(window.GIM_TS=window.GIM_TS||{})["Bava Metzia.3"]={"from":72,"a":[["\u0003והא טעמא\u0004 \u0005[והרי הטעם]\u0006 של \u0003ר' יוסי\u0004 שהוא עצמו מפרשו \u0003משום הפסד הרמאי הוא,\u0004 וכיון שאין הפסד ורמאי בדבר, בוודאי לא יודה ר' יוסי. \u0003אלא,\u0004 יש לומר כי \u0003תרוייהו לרבנן איצטריך\u0004 \u0005[שניהם הוצרכו\u0006 לשיטת \u0005חכמים]\u0006 ואף שהיה יכול לומר רק את הדין השני, הרי במשנה בסגנון \u0003לא זו אף זו קתני\u0004 \u0005[שנה],\u0006 שמתחיל בענין פשוט, ומוסיף דבר שיש בו חידוש יותר.","\u0003המפקיד פירות אצל חבירו, אפילו הן אבודין\u0004 על ידי ריקבון או מזיקים — \u0003לא יגע בהן,\u0004 שהרי אינן שלו. \u0003רבן שמעון בן גמליאל אומר: מוכרן בפני בית דין, מפני שהוא כמשיב אבידה לבעלים.\u0004 שהרי אם לא ימכור יאבד הפקדון, ובמכירתו נמצא מציל את רכוש חבירו.","ושואלים: \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 אמרו שלא יגע בהם? \u0003אמר רב כהנא:\u0004 כלל הוא, \u0003אדם רוצה בקב\u0004 תבואה \u0003שלו\u0004 יותר \u0003מתשעה קבים של חבירו.\u0004 וכיון שחביב על אדם דבר שלו, אין הוא רוצה שיחליפו אותו בשל אחרים, אפילו של אחרים מרובה יותר. ואילו \u0003רב נחמן בר יצחק אמר: חיישינן\u0004 \u0005[חוששים אנו]\u0006 \u0003שמא עשאן המפקיד תרומה ומעשר על מקום אחר,\u0004 ואם ימכרם יימצא הקונה משתמש בתרומות ומעשרות שלא כדין.","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 שנינו בברייתא: \u0003המפקיד פירות אצל חבירו\u0004 — \u0003הרי זה לא יגע בהן, לפיכך בעל הבית\u0004 (כלומר, המפקיד) \u0003עושה אותן תרומה ומעשר על מקום אחר,\u0004 שהרי הוא בטוח שהפירות במקומם. ומעתה, \u0003בשלמא\u0004 \u0005[נניח\u0006 לשיטת\u0005]\u0006 \u0003רב כהנא היינו דקתני\u0004 \u0005[הוא ששנה]\u0006 \u0003\"לפיכך\",\u0004 שיש טעם אחר לאיסור המכירה, ולפיכך יכול לעשותו תרומה.","\u0003אלא\u0004 לשיטת \u0003רב נחמן בר יצחק מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"לפיכך\"?\u0004 הלא לדעתו זה הוא טעם איסור המכירה! ומסבירים: \u0003הכי קאמר\u0004 \u0005[כך אמר],\u0006 כך יש להבין את הדברים: \u0003השתא דאמור רבנן\u0004 \u0005[עכשיו שאמרו חכמים]\u0006 ש\u0003לא נזבין\u0004 \u0005[ימכור],\u0006 משום \u0003דחיישינן\u0004 \u0005[שאנחנו חוששים]\u0006 שמא עשאן מעשר, \u0003לפיכך בעל הבית עושה אותן\u0004 אף לכתחילה \u0003תרומה ומעשר על מקום אחר.\u0004","\u0003אמר רבה בר בר חנה אמר ר' יוחנן: מחלוקת\u0004 שבמשנה היא כשנפחתים הפירות \u0003בכדי חסרונן,\u0004 כלומר, לפי השיעור המקובל של פחת, אבל אם אירע שפחתו \u0003יותר מכדי חסרונן\u0004 הרגיל — \u0003דברי הכל מוכרן בבית דין.\u0004","ומעירים: על דברי \u0003רב נחמן בר יצחק\u0004 — \u0003ודאי פליגא\u0004 \u0005[חולקת]\u0006 דעת ר' יוחנן, שהרי לגבי החשש שמא עשאן תרומות ומעשרות אין כל הבדל אם פחתו הרבה או מעט. ואולם, על שיטת \u0003רב כהנא מי לימא פליגא\u0004 \u0005[האם לומר שחלוקה]\u0006 דעת ר' יוחנן? ומשיבים: \u0003כי קאמר\u0004 \u0005[כאשר אמר]\u0006 \u0003רב כהנא\u0004 את דעתו — \u0003בכדי חסרונן קאמר\u0004 \u0005[אמר],\u0006 ומודה ביותר מזה.","ותוהים: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003רוצה\u0004 אדם \u0003בקב שלו\u0004 יותר \u0003מתשעה קבין של חבירו קאמר\u0004 \u0005[אמר],\u0006 משמע שאפילו היה החסרון אחד לתשע, עדיין רוצה אדם בשלו! ומשיבים: ביטוי \u0003גוזמא בעלמא\u0004 \u0005[הפרזה בלבד]\u0006 היה זה, ואין כוונתו לתשעה קבין ממש, אלא שאדם מוכן להפסיד קצת, כדי שיהיה ברשותו דבר שלו, אבל לא ביותר מכדי חסרון.","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 ממה ששנינו באותה ברייתא: \u0003לפיכך בעל הבית עושה אותן תרומה ומעשר על מקום אחר. וליחוש\u0004 \u0005[ושיחשוש]\u0006 בעל הבית \u0003דלמא הוו להו\u0004 \u0005[שמא היה להם]\u0006 פחת \u0003יותר מכדי חסרונן, וזבנינהו\u0004 \u0005[ומכרן]\u0006 השומר, ונמצא בעל הבית שהפריש את אלה כתרומות \u0003קא אכיל טבלים\u0004 \u0005[אוכל טבלים]!\u0006 ומשיבים: פחת \u0003יותר מכדי חסרונן לא שכיח\u0004 \u0005[אינו מצוי]\u0006 ובדבר שאינו מצוי לא גזרו חכמים.","וחוזרים ושואלים: \u0003ואי משתכחי\u0004 \u0005[ואם מוצאים]\u0006 שחסרה יותר מן הראוי \u0003מאי\u0004 \u0005[מה\u0006 עושים\u0005]\u0006 — האם \u0003מזבנינן להו\u0004 \u0005[מוכרים אותם]\u0006 לדעת ר' יוחנן, \u0003וליחוש\u0004 \u0005[ושיחשוש]\u0006 \u0003שמא\u0004 כבר \u0003עשאן בעל הבית תרומה ומעשר על מקום אחר!\u0004 ומשיבים: \u0003כי מזבנינן נמי\u0004 \u0005[כאשר מוכרים אנו אותן גם כן]\u0006 — \u0003לכהנים בדמי תרומה מזבנינן להו\u0004 \u0005[מוכרים אותם]\u0006 ולכן אין לחשוש, כי גם אם עשאן תרומה הרי יאכלו אותם הכהנים, ואין בכך כל רע.","ושואלים: \u0003ול\u0004דעת \u0003רב נחמן בר יצחק נמי\u0004 \u0005[גם כן]\u0006 כיון שיש עצה כזו, \u0003נזבנינהו\u0004 \u0005[נמכרם]\u0006 \u0003לכהנים בדמי תרומה?\u0004 ומשיבים: \u0003בהא פליגי\u0004 \u0005[\u0006בנושא \u0005זה חלוקים\u0006 הם\u0005],\u0006 ש\u0003רבה בר בר חנה סבר\u0004 \u0005[סבור]:\u0006 \u0003יותר מכדי חסרונן לא שכיח מידי\u0004 \u0005[מצוי הדבר\u0006 כלל\u0005]\u0006 \u0003וכי משתכח\u0004 \u0005[וכאשר נמצא]\u0006 מסתבר כי \u0003לקמיה\u0004 \u0005[לפני\u0006 שהיו\u0005],\u0006 כלומר, מעכשיו \u0003הוא דהויא\u0004 \u0005[שנהיה]\u0006 הפחת \u0003יתיר\u0004 \u0005[יותר]\u0006 \u0003מכדי חסרונן\u0004 ולא היה כן במשך כל הזמן. ולכן גם \u0003אי עביד להו\u0004 \u0005[אם עושה אותן]\u0006 \u0003בעל הבית תרומה ומעשר על מקום אחר,\u0004 מן הסתם \u0003מקמיה דהוו להו\u0004 \u0005[לפני שהיו\u0006 שפחתו \u0005להם]\u0006 \u0003יותר מכדי חסרונן עביד להו\u0004 \u0005[עשה אותן],\u0006 \u0003הלכך\u0004 \u0005[על כן],\u0006 \u0003כי הוו להו\u0004 \u0005[כאשר היו]\u0006 פוחתים \u0003יותר מכדי חסרונן\u0004 — \u0003נזבנינהו\u0004 \u0005[נמכרם]\u0006 \u0003לכהנים בדמי תרומה, ו\u0004אילו","\u0003רב נחמן בר יצחק סבר\u0004 \u0005[סבור]:\u0006 \u0003יתר מכדי חסרונן משכח שכיח\u0004 \u0005[מצוי הוא]\u0006 \u0003וכי הוו להו\u0004 \u0005[וכאשר היה להם]\u0006 הפחת — \u0003לאלתר\u0004 \u0005[מיד]\u0006 \u0003הוא דהוו להו\u0004 \u0005[שהיה להם]\u0006 ומבחין המחזיק מיד בדבר. \u0003ואי אמרת נזבנינהו\u0004 \u0005[ואם אומר אתה שנמכרם]\u0006 אם כן יש לחשוש כי \u0003זימנין דקדים ומזבין להו\u0004 \u0005[פעמים שמקדים ומוכר אותם],\u0006 \u0003וכי עביד להו\u0004 \u0005[וכאשר עושה אותם]\u0006 \u0003בעל הבית תרומה ומעשר על מקום אחר\u0004 — \u0003לא ידע דזבנא\u0004 \u0005[ש\u0006כבר \u0005מכר]\u0006 השומר את הפירות, ונמצא שבעל הבית \u0003קא אכיל\u0004 \u0005[אוכל]\u0006 \u0003טבלים.\u0004","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 ממה ששנינו בברייתא: \u0003המפקיד פירות אצל חבירו והרקיבו, יין והחמיץ, שמן והבאיש\u0004 (הסריח), \u0003דבש והדביש\u0004 (התקלקל) — \u0003הרי זה לא יגע בהן,\u0004 אלו \u0003דברי ר' מאיר. וחכמים אומרים: עושה להם תקנה, ומוכרן בבית דין.\u0004 ומעירים בברייתא: \u0003וכשהוא מוכרן\u0004 — \u0003מוכרן לאחרים ואינו מוכרן לעצמו,\u0004 גם אם הוא מוכן לשלם אותו מחיר, כדי שלא יחשדוהו שמא מכר לעצמו בזול.","ומטעם זה של התרחקות מן החשד אמרו \u0003כיוצא בו: גבאי צדקה בזמן שאין להם עניים לחלק\u0004 להם את הפרוטות שאספו — \u0003פורטין\u0004 את כספי הצדקה שקיבלו במטבעות כסף גדולות יותר \u0003לאחרים,\u0004 \u0003ואין פורטין לעצמן\u0004 שלא ייחשדו. וכן \u0003גבאי תמחוי,\u0004 הגובים מאכלים מוכנים ומאכילים אותם לעניים, \u0003בזמן שאין להם עניים לחלק\u0004 — \u0003מוכרין\u0004 מן התמחוי \u0003לאחרים ואין מוכרין לעצמן.\u0004","ולעניננו, \u0003קתני מיהת\u0004 \u0005[שנה על כל פנים]\u0006 \u0003פירות והרקיבו, מאי לאו\u0004 \u0005[האם לא]\u0006 נבין מכאן שהרקיבו כולם, \u0003אפילו יתר מכדי חסרונן!\u0004 ודוחים: \u0003לא,\u0004 הכוונה היא \u0003בכדי חסרונן\u0004 בלבד, ומקשים: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003יין והחמיץ, שמן והבאיש, דבש והדביש\u0004 ש\u0003יתר מכדי חסרונן נינהו\u0004 \u0005[הם],\u0006 שהרי יש הבדל גדול במחיר בין יין וחומץ, שמן טוב ושמן שהבאיש! ודוחים: משם אין להוכיח כי \u0003שאני הני\u0004 \u0005[שונים\u0006 \u0003אלה]\u0004 \u0003כיון דקם\u0004 \u0005[שעמד]\u0006 בקלקול — \u0003קם\u0004 \u0005[עומד],\u0006 כלומר, אמנם הקלקול הוא גדול מאד, אבל איננו מוסיף והולך ואם כבר החמץ היין כבר החמיץ הוא, ואיננו מתקלקל הרבה יותר, ומעתה אין סיבה למהר למכרו.","אגב כך שואלים: \u0003שמן והבאיש, דבש והדביש\u0004"],["\u0003למאי חזו\u0004 \u0005[למה\u0006 הם \u0005ראויים],\u0006 שהרי אמרנו שמוכר אותם, ולכאורה הרי אינם ראויים לכלום! ומסבירים: ה\u0003שמן חזי לגלדאי\u0004 \u0005[ראוי למעבדי עורות],\u0006 שמושחים עורות בשמן, ולא איכפת להם אם ריחו רע. \u0003דבש\u0004 ראוי \u0003לכתישא דגמלי\u0004 \u0005[לפצעים שבגב הגמל]\u0006 שמשמש כרפואה.","שנינו בברייתא ש\u0003חכמים אומרים: עושה להם תקנה ומוכרן בבית דין.\u0004 ושואלים: \u0003מאי תקנתא עביד להו\u0004 \u0005[איזו תקנה עושה להם]?\u0006 \u0003אמר רב אשי:\u0004 הכוונה היא תקנה \u0003לקנקנים,\u0004 שאם כי התוכן שהתקלקל אין לו תקנה, אולם אם ישהה את הפקדון אף הקנקנין עצמם יבאישו.","ושואלים: כיון שר' מאיר מודה שבחסרון מרובה מוכר, אם כן \u0003במאי מיפלגי\u0004 \u0005[במה נחלקו\u0006 איפוא\u0005]\u0006 ר' מאיר וחכמים? ומשיבים: בשאלה זו, \u0003דמר סבר\u0004 \u0005[שחכם זה,\u0006 ר' מאיר, \u0005סבור]:\u0006 \u0003להפסד מרובה\u0004 — \u0003חששו, להפסד מועט\u0004 של הקנקנים — \u0003לא חששו, ומר סבר\u0004 \u0005[וחכם זה,\u0006 חכמים, \u0005סבור]\u0006 \u0003אפילו להפסד מועט נמי\u0004 \u0005[גם כן]\u0006 \u0003חששו,\u0004 ולכן מוכר את מה שהתקלקל כדי שלא יפגמו אף בקנקנים.","שנינו במשנתנו ש\u0003רבן שמעון בן גמליאל אומר\u0004 שהשומר על פירות חבירו והן אבודים \u0003ימכרם בבית דין מפני שהוא כמשיב אבידה לבעלים. אתמר\u0004 \u0005[נאמר]\u0006 ש\u0003ר' אבא בר יעקב אמר\u0004 בשם \u0003ר' יוחנן: הלכה כרבן שמעון בן גמליאל, ורבא אמר\u0004 בשם \u0003רב נחמן: הלכה כדברי חכמים.\u0004","ושואלים: לשם מה צריך ר' יוחנן לפסוק הלכה זו, \u0003והא\u0004 \u0005[והרי]\u0006 כבר \u0003אמרה ר' יוחנן חדא זמנא\u0004 \u0005[פעם אחת]\u0006 בדרך כללית, ש\u0003אמר רבה בר בר חנה אמר ר' יוחנן: כל מקום ששנה רבן שמעון בן גמליאל במשנתינו הלכה כמותו, חוץ\u0004 משלושה מקרים: בדין \u0003ערב,\u0004 בענין של \u0003צידן\u0004 בגיטין, ובענין \u0003ראיה\u0004 במחלוקת \u0003אחרונה\u0004 (ולא בראשונה, ששם הלכה כמותו).","ומשיבים: \u0003אמוראי נינהו\u0004 \u0005[\u0006מחלוקת \u0005אמוראים היא]\u0006 ושניהם \u0003אליבא\u0004 \u0005[על פי שיטתו]\u0006 של \u0003ר' יוחנן,\u0004 שלדעת רבה בר בר חנה קבע ר' יוחנן הלכה כללית, ולשיטת ר' אבא יש כאן רק פסק במקום הזה.","ומעירים: \u0003מד\u0004 ברי \u0003רבן שמעון בן גמליאל נשמע\u0004 (נלמד) ש\u0003מורידין קרוב,\u0004 כלומר, מרשים לו לבוא ולטפל \u0003לנכסי שבוי,\u0004 שאדם שנשבה הרי אין מי שיטפל בנכסיו, וכיון שהוא חי עדיין — אין קרוביו יורשים אותו, ולכן כדי שלא יהיה הפסד מרובה, ממנים (\"מורידין\") את אחד הקרובים שיטפל בנכסים כדי שלא יפסדו. ואילו \u0003מדרבנן\u0004 \u0005[מדברי חכמים]\u0006 \u0003נשמע\u0004 ש\u0003אין מורידין קרוב לנכסי שבוי.\u0004","את ההשוואה הזו דוחים: \u0003וממאי\u0004 \u0005[וממה]\u0006 מוכיח אתה? \u0003דלמא\u0004 \u0005[שמא]\u0006 \u0003עד כאן לא\u0004 שמענו כי \u0003קאמר\u0004 \u0005[אמר]\u0006 \u0003רבן שמעון בן גמליאל הכא\u0004 \u0005[כאן]\u0006 — \u0003אלא משום דקא כליא קרנא\u0004 \u0005[שהקרן,\u0006 גוף הפירות עצמם, \u0005כלה],\u0006 \u0003אבל התם הכי נמי\u0004 \u0005[שם כך גם כן\u0006 יודה\u0005]\u0006 ש\u0003אין מורידין,\u0004 שהרי גוף הקרקעות איננו כלה אם אין מטפלים בהן. \u0003ו\u0004להיפך, \u0003עד כאן לא\u0004 שמענו כי \u0003קאמרי רבנן הכא\u0004 \u0005[אמרו חכמים כאן]\u0006 שאין מוכרים פקדון, \u0003אלא אי\u0004 \u0005[אי]\u0006 מן הטעם של \u0003רב כהנא\u0004 שאדם רוצה בשלו, \u0003אי\u0004 \u0005[או]\u0006 מטעמו של \u0003רב נחמן בר יצחק\u0004 מחשש שמא יפרישו עליהם תרומות. \u0003אבל התם\u0004 \u0005[שם]\u0006 בקרקעות \u0003הכי נמי\u0004 \u0005[כך גם כן]\u0006 יהיה הדין ש\u0003מורידין,\u0004 שהרי אין מקום לחשש.","ושואלים: \u0003למימרא דתרי טעמי נינהו\u0004 \u0005[האם לומר\u0006 מכאן \u0005ששני טעמים הם],\u0006 כלומר, שני הנושאים אין קשר ביניהם? \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רב יהודה אמר שמואל: הלכה כרבן שמעון בן גמליאל, ואמר שמואל: מורידין קרוב לנכסי שבוי. לאו\u0004 \u0005[האם לא]\u0006 \u0003משום דחד טעמא\u0004 \u0005[שטעם אחד]\u0006 \u0003הוא\u0004 לשתי ההלכות? ודוחים: \u0003לא, תרי טעמי נינהו\u0004 \u0005[שני טעמים הם]\u0006 ופסק שמואל הלכה בשני המקרים, אבל אין קשר מהותי ביניהם.","ומעירים: \u0003הכי נמי מסתברא\u0004 \u0005[כך גם כן מסתבר]\u0006 לומר שאין הדברים קשורים זה בזה, ש\u0003אמר רבא אמר רב נחמן: הלכה כדברי חכמים,\u0004 ויודעים אנו כי \u0003אמר רב נחמן: מורידין קרוב לנכסי שבוי. אלא שמע מינה\u0004 \u0005[למד מכאן]:\u0006 כי \u0003תרי טעמי נינהו\u0004 \u0005[שני טעמים הם]\u0006 ואין קשר ביניהם, ומסכמים: אכן, \u0003שמע מינה.\u0004","לגופו של הענין מביאים, \u0003אתמר\u0004 \u0005[נאמר]\u0006 שחלקו אמוראים בשאלה \u0003שבוי שנשבה, רב אמר: אין מורידין קרוב לנכסיו, שמואל אמר: מורידין קרוב לנכסיו,\u0004 ומסייגים את המחלוקת:","\u0003כששמעו בו שמת\u0004 — \u0003כולי עלמא לא פליגי\u0004 \u0005[הכל אינם חולקים]\u0006 ש\u0003מורידין,\u0004 שהרי הקרוב שהוא מקבל את הנכסים בירושה יטפל בהם כבשלו, ואם יתברר שהיתה זו טעות — יחזיר לקרוב את הוצאותיו.","\u0003כי פליגי\u0004 \u0005[כאשר נחלקו]\u0006 — הרי זה \u0003בשלא שמעו בו שמת,\u0004 וסוברים שעדיין חי הוא וסופו לחזור. \u0003רב אמר: אין מורידין\u0004 קרוב לנכסים \u0003דלמא מפסיד להו\u0004 \u0005[שמא יפסיד\u0006 אותם\u0005],\u0006 שכיון שהוא משער שבעל הנכסים חי עדיין, הרי יצטרך להחזיר לו את נכסיו, ולכן איננו דואג לעבדם כראוי, והוא רק מנסה לנצל את השדה ככל האפשר. \u0003ושמואל אמר: מורידין, כיון\u0004 ש\u0003אמר מר\u0004 \u0005[החכם]\u0006 שבכל מקרה שנתברר שאדם עיבד שדה שאינו שלו \u0003שיימינן להו\u0004 \u0005[שמים,\u0006 מעריכים \u0005אנו אותה,\u0006 את עבודתו\u0005]\u0006 \u0003כ\u0004אילו היה \u0003אריס, ו\u0004אם כן ודאי שהוא \u0003לא מפסיד להו\u0004 \u0005[אותם,\u0006 את הנכסים\u0005]\u0006 שהרי בכל מקרה יש לו שכר.","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על כך ממה ששנינו בברייתא, \u0003ר' אליעזר אומר: ממשמע שנאמר \"וחרה אפי והרגתי אתכם\"\u0004 (שמות כב, כג) הלא \u0003יודע אני\u0004 שאם הם מתים ממילא \u0003נשותיהם\u0004 \u0003אלמנות ובניהם יתומים,\u0004 \u0003אלא מה תלמוד לומר\u0004 בסופו של הפסוק \u0003\"והיו נשיכם אלמנות ובניכם יתומים\"\u0004 הרי זה עונש נוסף, שאותם אנשים יהרגו ולא תהא עדות על כך, ומשום כך","\u0003נשותיהם מבקשות לינשא ואין מניחין אותן\u0004 בהעדר עדים, \u0003ובניהן רוצים לירד לנכסי אביהן\u0004 לרשתם \u0003ואין מניחין אותן.\u0004 ומכאן לכאורה ראיה שאין מורידין קרוב לנכסי מי שלא התברר מותו! \u0003אמר רבא:\u0004 הכוונה איננה לירד ולעבד את השדה, אלא \u0003לירד ולמכור\u0004 את השדה \u0003תנן\u0004 \u0005[שנינו].\u0006","ומספרים: \u0003הוה עובדא\u0004 \u0005[היה\u0006 \u0003מעשה]\u0004 מעין זה \u0003ב\u0004עיר \u0003נהרדעא\u0004 \u0003ופשטה\u0004 \u0005[ופתר אותה]\u0006 את הבעיה \u0003רב ששת מהא מתניתא\u0004 \u0005[מן הברייתא הזו]\u0006 לאיסור, ו\u0003אמר לו רב עמרם: דלמא\u0004 \u0005[שמא]\u0006 \u0003לירד ולמכור תנן\u0004 \u0005[שנינו]?\u0006 \u0003אמר\u0004 לו רב ששת: בלעג, באותו סגנון: \u0003דלמא\u0004 \u0005[שמא]\u0006 \u0003מ\u0004אנשי \u0003פומבדיתא את\u0004 \u0005[אתה],\u0006 \u0003דמעיילין פילא בקופא דמחטא\u0004 \u0005[שמכניסים פיל בחור המחט],\u0006 כלומר, רואים בך שאתה מאלה שמתפלפלים בלא בסיס נכון, \u0003והא דומיא\u0004 \u0005[והרי בדומה]\u0006 ל\u0003נשותיהם ובניהם קתני\u0004 \u0005[שנה],\u0006 \u0003מה התם\u0004 \u0005[מה שם]\u0006 הכוונה היא ש\u0003כלל לא\u0004 יינשאו הנשים, \u0003אף הכא נמי\u0004 \u0005[כאן גם כן]\u0006 הכוונה היא ש\u0003כלל לא\u0004 מורידים.","ומעירים: שאלה זו אם \u0003מורידין קרוב לנכסי שבוי תנאי\u0004 \u0005[\u0006מחלוקת \u0005תנאי]\u0006 \u0003היא,\u0004 \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003היורד לנכסי שבוי\u0004 ומעבד את השדה — \u0003אין מוציאין אותו מידו, ולא עוד אלא, אפילו שמע שממשמשין\u0004 (מתקרבים) \u0003ובאין\u0004 בעלי השדה, \u0003וקדם\u0004 המחזיק \u0003ותלש ואכל\u0004 את הפירות של אותה שנה \u0003הרי זה זריז ונשכר,\u0004 שהרי קבל תמורה על העבודה שעבד. \u0003ואלו הן נכסי שבויין\u0004 — \u0003הרי שהיה אביו או אחיו או אחד מן המורישין\u0004 (שהוא יורשו), \u0003הלכו להם\u0004 אלה \u0003למדינת הים, ושמעו בהן שמת.\u0004","אולם \u0003היורד לנכסי נטושים\u0004 — \u0003מוציאין אותו מידו. ואלו הן נכסי נטושים\u0004 — \u0003הרי שהיה אביו או אחיו או אחד מן המורישין, הלכו להם למדינת הים ולא שמעו בהם שמת. ואמר רבן שמעון בן גמליאל: שמעתי שהנטושים כשבויין.\u0004 הרי שכבר נחלקו תנא קמא ורבן שמעון בן גמליאל כמחלוקת רב ושמואל.","ועוד דין בברייתא: \u0003היורד לנכסי רטושים\u0004 — \u0003מוציאין אותו מידו. ואלו הן נכסי רטושים\u0004 — \u0003הרי שהיה אביו או אחיו או אחד מן המורישים\u0004 קודם לכן \u0003כאן, ואינו יודע להיכן הלכו.\u0004 שבמקרה כזה הכל מודים שאין לקרובים זכות להיכנס לשדה.","כיון שהוזכרו המונחים \"נטושים ורטושים\" שעיקר משמעותם \"עזובים\", שואלים: \u0003מאי שנא הנך דקרו להו\u0004 \u0005[מה שונים אלה,\u0006 של שבוי, \u0005שקוראים אותם]\u0006 \u0003\"נטושים\",\u0004 \u0003ומאי שנא הני\u0004 \u0005[ובמה שונים אלה]\u0006 של אדם שנעלם \u0003דקרו להו\u0004 \u0005[שקוראים אותם]\u0006 \u0003\"רטושים\"?\u0004"],["ומסבירים: \u0003\"נטושים\"\u0004 פירושו נכסים שנעזבו \u0003בעל כרחם\u0004 של הבעלים, כמו שנאמר \u0003\"והשביעת תשמטנה ונטשתה\"\u0004 (שמות כג, יא), שיש כאן \u0003אפקעתא דמלכא\u0004 \u0005[הפקעה\u0006 מטעם \u0005המלך]\u0006 הקדוש ברוך הוא, המצוה לעזוב את הנכסים — זו קרויה \"נטישה\", בעל כרחו. \u0003\"רטושים\"\u0004 פירושו עזיבת נכסים \u0003מדעתן\u0004 של העוזבים, \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 \u0003\"אם על בנים רטשה\"\u0004 (הושע י, יד), שמפרש שהאם על הבנים נעזבה, משום שהגברים ברחו להם.","\u0003תנא\u0004 \u0005[שנה\u0006 החכם\u0005]\u0006 על אותה משנה: \u0003וכולם שמין להם כאריס.\u0004 ושואלים: \u0003אהייא\u0004 \u0005[על איזה\u0006 חלק מן הברייתא\u0005]\u0006 מוסבת הערה זו? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 על \u0003שבויין, השתא\u0004 \u0005[הרי]\u0006 \u0003זריז ונשכר הוה\u0004 \u0005[הוא],\u0006 שהרי רשאי לתלוש כמה פירות שיכול, \u0003מאי דאשבח מיבעיא\u0004 \u0005[את מה שהשביח נצרכה לומר]\u0006 שיכול לקחת? \u0003אלא\u0004 תאמר שמדובר ב\u0003רטושים\u0004 — \u0003והא\u0004 \u0005[והרי]\u0006 \u0003\"מוציאין אותן מידו\" קתני\u0004 \u0005[שנה],\u0006 ואם כן אינו נדון כאריס!","\u0003אלא\u0004 תפרש זאת על \u0003נטושים.\u0004 ונברר, \u0003למאן\u0004 \u0005[\u0006לשיטת \u0005מי]?\u0006 \u0003אילימא לרבנן\u0004 \u0005[אם תאמר\u0006 לשיטת \u0005חכמים]\u0006 \u0003הא אמרי\u0004 \u0005[הרי אומרים\u0006 הם\u0005]\u0006 כי \u0003מוציאין אותו מידו. אי\u0004 \u0005[\u0006ו\u0005אם]\u0006 לדעת \u0003רבן שמעון בן גמליאל\u0004 — \u0003הא\u0004 \u0005[הרי]\u0006 הוא \u0003אמר\u0004 \u0003שמעתי שהנטושים\u0004 דינם \u0003כשבויין\u0004 ואם כן עדיף הוא מאריס!","ומשיבים: לדעת רבן שמעון בן גמליאל דינם \u0003כשבויין,\u0004 אבל לא \u0003שבויין\u0004 ממש לכל ענין. כלומר, \u0003כשבויין\u0004 לענין זה ש\u0003אין מוציאין אותן מידו,\u0004 אבל \u0003לא שבויין\u0004 ממש, ש\u0003אילו התם\u0004 \u0005[שם,\u0006 בשבויים\u0005]\u0006 המחזיק הוא \u0003זריז ונשכר\u0004 במה שהוא לוקח, \u0003ואילו הכא שיימינן ליה\u0004 \u0005[כאן שמים,\u0006 מעריכים \u0005אנו אותו]\u0006 \u0003כ\u0004אילו היה \u0003אריס.\u0004","ושואלים: \u0003ומאי שנא מהא דתנן\u0004 \u0005[ובמה שונה\u0006 הדבר \u0005מזו ששנינו\u0006 במשנה\u0005]:\u0006 \u0003המוציא הוצאות על נכסי אשתו\u0004 שהם נכסי מלוג שלה, וגירשה או מת, וחוזרים הנכסים אליה, \u0003הוציא הרבה\u0004 הוצאות \u0003ואכל קימעא\u0004 \u0005[מעט]\u0006 שלא הספיק ליהנות מהשבחת הנכסים, או הוציא \u0003קימעא ואכל הרבה,\u0004 כלל הוא: \u0003מה שהוציא\u0004 — \u0003הוציא, ומה שאכל\u0004 — \u0003אכל,\u0004 ואין עושים אתו חשבון.","ומשיבים: \u0003הא לא דמיא\u0004 \u0005[זה אינו דומה]\u0006 \u0003אלא להא\u0004 \u0005[ל\u0006מקרה \u0005זה]\u0006 ששנינו: \u0003המוציא הוצאות על נכסי אשתו קטנה\u0004 שהיתה יתומה והשיאוה אחיה ואמה שנישואיו עמה אינם מדין תורה, אלא מתקנת חכמים (והיא יכולה להפקיעם במיאון) — \u0003הרי זה\u0004 \u0003כמוציא\u0004 הוצאות על \u0003נכסי אחר דמי\u0004 \u0005[נחשב],\u0006 שמחזירים לו את הוצאותיו. והטעם הוא: \u0003אלמא, כיון דלא סמכא דעתיה\u0004 \u0005[שאין דעתו סומכת]\u0006 שנכסיה ישארו ברשותו \u0003תקינו ליה רבנן כי היכי\u0004 \u0005[\u0006\u0005תקנו לו חכמים\u0006 שיקבל את \u0005כל הוצאותיו כדי]\u0006 ש\u0003לא לפסדינהו\u0004 \u0005[יפסיד אותם,\u0006 את הנכסים\u0005],\u0006 \u0003הכא נמי תקינו ליה רבנן כי היכי דלא לפסדינהו\u0004 \u0005[כאן גם כן תקנו לו חכמים\u0006 שיקבל חשבון עבודתו \u0005כדי שלא יפסיד אותם].\u0006","ושואלים: למדנו בברייתא \u0003וכולן שמין להם כאריס\u0004 — הלשון \u0003\"וכולן\" לאיתויי מאי\u0004 \u0005[להביא את מה]\u0006 עוד, שהרי נראה שלא במקרה אחד בלבד מדובר!","ומשיבים: \u0003לאיתויי הא\u0004 \u0005[להביא זו]\u0006 ש\u0003אמר רב נחמן אמר שמואל: שבוי שנשבה\u0004 — \u0003מורידין קרוב לנכסיו, יצא לדעת\u0004 — \u0003אין מורידין קרוב לנכסיו. ורב נחמן דידיה\u0004 \u0005[משלו]\u0006 \u0003אמר:\u0004 \u0003בורח הרי הוא כשבוי.\u0004 ושואלים: \u0003בורח מחמת מאי\u0004 \u0005[מה],\u0006 מאיזה טעם ברח? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 שברח \u0003מחמת כרגא\u0004 \u0005[מיסים]\u0006 שאינו יכול או אינו רוצה לשלם — \u0003היינו\u0004 \u0005[הרי זה]\u0006 אדם שיצא \u0003לדעת,\u0004 שהרי שקל בדעתו והחליט שהוא יוצא, \u0003אלא\u0004 הכוונה היא \u0003בורח מחמת\u0004 אשמת \u0003מרדין\u0004 \u0005[רצח]\u0006 שהוא בורח בעל כרחו, ולכן דינו כשבוי.","\u0003אמר רב יהודה אמר שמואל: שבוי שנשבה והניח\u0004 בשדהו \u0003קמה לקצור,\u0004 או \u0003ענבים לבצור,\u0004 או \u0003תמרים לגדור,\u0004 או \u0003זיתים למסוק,\u0004 ויהיה הפסד מרובה אם לא יטפלו בהם — \u0003בית דין יורדין לנכסיו ומעמידין אפוטרופוס\u0004 על הנכסים, והוא \u0003קוצר ובוצר וגודר ומוסק, ואחר כך מורידין קרוב לנכסיו\u0004 שימשיך לעבד את השדה. ושואלים: אם יש תקנה כזו על ידי אפוטרופוס, \u0003ולוקים אפוטרופא\u0004 \u0005[ושיעמידו אפוטרופוס]\u0006 \u0003לעולם\u0004 מטעם בית הדין! ומשיבים: \u0003אפוטרופא לדיקנני לא מוקמינן\u0004 \u0005[אפוטרופוס לבעלי זקן אין מעמידין],\u0006 כלומר, אין מעמידים בקביעות אפוטרופוס לאנשים מבוגרים, ואין מינוי אפוטרופוס אלא לפי שעה כגון ליתומים, ולא למבוגרים.","\u0003אמר רב הונא: אין מורידין\u0004 יורש \u0003קטן לנכסי שבוי, ולא\u0004 מורידים \u0003קרוב\u0004 הראוי לרשת \u0003לנכסי קטן\u0004 שאין מי שיעבדם. ויותר מכן: אף אין מורידין \u0003קרוב מחמת קרוב\u0004 (קרובו של קרוב) \u0003לנכסי קטן.\u0004","ומסבירים את טעם הדברים: \u0003אין מורידין קטן לנכסי שבוי\u0004 — \u0003דלמא מפסיד להו\u0004 \u0005[שמא יפסיד אותם],\u0006 שכיון שקטן הוא אינו יודע לטפל בנכסים כראוי. \u0003ולא\u0004 מורידין \u0003קרוב מחמת קרוב לנכסי קטן,\u0004 מדובר \u0003באחי מאימא\u0004 \u0005[באחים מן האם]\u0006 שאם יש לו לקטן אח למחצה מאביו, ואותו אח יש לו אח מאמו, אף שאותו אדם אינו קרוב כלל לקטן — יש אפשרות שיטען שירש את הנכס מאחיו. \u0003ולא קרוב לנכסי קטן\u0004 מפני החשש: \u0003כיון דלא מחי, אתי לאחזוקי ביה\u0004 \u0005[כיון שאין\u0006 הקטן \u0005מוחה\u0006 בזמן הראוי שהנכסים אינם של הקרוב לו, \u0005יבוא להחזיק בהם]\u0006 כאילו היו שלו.","\u0003אמר רבא: שמע מיניה\u0004 \u0005[למד ממנו]\u0006 \u0003מ\u0004דברי \u0003רב הונא\u0004 ש\u0003אין מחזיקין בנכסי קטן.\u0004 כלומר, שגם אדם שהחזיק והשתמש בנכסי קטן במשך שלוש שנים בפני הקטן — אין זו הוכחה לענין דיני חזקה שנכסים אלה שלו הם, שכן רב הונא לא הקפיד אלא בקרובים, ולא אמר שאיש אחר לא ירד לנכסי קטן, משמע שבאיש זר שאין לו טענת ירושה אין חוששים — כיון שאין לו חזקה."],["\u0003ואפילו הגדיל\u0004 הקטן אחר כך — אין זו חזקה, שמא לא ידע הקטן מעולם שהיו שלו.","ומעירים: \u0003ולא אמרן\u0004 \u0005[אמרנו]\u0006 שאין מורידין קרוב לנכסי קטן \u0003אלא באחי דאבא\u0004 \u0005[באחים מן האב]\u0006 שהם קרובים שיכולים לרשת אותו, \u0003אבל באחי דאמא לית לן\u0004 \u0005[באחים מן האם אין לנו]\u0006 \u0003בה\u0004 חשש, שכן אין להם צד ירושה. \u0003ואחי דאבא נמי\u0004 \u0005[ובאחים מן האב גם כן]\u0006 \u0003לא אמרן\u0004 \u0005[אמרנו]\u0006 \u0003אלא בארעתא\u0004 \u0005[בקרקעות],\u0006 \u0003אבל בבתי לית לן\u0004 \u0005[בבתים אין לנו]\u0006 \u0003בה\u0004 חשש, לפי שיש שכנים והם יכולים להעיד שהבתים לא היו שלהם. \u0003ובארעתא נמי\u0004 \u0005[ובקרקע גם כן]\u0006 \u0003לא אמרן\u0004 \u0005[אמרנו]\u0006 \u0003אלא\u0004 כש\u0003לא עביד עיטדא\u0004 \u0005[עשה שטר חלוקה\u0006 מפורש\u0005],\u0006 \u0003אבל\u0004 כאשר \u0003עביד עיטדא\u0004 \u0005[עשה שטר חלוקה]\u0006 — \u0003קלא אית לה\u0004 \u0005[קול יש לכך],\u0006 כלומר, השמועה יוצאת, והכל יודעים מה חלקו של כל אחד מן האחים.","ואולם מסכמים: \u0003ולא היא\u0004 \u0005[ואינו כן]\u0006 כלומר, אין נוהגים כפי שאמרנו, אלא \u0003לא שנא אחי דאבא ולא שנא אחי דאמא\u0004 \u0005[אינו שונה אחים מאב ואינו שונה אחים מן האם],\u0006 \u0003לא שנא ארעתא ולא שנא בתי\u0004 \u0005[אינו שונה בקרקעות ואינו שונה בבתים],\u0006 \u0003ולא שנא עביד עיטדא לא שנא לא עביד עיטדא\u0004 \u0005[ואינו שונה אם עשה שטר חלוקה אינו שונה אם לא עשה שטר חלוקה]\u0006 — \u0003לא מחתינן\u0004 \u0005[אין אנו מורידין]\u0006 קרוב לנכסי קטן, כדי שלא להגיע לידי חשש.","מסופר: \u0003ההיא סבתא דהויא\u0004 \u0005[זקנה אחת שהיו]\u0006 \u0003לה תלת בנתא\u0004 \u0005[שלוש בנות].\u0006 \u0003אישתבאי איהי וחדא ברתא\u0004 \u0005[נשבתה היא ובת אחת].\u0006 \u0003אידך תרתי בנתא שכיבא חדא מינייהו ושבקה ינוקא\u0004 \u0005[\u0006ו\u0005משתי הבנות\u0006 האחרות \u0005מתה אחת מהן והניחה תינוק].\u0006 \u0003אמר אביי: היכי נעביד\u0004 \u0005[כיצד נעשה]\u0006 בענין זה? אם \u0003לוקמינהו לנכסי בידא דאחתא\u0004 \u0005[נעמיד את הנכסים בידי האחות\u0006 הנותרת\u0005]\u0006 יש לחשוש \u0003דלמא שכיבא סבתא\u0004 \u0005[שמא\u0006 כבר \u0005מתה הזקנה]\u0006 \u0003ו\u0004הלא \u0003אין מורידין קרוב לנכסי קטן,\u0004 שהרי אם מתה הזקנה ירש הקטן שליש מנכסיה ואין מורידין קרוב לנכסי קטן. ואולם אם \u0003נוקמינהו לנכסיה בידא דינוקא\u0004 \u0005[נעמיד את\u0006 חלק \u0005הנכסים בידי הקטן]\u0006 \u0003דלמא\u0004 \u0005[שמא]\u0006 \u0003לא שכיבא\u0004 \u0005[מתה]\u0006 ה\u0003סבתא\u0004 וכלל הוא: \u0003אין מורידין קטן לנכסי שבוי!\u0004","\u0003אמר אביי: הלכך\u0004 \u0005[על כן],\u0006 \u0003פלגא יהבינא\u0004 \u0005[חצי\u0006 הנכסים \u0005נותנים]\u0006 \u0003לה לאחתא\u0004 \u0005[לאחות]\u0006 שאם מתו שתי השבויות הרי זו יורשת חצי הנכסים, ואם לא מתו — הרי מורידים קרוב לנכסי שבוי. \u0003ואידך פלגא מוקמינן ליה אפוטרופא לינוקא\u0004 \u0005[ולחצי האחר מעמידין אפוטרופוס עבור הקטן],\u0006 שהרי יתכן שהוא ירש את חצי הנכסים. \u0003רבא אמר: מגו דמוקמינן אפוטרופא לפלגא, מוקמינן ליה אפוטרופא לאידך פלגא\u0004 \u0005[מתוך שאנו מעמידין אפוטרופוס לחצי, מעמידין אפוטרופוס לחצי האחר]\u0006 ויהיו כל הנכסים בידי אפוטרופוס, עד שיתבררו הדברים.","\u0003לסוף שמעו דשכיבא\u0004 \u0005[שמתה]\u0006 אותה \u0003סבתא\u0004 ולא שמעו מה אירע לה לבת השבויה. \u0003אמר אביי: תילתא יהבינן\u0004 \u0005[שליש\u0006 מן הנכסים \u0005נותנים אנו]\u0006 \u0003לה לאחתא\u0004 \u0005[לאחות\u0006 החיה\u0005],\u0006 \u0003ותילתא יהבינן ליה לינוקא\u0004 \u0005[ושליש נותנים לתינוק],\u0006 שהרי הוא יורש (על ידי אמו שמתה) את סבתו. \u0003ואידך תילתא\u0004 \u0005[והשליש האחר]\u0006 של האחות השבויה שאין יודעים מה עלה בגורלה, \u0003יהבינן דנקא לאחתא\u0004 \u0005[נותנים ששית,\u0006 חצי השליש, \u0005לאחות]\u0006 \u0003ואידך דנקא מוקמינן ליה אפוטרופא לינוקא\u0004 \u0005[ולששית האחרת מעמידין אפוטרופוס לתינוק]\u0006 שמא מתה האחות ונכס זה הוא שלו. \u0003רבא אמר: מגו דמוקים אפוטרופא לדנקא מוקמינן נמי אפוטרופא לאידך דנקא\u0004 \u0005[מתוך שמעמיד אפוטרופוס לשישית מעמידין גם כן אפוטרופוס לששית האחרת]\u0006 עד שיתברר מה עלה בגורל האחות.","מסופר: \u0003מרי בר איסק\u0004 שהיה איש עשיר ותקיף \u0003אתא ליה אחא\u0004 \u0005[בא לו אח]\u0006 שלא הכיר \u0003מבי חוזאי\u0004 שהוא מקום רחוק מבבל. \u0003אמר ליה\u0004 \u0005[אמר לו]\u0006: \u0003פלוג\u0004 \u0005[חלוק]\u0006 \u0003לי\u0004 בנכסים שהרי אני אחיך. \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003לא ידענא לך\u0004 \u0005[אין אני מכיר אותך]\u0006 ואינני יודע מי אתה.","\u0003אתא לקמיה\u0004 \u0005[בא\u0006 הדין \u0005לפני]\u0006 \u0003רב חסדא. אמר\u0004 לו לתובע: \u0003שפיר קאמר\u0004 \u0005[יפה אמר]\u0006 \u0003לך\u0004 מרי בר איסק, \u0003שנאמר: \"ויכר יוסף את אחיו והם לא הכרהו\"\u0004 (בראשית מב, ח), ומסבירים כיצד יכול היה דבר זה לקרות — \u0003מלמד שיצא\u0004 מהם \u0003בלא חתימת זקן ובא בחתימת זקן,\u0004 ואם כן מוכיח הדבר שבהחלט יתכן שאי אפשר להכיר אותך כמבוגר. \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב חסדא לתובע: \u0003זיל אייתי סהדי דאחוה את\u0004 \u0005[לך הבא עדים שאתה אחיו].\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אית\u0004 \u0005[יש]\u0006 \u0003לי סהדי\u0004 \u0005[עדים],\u0006 \u0003ו\u0004אולם \u0003דחלי מיניה\u0004 \u0005[מפחדים\u0006 הם \u0005ממנו],\u0006 ממרי בר איסק, משום \u0003דגברא אלימא\u0004 \u0005[שאדם אלים]\u0006 \u0003הוא\u0004 וחוששים שמא יפגע בהם. \u0003אמר ליה לדידיה\u0004 \u0005[אמר לו\u0006 למרי בר איסק\u0005]:\u0006 \u0003זיל אנת אייתי סהדי דלאו אחוך\u0004 \u0005[לך אתה הבא עדים שאין אחיך]\u0006 \u0003הוא.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 מרי בר איסק: וכי \u0003דינא הכי\u0004 \u0005[הדין כך]?!\u0006 והלא כלל הוא: \u0003המוציא מחבירו עליו הראיה,\u0004 ועליו חובת ההוכחה ולא עלי. \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003הכי דיינינא לך ולכל אלימי דחברך\u0004 \u0005[כך אני דן אותך ואת כל האלמים חבריך],\u0006 שכיון שידוע שאתה איש אלים, אני קונס אותך שעליך להביא עדים. \u0003אמר ליה\u0004 \u0005[לו]\u0006 מרי בר איסק: \u0003סוף סוף\u0004 אם לכך אתה חושש \u0003אתו סהדי\u0004 \u0005[יבואו עדים]\u0006 \u0003ול\u0004\u0003א מסהדי\u0004 \u0005[יעידו]\u0006 לטובתו אלא לטובתי, שהרי יתכן שישקרו! \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003תרתי\u0004 \u0005[שני]\u0006 דברים \u0003לא עבדי\u0004 \u0005[יעשו],\u0006 כלומר, אינני חושש שתוכל להשפיע שהעדים יעשו שני דברים רעים: גם ימנעו מעדות אמת וגם יבואו להעיד עדות שקר ממש.","\u0003לסוף אתו סהדי\u0004 \u0005[לבסוף באו עדים]\u0006 והעידו על אותו אדם \u0003דאחוה\u0004 \u0005[שאחיו]\u0006 של מרי בר איסק \u0003הוא.\u0004 כיון שהוכח הדבר \u0003אמר ליה\u0004 \u0005[אמר לו\u0006 האח\u0005]:\u0006 \u0003לפלוג לי נמי מפרדיסי ובוסתני דשתל\u0004 \u0005[שיחלוק לי גם כן מן הפרדסים והגנים ששתל]\u0006 בינתיים מאז מות אבינו. \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב חסדא למרי בר איסק: \u0003שפיר קאמר\u0004 \u0005[יפה אמר]\u0006 \u0003לך,\u0004 וכדין אמר, שכן שנינו במשנה: \u0003הניח\u0004 אדם במותו \u0003בנים גדולים וקטנים, והשביחו גדולים את הנכסים\u0004 — \u0003השביחו לאמצע.\u0004 כלומר, כל השבח מתחלק בין כולם, ואין הגדולים יכולים לטעון שהם לבדם עבדו והשבח הוא שלהם בלבד."],["\u0003וכן אמר רבה: השביחו לאמצע. אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: מי דמי\u0004 \u0005[האם דומה\u0006 הדבר\u0005]?\u0006 \u0003התם\u0004 \u0005[שם]\u0006 במקרה שהיו האחים יחד, ה\u0003גדולים גבי\u0004 (את) ה\u0003קטנים ידעי וקא מחלי\u0004 \u0005[ידעו\u0006 שהם מצויים \u0005ומחלו]\u0006 מראש על טרחתם למען אחיהם הקטנים, \u0003הכא מי ידע דליחיל\u0004 \u0005[כאן האם ידע\u0006 האח הגדול שקיים אח צעיר \u0005שימחול לו\u0006 על טרחתו\u0005].\u0006","מסופר: \u0003אגלגל מלתא ומטא לקמיה\u0004 \u0005[התגלגל הדבר ובא לפני]\u0006 \u0003ר' אמי.\u0004 \u0003אמר להו\u0004 \u0005[להם]\u0006 למוסרי הלכה זו: הלא \u0003גדולה מזו,\u0004 כלומר, חידוש גדול מזה \u0003אמרו:\u0004 שקרובים המטפלים בנכסי שבוים \u0003שמין להם כאריס,\u0004 ואם כן אף כשטיפל בנכסים שלא היו שלו כלל נותנים לו שכר עבודתו, \u0003השתא דידיה לא יהבינן ליה\u0004 \u0005[ועכשיו את שלו\u0006 שכר עבודתו שעבד בדבר שהוא שלו \u0005לא ניתן לו]?\u0006 ולפיכך מגיע למרי בר איסק שכר על מה שהוציא עבור הנכסים.","\u0003אהדרוה הא לקמיה\u0004 \u0005[החזיר\u0006 את ההערה \u0005הזו לפני]\u0006 \u0003רב חסדא. אמר להו: מי דמי\u0004 \u0005[אמר להם: האם דומה]\u0006 הדבר? \u0003התם ברשות נחית, הכא לאו ברשות נחית\u0004 \u0005[שם ברשות\u0006 חכמים \u0005ירד\u0006 לנכסי השבוי, \u0005כאן לא ברשות ירד\u0006 לנכסי אחיו\u0005].\u0006 \u0003ועוד:\u0004 הלא \u0003קטן הוא\u0004 (היה) האח בשעה שירש מרי בר איסק את הנכסים, וכלל הוא ש\u0003אין מורידין קרוב לנכסי קטן,\u0004 ונמצא כי שלא כדין עשה.","\u0003אהדרוה לקמיה דר' אמי\u0004 \u0005[החזירו\u0006 את התשובה הזו \u0005לפני ר' אמי],\u0006 \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003לא סיימוה קמי דקטן הוא\u0004 \u0005[לא סיימו\u0006 לספר \u0005לי שקטן היה]\u0006 ואם כן הוא צדק רב חסדא.","\u0003המפקיד פירות אצל חבירו\u0004 והחבר מחזיר פירות אחרים כנגדם, \u0003הרי זה יוציא לו\u0004 מהדברים שהוא מחזיר \u0003חסרונות\u0004 של פחת. שהפירות פוחתים מסיבות שונות עם הזמן, וצריך להחזיר לו רק כשיעור המגיע למפקיד. והפחת היחסי אותו הוא מוציא מן הפירות הוא לפי חשבון זה: \u0003לחטים ולאורז\u0004 מוריד \u0003תשעה חצאי קבין\u0004 לכל \u0003כור, לשעורין ולדוחן\u0004 יוריד \u0003תשעה קבין לכור, לכוסמין ולזרע פשתן\u0004 — \u0003שלש סאין לכור, הכל לפי המדה,\u0004 כלומר, בהתאם ליחס זה מוסיף ומפחית מן הפחת, \u0003והכל לפי הזמן\u0004 ששהו הדברים, שחסרון זה הוא לשנה אחת, ואם שהה פחות או יותר מוריד לפי החשבון.","\u0003אמר ר' יוחנן בן נורי: וכי מה אכפת להן לעכברין\u0004 המכרסמים בתבואה, מה היתה הכמות? \u0003והלא אוכלות בין מהרבה ובין מקמעא! אלא, אינו יוציא\u0004 (מוציא) \u0003לו חסרונות אלא לכור אחד בלבד\u0004 ולא יותר, שהרי אין העכברים אוכלים יותר מכמות זו, גם אם היו שם תבואות מרובות. \u0003ר' יהודה אומר: אם היתה מדה מרובה\u0004 שהפקיד אצלו \u0003אינו מוציא לו חסרונות\u0004 כלל, \u0003מפני שמותירות\u0004 (מוסיפות) מסיבות שונות, ולכן כשמחזיר לו לפי מה שנתן נכלל הפחת בחשבון.","ושואלים: וכי פחת של אורז הוא מעט כל כך? הלא \u0003אורז טובא\u0004 \u0005[הרבה\u0006 יותר\u0005]\u0006 הוא \u0003חסר\u0004 במשך הזמן! \u0003אמר רבה בר בר חנה אמר ר' יוחנן: באורז קלוף שנו,\u0004 שפחתו מועט יותר. שנינו במשנה: \u0003לכוסמין ולזרע פשתן שלשה סאין לכור. אמר ר' יוחנן אמר ר' חייא: זרע פשתן בגבעולין שנו,\u0004 שהוא שפוחת הרבה כל כך. ומעירים: \u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך]:\u0006 \u0003לכוסמין ולזרע פשתן בגבעולין, ולאורז שאינו קלוף\u0004 — מוריד לפי חשבון של \u0003שלשה סאין לכור.\u0004","עוד שנינו במשנה: \u0003הכל לפי המדה\u0004 ולפי הזמן. \u0003תנא\u0004 \u0005[שנה]\u0006 החכם בתוספתא: \u0003כן לכל כור וכור, וכן לכל שנה ושנה.\u0004","\u0003אמר ר' יוחנן בן נורי:\u0004 וכי מה אכפת להם לעכברים, \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003אמרו לו\u0004 חכמים \u0003לר' יוחנן:\u0004 לא רק עכברים אוכלים, אלא \u0003הרבה אובדות מהן, הרבה מתפזרות מהן,\u0004 ולכן על כל כמות יש מסיבות שונות פחת.","\u0003תנא\u0004 \u0005[שנה\u0006 החכם\u0005]\u0006 \u0003במה דברים אמורים\u0004 שמוציא לו חסרונות לפי שיעור זה — \u0003שעירבן\u0004 את הפירות שלקח מחבירו \u0003עם פירותיו,\u0004 ואינו יודע מה שלו ומה של חבירו. \u0003אבל\u0004 אם \u0003יחד לו קרן זוית\u0004 לפירות של חבירו, \u0003אומר לו: הרי שלך לפניך\u0004 ואינו צריך לחשב אם פחת יותר או פחות.","ושואלים: \u0003וכי\u0004 \u0005[וכאשר]\u0006 \u0003עירבן עם פירותיו מאי הוי\u0004 \u0005[מה יהיה],\u0006 מדוע צריך לעשות חשבון? \u0003ליחזי לדידיה\u0004 \u0005[שיראה את שלו]\u0006 \u0003כמה הויין\u0004 \u0005[הן]\u0006 ויחשב כמה חסרו במשך הזמן, ולפי אותו חסרון יתן גם לחבירו! ומשיבים: כאן מדובר \u0003במסתפק מהם,\u0004 שבינתיים היה בעל הבית גם אוכל מפירותיו ולכן אינו יכול לחשב.","ושואלים: \u0003וליחזי\u0004 \u0005[ושיראה]\u0006 \u0003כמה אסתפק\u0004 \u0005[הסתפק],\u0006 כמה אכל במשך הזמן, ויצרף ויעשה את החישוב! ומשיבים: \u0003דלא ידעי\u0004 \u0005[שאין\u0006 \u0003יודעים]\u0004 \u0003כמה אסתפק\u0004 \u0005[לקח]\u0006 ולכן יש להחזיר לפי אומדן.","שנינו במשנה ש\u0003ר' יהודה אומר: אם היתה מדה מרובה\u0004 אינו מוציא לו חסרונות. ושואלים: \u0003כמה\u0004 היא \u0003מדה מרובה? אמר רבה בר בר חנה אמר ר' יוחנן: עשרה כורין. תניא נמי הכי\u0004 \u0005[שנויה גם כן כך\u0006 בברייתא\u0005]:\u0006 \u0003כמה מדה מרובה\u0004 — \u0003עשרה כורין.\u0004","\u0003תני תנא קמיה\u0004 \u0005[שנה חוזר המשניות לפני]\u0006 \u0003רב נחמן: במה דברים אמורים\u0004 — \u0003שמדד לו מתוך גורנו והחזיר לו מתוך גורנו,\u0004 כלומר באותה מדה שמודדים בגורן. \u0003אבל\u0004 כאשר \u0003מדד לו מתוך גורנו והחזיר לו מתוך ביתו\u0004 — \u0003אינו יוציא לו חסרונות מפני שמותירות,\u0004 שהמדה שבגורן היתה גדולה קצת יותר מן המדה הרגילה.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003וכי בשופטני עסקינן\u0004 \u0005[בשוטים עוסקים אנו],\u0006 \u0003דיהבי בכיילא רבא ושקלי בכיילא זוטא\u0004 \u0005[שנותנים במדה גדולה ונוטלים במדה קטנה]?\u0006 ברור שאם נתן לו בגורן ומדד במדת הגורן, אף כשלוקח יקח במדת הגורן ולא לפי מדות אחרות! \u0003דלמא\u0004 \u0005[שמא]\u0006 לא הסברת את הברייתא כיאות ו\u0003בימות הגורן קאמרת\u0004 \u0005[אמרת].\u0006 וכך יש להבין: \u0003במה דברים אמורים\u0004 — \u0003שמדד לו בימות הגורן והחזיר לו בימות הגורן,\u0004 כלומר באותם זמנים. \u0003אבל\u0004 כאשר \u0003מדד לו בימות הגורן והחזיר לו בימות הגשמים\u0004 — \u0003אינו יוציא לו חסרון מפני שמותירות,\u0004 משום שהזרעים סופגים לחות במשך הזמן ונפחם גדל, וכשמחזיר לו לפי אותה מדת נפח כבר נכלל הפחת בכך.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב פפא לאביי:\u0004 \u0003אם כן\u0004 שהנפח גדל בימות הגשמים \u0003לפקע כדא\u0004 \u0005[שיפקע הכד]\u0006 שבו שמים תבואה בגלל ההתנפחות הזו! ומספרים: אכן \u0003הוה עובדא\u0004 \u0005[היה מעשה]\u0006 \u0003ו\u0004אכן \u0003פקע כדא\u0004 \u0005[הכד].\u0006 \u0003איבעית אימא\u0004 \u0005[אם תרצה אמור]\u0006 יש טעם אחר, \u0003משום איצצא\u0004 \u0005[הדוחק],\u0006 כלומר, כשהיו הזרעים בגורן היו בשל הכמות הגדולה מרווחים יותר ואחר כך כשנותנו במקום צר נדחקו הזרעים, ומשום כך נותן במדה קטנה יותר.","וכשמחזיר משקים שהופקדו אצלו \u0003יוציא\u0004 (יוריד) לו \u0003שתות ליין\u0004 שבשל בליעת הקנקנים והאידוי פוחת מהם כדי שתות. \u0003ר' יהודה אומר:\u0004 יוריד \u0003חומש. יוציא לו שלשה לוגין שמן למאה,\u0004 לפי חשבון חסרונן: \u0003לוג ומחצה\u0004 של \u0003שמרים\u0004 ששוקעים במשך הזמן לתחתית הקנקן, ו\u0003לוג ומחצה בלע\u0004 שנבלע השמן בדפנות הקנקן. \u0003אם היה\u0004 זה \u0003שמן מזוקק אינו יוציא לו שמרים,\u0004 שהרי כבר סיננו את השמן משמריו קודם לכן, \u0003אם היו קנקנים ישנים\u0004 שכבר בלעו כל צרכם — \u0003אינו יוציא לו בלע. ר' יהודה אומר: אף המוכר שמן מזוקק לחבירו כל ימות השנה, הרי זה\u0004 הקונה \u0003מקבל עליו\u0004 שיפחית לו \u0003לוג ומחצה שמרים למאה,\u0004 שזהו השעור המקובל של שמרים.","ומעירים: \u0003ולא פליגי\u0004 \u0005[ואין חלוקים]\u0006 חכמים ור' יהודה בהלכה, אלא \u0003מר כי אתריה ומר כי אתריה\u0004 \u0005[חכם זה לפי מקומו וחכם זה לפי מקומו].\u0006 \u0003באתריה דמר\u0004 \u0005[במקומו של חכם זה,\u0006 של תנא קמא\u0005]\u0006 \u0003חפו בקירא ולא מייץ טפי\u0004 \u0005[מחפים\u0006 את הקנקנים \u0005בשעוה ואינה סופגת הרבה],\u0006 \u0003באתריה דמר חפו בכופרא ומייץ טפי\u0004 \u0005[במקומו של חכם זה,\u0006 ר' יהודה, \u0005מצפים\u0006 את הכדים \u0005בזפת והיא בולעת הרבה].\u0006 \u0003איבעית אימא\u0004 \u0005[אם תרצה אמור]\u0006 \u0003משום גרגישתא\u0004 \u0005[משום\u0006 טיב \u0005האדמה]\u0006 שממנה עושים את הכדים, \u0003הא מייצא טפי והא לא מייצא טפי\u0004 \u0005[זו סופגת הרבה וזו אינה סופגת הרבה].\u0006","מסופר: \u0003באתריה\u0004 \u0005[במקומו]\u0006 של \u0003רב יהודה רמו\u0004 \u0005[היו מכניסים]\u0006 \u0003ארבעים ותמני כוזי בדנא\u0004 \u0005[ושמונה ספלים בתוך חבית],\u0006 שזה היה שעור גודלן של החביות שם. \u0003אזיל דנא בשיתא זוזי\u0004 \u0005[היה הולך,\u0006 עולה, מחיר \u0005החבית שישה דינרים],\u0006 והיה \u0003פריס\u0004 \u0005[מחלקם]\u0006 \u0003רב יהודה\u0004 ומוכרם כחנווני \u0003שיתא שיתא בזוזא\u0004 \u0005[שישה שישה\u0006 ספלים \u0005בזוז],\u0006"],["\u0003דל תלתין ושיתא בשיתא\u0004 \u0005[הוצא מהם שלושים ושישה\u0006 ספלים שמכר \u0005בשישה\u0006 זוזים\u0005]\u0006 ואם כן קיבל בחזרה את מה ששילם עבור החבית, \u0003פשו ליה תריסר\u0004 \u0005[נשארו\u0006 עוד \u0005שנים עשר\u0006 ספלים\u0005]\u0006 עודף שהרוויח. \u0003דל תמניא שתותי\u0004 \u0005[הוצא\u0006 מהם \u0005שמונה ששיות]\u0006 שהרי אמרנו כי שישית מהיין נספגת בקנקנים, ודבר זה היה על חשבונו של החנווני, נמצא כי \u0003פשו להו\u0004 \u0005[נשארו להם]\u0006 איפוא \u0003ארבעה\u0004 ספלים יתרים שהם היו הרווח שהרויח רב יהודה.","ושואלים: \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003שמואל:\u0004 \u0003המשתכר\u0004 בצורכי אוכל נפש \u0003אל ישתכר יותר על שתות\u0004 \u0005[ששית],\u0006 ומשמע כי לכל הפחות שישית מותר לו להשתכר, ואולם לפי החשבון נמצא שרב יהודה הרוויח הרבה פחות משישית, ומדוע עשה כן?","ומשיבים: \u0003איכא גולפי ושמריא\u0004 \u0005[יש\u0006 את \u0005הקנקן\u0006 עצמו \u0005והשמרים]\u0006 שנשארו עוד בידו שהרי קנה הכל בשישה זוזים, והם מוסיפים לרווח. ושואלים: \u0003אי הכי נפיש ליה טפי משתות\u0004 \u0005[אם כך מרובה\u0006 לו הרווח \u0005יותר משישית]\u0006 וכיצד לקח רב יהודה יותר מן המותר? ומשיבים: \u0003איכא טרחיה\u0004 \u0005[יש\u0006 את שכר \u0005טרחתו],\u0006 שכר מכירת השמן \u0003ודמי ברזנייתא\u0004 \u0005[הניקוב]\u0006 שלוקח בעל מלאכה מיוחד שצריך לנקב את החביות, וכשמורידים את אלה מן החשבון נמצא שהרוויח שתות.","שנינו במשנה \u0003אם היה שמן מזוקק אינו יוציא לו שמרים,\u0004 וכן אם היה זה כד ישן לא יוציא לו כיון שאין הכד בולע. ושואלים: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003אי אפשר\u0004 ש\u0003לא בלע\u0004 \u0005[יבלע]\u0006 הכד מאומה, אפילו בכד ישן! \u0003אמר רב נחמן: במזופפין\u0004 (בכלים שהיו מצופים מבפנים בזפת) \u0003שנו,\u0004 שאם הכד ישן ומזופף — אינו בולע. \u0003אביי אמר: אפילו תימא\u0004 \u0005[תאמר]\u0006 \u0003שלא\u0004 מדובר כאן \u0003במזופפין, כיון דטעון\u0004 \u0005[שבלעו]\u0006 — \u0003טעון\u0004 \u0005[בלעו]\u0006 ושוב אין שמן נבלע בתוכם.","עוד שנינו במשנה ש\u0003ר' יהודה אומר\u0004 ש\u0003אף המוכר שמן מזוקק לחבירו כל ימות השנה הרי זה\u0004 הקונה \u0003מקבל עליו לוג ומחצה שמרים למאה. אמר אביי: כשתמצא לומר\u0004 כשתמצה את הדבר ותדקדק בו תמצא כי \u0003לדברי ר' יהודה מותר לערב שמרים\u0004 ששקעו לתחתית החבית עם השמן הצלול שנשאר מלמעלה, שיכול לבחוש שנית את כל החבית ולמכור כל מה שיש בה. \u0003ולדברי חכמים אסור לערב שמרים.\u0004","ומסביר, \u0003לדברי ר' יהודה מותר לערב שמרים, והיינו טעמא\u0004 \u0005[וזהו הטעם]\u0006 ש\u0003מקבל\u0004 הקונה ומפחית מן השמן אותו לוג ומחצה, \u0003דאמר ליה\u0004 \u0005[שאומר לו]\u0006 המוכר: \u0003אי בעי לערובי\u0004 \u0005[אילו הייתי רוצה לערב]\u0006 \u0003לך\u0004 שמרים — \u0003מי\u0004 \u0005[האם]\u0006 \u0003לא ערבי\u0004 \u0005[הייתי מערב]\u0006 \u0003לך?\u0004 \u0003השתא נמי קביל\u0004 \u0005[עכשיו גם כן קבל]\u0006 על עצמך שיעור הפחת עבור השמרים.","ושואלים: \u0003ולימא ליה\u0004 \u0005[ושיאמר לו]\u0006 הקונה: \u0003אי ערבת\u0004 \u0005[אילו הייתה מערב]\u0006 \u0003לי\u0004 שמרים \u0003הוה מזדבן\u0004 \u0005[היו נמכרים]\u0006 \u0003לי, השתא מאי אעביד ליה\u0004 \u0005[עכשיו מה אעשה לזה]?\u0006 הרי \u0003לחודיה לא מזדבן\u0004 \u0005[לחוד אין\u0006 הדבר \u0005נמכר]\u0006 \u0003לי\u0004 ונמצא שאני מפסיד! ומשיבים: בקונה שהוא \u0003בעל הבית\u0004 הצריך שמן לעצמו \u0003עסקינן\u0004 \u0005[עוסקים אנו]\u0006 \u0003דניחא ליה בצילא\u0004 \u0005[שנוח לו\u0006 בשמן \u0005צלול]\u0006 וכדאי לו שהמוכר יפחית מן השמן את אחוז השמרים. ושואלים: \u0003ולימא ליה\u0004 \u0005[ושיאמר לו]\u0006 הקונה: \u0003מדלא ערבית\u0004 \u0005[מכיון שלא עירבת]\u0006 \u0003לי\u0004 — משמע ש\u0003אחולי אחלת\u0004 \u0005[מחלת]\u0006 \u0003לי!\u0004","ומשיבים: \u0003ר' יהודה לטעמיה\u0004 \u0005[לטעמו,\u0006 לשיטתו\u0005],\u0006 \u0003דלית ליה\u0004 \u0005[שאין לו,\u0006 שאינו מקבל\u0005]\u0006 סברה זו של \u0003מחילה,\u0004 ולדעתו אין הקונה יכול לומר שמחל המוכר יתר על המחיר הראוי. \u0003דתנן\u0004 \u0005[\u0005שכן שנינו במשנה\u0006]\u0006: \u0003מכר לו\u0004 לחבירו \u0003צמד\u0004 — \u0003לא מכר לו את הבקר,\u0004 שהמלה \"צמד\" כדיוקה משמעה העול המצמיד זוג בהמות לחרישה, אבל אפשר להבינו גם כצמד הבהמות עם העול שעליהן. ואמרו חכמים שאם אמר שמוכר \"צמד\" שרק העול עצמו נמכר, אבל לא הבקר. \u0003מכר לו את הבקר\u0004 — \u0003לא מכר לו את הצמד,\u0004 והמכירה היא רק על מה שאמר לו כדיוקן של המילים.","\u0003ר' יהודה אומר: הדמים מודיעין,\u0004 כלומר לפי המחיר אפשר להבין מה הוא שנמכר ונקנה. \u0003כיצד?\u0004 — \u0003אמר לו: מכור לי צמדך במאתים זוז\u0004 — \u0003הדבר ידוע שאין הצמד\u0004 (העול עצמו) נמכר \u0003במאתיים זוז\u0004 ובוודאי נתכוון לצמד שוורים. \u0003וחכמים אומרים: אין הדמים\u0004 (המחיר) \u0003ראיה\u0004 אלא ייתכן שמחל המוכר לקונה, ומכר לו הרבה במעט או להיפך.","ובהמשך לענייננו: \u0003לדברי חכמים אסור לערב שמרים, והיינו טעמא\u0004 \u0005[וזהו הטעם]\u0006 ש\u0003לא מקבל\u0004 הקונה על עצמו את הפחת — \u0003דאמר ליה\u0004 \u0005[שאומר לו]\u0006 הקונה: \u0003אי בעית לערובי\u0004 \u0005[אם היית רוצה לערב]\u0006 — \u0003מי הוה שרי\u0004 \u0005[האם היה מותר]\u0006 \u0003לך?\u0004 \u0003השתא נמי לא מקבילנא\u0004 \u0005[עכשיו גם כן אין אני רוצה לקבל].\u0006","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב פפא לאביי: אדרבה, איפכא מסתברא\u0004 \u0005[להיפך, ההיפך\u0006 הוא \u0005המסתבר].\u0006 וכן נדון: \u0003לדברי חכמים מותר לערב שמרים, והיינו טעמא\u0004 \u0005[וזהו הטעם]\u0006 שהוא \u0003לא מקבל\u0004 — \u0003דאמר ליה\u0004 \u0005[שאומר לו]\u0006 הקונה: \u0003מדלא\u0004 \u0005[מכיון שלא]\u0006 \u0003ערבת לי,\u0004 ודאי \u0003אחולי אחלית\u0004 \u0005[מחלת]\u0006 \u0003לי.\u0004 ואילו \u0003לדברי ר' יהודה אסור לערב שמרים, והיינו טעמא\u0004 \u0005[וזהו הטעם]\u0006 ש\u0003מקבל\u0004 — \u0003דאמר ליה\u0004 \u0005[שאומר לו]\u0006 המוכר: \u0003אי בעי לערובי\u0004 \u0005[אילו הייתי רוצה לערב]\u0006 — הרי \u0003לא שרי\u0004 \u0005[אסור]\u0006 \u0003לי לערובי\u0004 \u0005[ערב]\u0006 \u0003לך,\u0004 ואתה \u0003קבולי\u0004 \u0005[לקבל]\u0006 \u0003לא מקבלת\u0004 \u0005[תקבל]\u0006 את הפחת, אם כן נמצא שאינני מרויח כלום במכירה זו. והרי מפורסם מפתגם שאומרים אנשים על שוטה העוסק במסחר: \u0003זבון וזבין תגרא איקרי\u0004 \u0005[מכור וקנה\u0006 באותו מחיר כדי \u0005שתקרא תגר]?\u0006 הלא בוודאי צריך אני להרויח דבר מה.","\u0003תנא\u0004 \u0005[שנה]\u0006 החכם: \u0003אחד הלוקח\u0004 (הקונה) \u0003ואחד המפקיד לפקטים\u0004 (פסולת הצפה על גבי השמן). ושואלים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003לפקטים?\u0004 \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003כי היכי\u0004 \u0005[כשם]\u0006 שה\u0003לוקח לא מקבל\u0004 על עצמו את הפחת של ה\u0003פקטים\u0004 ו\u0003מפקיד נמי\u0004 \u0005[גם כן]\u0006 \u0003לא מקבל\u0004 על עצמו את פחת ה\u0003פקטים\u0004 וצריך להחזיר לו שמן צלול \u0003ולימא ליה\u0004 \u0005[ושיאמר לו]\u0006 מקבל הפקדון: \u0003פקטך מאי איעביד להו\u0004 \u0005[עכירות השמנים שלך מה אעשה להם]?\u0006","אלא יש להבין: \u0003כי היכי\u0004 \u0005[כשם]\u0006 שה\u0003מפקיד מקבל\u0004 את ה\u0003פקטים\u0004 ויודע שמפחיתים חלק מן השמן בגלל החלק העכור שבתוכו \u0003ה\u0004\u0003לוקח נמי\u0004 \u0005[גם כן]\u0006 \u0003מקבל\u0004 על עצמו אחוז מסויים עבור \u0003פקטים.\u0004 ושואלים: \u0003ומי\u0004 \u0005[והאם]\u0006 \u0003מקבל\u0004 ה\u0003לוקח\u0004 על עצמו \u0003את ה\u0004\u0003פקטים?\u0004 \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005],\u0006 \u0003ר' יהודה אומר: לא אמרו שמן עכור אלא למוכר בלבד, שהרי לוקח מקבל עליו לוג ומחצה שמרים,\u0004 אבל מקבל שמן נקי בלא פקטים. ומשיבים: \u0003לא\u0004","\u0003קשיא\u0004 \u0005[אינו קשה],\u0006 \u0003הא\u0004 \u0005[זה]\u0006 — \u0003דיהיב ליה זוזי\u0004 \u0005[שנתן לו זוזים,\u0006 כסף\u0005]\u0006 \u0003ב\u0004חודש \u0003תשרי\u0004 שאז מוסקים את הזיתים \u0003וקא שקיל מיניה\u0004 \u0005[ולוקח ממנו]\u0006 \u0003ב\u0004חודש \u0003ניסן כי\u0004 \u0005[כפי]\u0006 ה\u0003מדה\u0004 של חודש \u0003תשרי,\u0004 שכיון ששילם לו בשעתו מחיר נמוך קצת יותר, הרי הוא צריך לקבל על עצמו שמן כפי שהיה בתשרי, שמיד לאחר המסיקה היה עדיין השמן עכור. \u0003הא\u0004 \u0005[זה]\u0006 \u0003דיהיב ליה זוזי\u0004 \u0005[שנתן לו זוזים,\u0006 כסף\u0005]\u0006 \u0003ב\u0004חודש \u0003ניסן וקא שקיל מיניה\u0004 \u0005[ולוקח ממנו]\u0006 \u0003ב\u0004חודש \u0003ניסן כי\u0004 \u0005[כפי]\u0006 ה\u0003מדה\u0004 של חודש \u0003ניסן,\u0004 שמשלם לו מעט יותר ורוצה בשמן מזוקק.","\u0003המפקיד חבית אצל חבירו ולא יחדו לה\u0004 ה\u0003בעלים מקום,\u0004 שלא התנה המפקיד שתהא החבית במקום מסויים בבית השומר, \u0003וטלטלה\u0004 השומר \u0003ונשתברה, אם מתוך ידו\u0004 (בעודה בידו) \u0003נשברה,\u0004 יש לחלק: אם טלטל את החבית \u0003לצורכו\u0004 שרצה להשתמש בה לאיזה צורך — \u0003חייב\u0004 לשלם את הנזק. ואם טלטל את החבית \u0003לצורכה,\u0004 כגון שרצה להוציאה ממקום שהיתה ניזוקת בו — \u0003פטור.\u0004 \u0003אם משהניחה\u0004 לאחר שטלטלה \u0003נשברה, בין\u0004 שטלטלה מראש \u0003לצורכו בין\u0004 שטלטלה \u0003לצורכה\u0004 — \u0003פטור.\u0004 ואולם אם \u0003יחדו לה הבעלים מקום, וטלטלה\u0004 השומר \u0003ונשברה, בין מתוך ידו ובין משהניחה,\u0004 אם טלטלה \u0003לצורכו\u0004 — \u0003חייב,\u0004 אם \u0003לצורכה\u0004 — \u0003פטור.\u0004","ושואלים: \u0003הא מני\u0004 \u0005[זו\u0006 משנתינו, כשיטת \u0005מי היא]\u0006 — כשיטת \u0003ר' ישמעאל,\u0004 ש\u0003אמר: לא בעינן\u0004 \u0005[אין אנו צריכים]\u0006 \u0003דעת בעלים.\u0004 שכאשר אדם מחזיר דבר שגנב, אינו צריך להודיע לבעל החפץ שהוא מחזיר לו. \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003הגונב טלה מן העדר\u0004 או \u0003סלע\u0004 (מטבע) \u0003מן הכיס\u0004 — \u0003למקום שגנב יחזיר,\u0004 ואינו צריך להודיע כלל לבעלים, אלו \u0003דברי ר' ישמעאל. רבי עקיבא אומר:\u0004"],["\u0003צריך דעת בעלים\u0004 כשמחזיר, וכל עוד לא הודיע להם הריהו חייב באחריות על מה שלקח.","ושואלים: \u0003אי\u0004 \u0005[אם]\u0006 לשיטת \u0003ר' ישמעאל, מאי איריא\u0004 \u0005[מה שייך,\u0006 מדוע דווקא\u0005]\u0006 ש\u0003לא יחדו\u0004 הבעלים מקום? \u0003אפילו יחדו נמי\u0004 \u0005[גם כן],\u0006 כיון שהחזיר את הדבר למקומו, הרי נהג כראוי!","ומשיבים: בלשון \u0003לא מיבעיא קאמר\u0004 \u0005[נצרכה אמר;.\u0006 \u0003לא מיבעיא\u0004 \u0005[נצרכה]\u0006 לומר כש\u0003יחדו\u0004 לה הבעלים מקום ש\u0003מקומה הוא, אלא אפילו לא יחדו\u0004 לה הבעלים מקום, \u0003דלאו\u0004 \u0005[שלא]\u0006 \u0003מקומה הוא\u0004 המסויים — \u0003לא בעינן\u0004 \u0005[אין אנו צריכים]\u0006 לכך את \u0003דעת הבעלים,\u0004 וכיון שהניח את החבית הרי זה נפטר מכל אחריות.","ואומרים: אם כן, \u0003אימא סיפא\u0004 \u0005[אמור את סופה]\u0006 של משנתנו: \u0003יחדו לה הבעלים מקום וטלטלה ונשברה, בין מתוך ידו, בין משהניחה,\u0004 אם טלטלה \u0003לצרכו\u0004 — \u0003חייב, לצרכה\u0004 — \u0003פטור.\u0004 ואם כן \u0003אתאן\u0004 \u0005[הגענו]\u0006 לשיטת \u0003ר' עקיבא,\u0004 ש\u0003אמר: בעינן\u0004 \u0005[צריכים אנו]\u0006 \u0003דעת בעלים,\u0004 וכיון שנטלה ממקומה לשם עצמו הרי הוא כגזלן, ועליו האחריות.","ומקשים: \u0003אי\u0004 \u0005[אם]\u0006 לשיטת \u0003ר' עקיבא\u0004 — \u0003מאי איריא\u0004 \u0005[מה שייך,\u0006 מדוע דווקא\u0005]\u0006 אם \u0003יחדו? אפילו לא יחדו נמי\u0004 \u0005[גם כן]\u0006 יהיה חייב!","ומשיבים: בלשון \u0003לא מיבעיא קאמר\u0004 \u0005[נצרכה אמר],\u0006 \u0003לא מיבעיא\u0004 \u0005[נצרכה]\u0006 לומר כש\u0003לא יחדו, דלאו\u0004 \u0005[שלא]\u0006 \u0003מקומה הוא\u0004 ואם כן לא היתה כאן החזרה, \u0003אלא אפילו יחדו נמי\u0004 \u0005[גם כן]\u0006 שהחבית עכשיו \u0003ב\u0004\u0003מקומה הוא,\u0004 והחזירה למקומה — מכל מקום \u0003בעינן\u0004 \u0005[צריכים אנו]\u0006 \u0003דעת בעלים.\u0004","ותוהים: אם כן יוצא מכאן כי \u0003רישא\u0004 \u0005[ראשה]\u0006 של המשנה כשיטת \u0003ר' ישמעאל וסיפא\u0004 \u0005[וסופה]\u0006 כ\u0003ר' עקיבא!\u0004 ומשיבים: \u0003אין\u0004 \u0005[כן]\u0006 הוא. וכפי ש\u0003אמר ר' יוחנן: מאן דמתרגם\u0004 \u0005[מי שיסביר]\u0006 \u0003לי\u0004 משנה \u0003זו ב\u0004\u0003חבית אליבא דחד תנא\u0004 \u0005[לפי שיטתו של תנא אחד]\u0006 ולא לפי שתי שיטות, אכבד אותו עד כדי כך, ש\u0003מובלנא מאניה בתריה לבי מסותא\u0004 \u0005[אוביל את כליו,\u0006 בגדיו \u0005אחריו לבית המרחץ],\u0006 כלומר, אנהג בו כמנהג שימוש שעבד נוהג ברבו.","מסופר, \u0003תרגמה\u0004 \u0005[הסבירה]\u0006 \u0003ר' יעקב בר אבא קמיה\u0004 \u0005[לפני]\u0006 \u0003רב,\u0004 שמדובר כאן באופן \u0003שנטלה על מנת לגוזלה\u0004 וזהו פירוש \"לצורכו\" וכיון שהתכוון לגזול צריך להשיב את החבית למקומה ממש. ובסוף המשנה מדובר שלא החזירה ממש.","ובדומה לזה \u0003תרגמה\u0004 \u0005[פירשה]\u0006 \u0003ר' נתן בר אבא קמיה\u0004 \u0005[לפני]\u0006 \u0003רב:\u0004 מדובר כאן באופן \u0003שנטלה על מנת לשלוח בה יד,\u0004 כלומר, לקחת ממנה משהו, שאמר הכתוב שאם שלח ידו במלאכת רעהו — האחריות מוטלת עליו.","ושואלים: \u0003במאי קמיפלגי\u0004 \u0005[במה חולקים הם]?\u0006 שזה נתן טעם זה וזה נתן טעם אחר? ומשיבים: בשאלה אם \u0003שליחות יד צריכה חסרון,\u0004 כלומר דין זה ששלח את ידו במלאכת רעהו, משמעו שממש יקח משהו ויחסר מן הפקדון, או שנתחייב באחריות אף אם רק נתכוין לכך, ואפילו לא חסר מאומה. \u0003מאן\u0004 \u0005[מי]\u0006 ש\u0003אמר\u0004 שהתכוון \u0003לגוזלה קסבר\u0004 \u0005[סבור]\u0006 ש\u0003שליחות יד\u0004 בניגוד לגזילה \u0003צריכה חסרון\u0004 ממש, \u0003ומאן\u0004 \u0005[ומי]\u0006 ש\u0003אמר\u0004 \u0003לשלוח בה יד, קסבר\u0004 \u0005[סבור\u0006 הוא\u0005]\u0006 כי \u0003שליחות יד אינה צריכה חסרון.\u0004","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רב ששת: מידי\u0004 \u0005[וכי]\u0006 \u0003\"נטלה\" קתני\u0004 \u0005[שנה],\u0006 הלא \u0003\"טלטלה\" קתני\u0004 \u0005[שנה],\u0006 ואין במשמעות הדברים שהתכוון לקחת אותה לעצמו! \u0003אלא אמר רב ששת: הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 — \u0003כגון שטלטלה להביא עליה גוזלות,\u0004 שלא התכוון להשתמש בתוכנה, אלא לטפס עליה לפי שעה לצורכו, \u0003וקא סבר\u0004 \u0005[וסבור הוא]:\u0006 \u0003שואל שלא מדעת\u0004 הבעלים — \u0003גזלן הוי\u0004 \u0005[הוא]\u0006 לענין אחריות. \u0003ו\u0004אם כן, המשנה \u0003כולה\u0004 כשיטת \u0003ר' ישמעאל היא,\u0004 אלא \u0003סיפא\u0004 \u0005[סופה]\u0006 מדובר \u0003שהניחה במקום שאינה מקומה,\u0004 וכיון שלא החזירה למקומה — אחריותו עדיין עליה.","ושואלים: \u0003ור' יוחנן\u0004 הסבור שמשנה זו קשה מאד לתרצה לפי שיטה אחת, מה היה אומר על תרוץ זה? — לדעתו \u0003\"הניחה\"\u0004 — \u0003במקומה משמע,\u0004 ואם כן אין אפשרות להסבירה כר' ישמעאל. ועדיין יש סתירה במשנתנו.","\u0003איתמר\u0004 \u0005[נאמר]\u0006 שנחלקו בבעיה זו האמוראים \u0003רב ולוי. חד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 \u0003אמר: שליחות יד צריכה חסרון,\u0004 שאינו נחשב לשולח יד בפקדון עד שיחסר ממנו ממש ויקח לעצמו, \u0003וחד\u0004 \u0005ואחד\u0006 מהם\u0005]\u0006 \u0003אמר:\u0004 \u0003שליחות יד אינה צריכה חסרון,\u0004 ודי בכוונה לשלוח בה יד. ומעירים: \u0003תסתיים\u0004 \u0005[תוגדר]\u0006 ש\u0003רב הוא\u0004 ש\u0003אמר\u0004 כי \u0003שליחות יד אינה צריכה חסרון\u0004 — \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003רועה שהיה רועה עדרו\u0004 שהיו בו בהמותיהם של אחרים, \u0003והניח עדרו ובא לעיר, ובא זאב וטרף\u0004 מן העדר \u0003ובא ארי ודרס\u0004 — הרי זה \u0003פטור,\u0004 שהרי בין כה וכה טריפת הזאב והארי אונס היא. ואולם אם \u0003הניח מקלו ותרמילו עליה\u0004 על הבהמה — \u0003חייב\u0004 עליה שכיון שהשתמש בבהמה הרי זה כשולח בה יד, וממילא נתחייב בכל אונס שיקרה.","\u0003והוינן בה\u0004 \u0005[והיינו עוסקים\u0006 ומתקשים \u0005בה]\u0006 בבעיה זו, וכי \u0003משום\u0004 ש\u0003הניח מקלו ותרמילו עליה חייב? הא שקלינהו\u0004 \u0005[הרי\u0006 כבר \u0005לקח אותם],\u0006 וגם אם נאמר שהשתמש בבהמה שלא כדין, הרי כבר הוריד את חפציו ממנה, והרי זה כמחזיר לבעלים!","\u0003אמר רב נחמן אמר רבה בר אבוה אמר רב:\u0004 מדובר כאן שטרפתה החיה \u0003בעודן עליה\u0004 שכיון שלקחם לצורכו הרי הן כשלו להתחייב עליהן. ושאלו: \u0003וכי עודן עליה מאי הוא\u0004 \u0005[מה יהיה]?\u0006 \u0003הא\u0004 \u0005[הרי]\u0006 \u0003לא משכה\u0004 את הבהמה, וכיון שלא משך אותה לא נקנתה לו!","\u0003אמר רב שמואל בר רב יצחק אמר רב:\u0004 מדובר שם \u0003שהכישה\u0004 (הכה אותה) \u0003במקל ורצתה\u0004 (רצה) \u0003לפניו\u0004 ואם כן עשה בה משיכה כל שהיא. וממשיכים בבירור הדברים: \u0003והא\u0004 \u0005[הרי]\u0006 \u0003לא חסרה\u0004 הבהמה דבר על ידי שהניח את חפציו עליה? \u0003אלא לאו שמע מינה\u0004 \u0005[האם לא תלמד מכאן]\u0006 כי \u0003קסבר\u0004 \u0005[סבור]\u0006 \u0003רב\u0004 ש\u0003שליחות יד אינה צריכה חסרון.\u0004","ודוחים: \u0003אימא\u0004 \u0005[אמור]\u0006 \u0003שהכחישה במקל,\u0004 כלומר איננו מתחייב משום שרצה לפניו, אלא שהוריד מערכה משהו על ידי שהיכה אותה. ומעירים: \u0003דיקא נמי\u0004 \u0005[מדוייק גם כן]\u0006 לפרש כן, \u0003דקתני\u0004 \u0005[ששנה]\u0006 \u0003\"שהכישה במקל\"\u0004 שפירש \"במקל\" דווקא, ללמד שחבטות המקל גרמו לנזק מה. ומסכמים: אכן, \u0003שמע מינה\u0004 \u0005[למד ממנה].\u0006","וכיון שאתה מדייק \u0003שרב סבר שליחות יד צריכה חסרון,\u0004 משמע ש\u0003לוי\u0004 הוא אשר \u0003סבר שליחות יד אינה צריכה חסרון.\u0004 ושואלים: \u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003לוי\u0004 שדי בכוונה בלבד? \u0003אמר ר' יוחנן משום\u0004 \u0005[בשם]\u0006 \u0003ר' יוסי בן נהוראי: משונה שליחות יד האמורה בשומר שכר משליחות יד האמורה בשומר חנם,\u0004 שכיון שהלכה זו נאמרה בכתוב בשני המקרים, ולכאורה אינה נחוצה, שהרי אם מתחייב שומר חנם — כל שכן ששומר שכר מתחייב על כך. אלא ודאי באה חזרה זו ללמדנו ששליחות יד של שומר שכר דייה בכוונה בלבד, ואינה צריכה חסרון."],["והוסיף ר' יוחנן עצמו: \u0003ואני אומר אינה משונה.\u0004","ומסבירים: \u0003ומאי\u0004 \u0005[מה]\u0006 ה\u0003משונה\u0004 בדבר — \u0003לא תאמר שליחות יד בשומר שכר, ותיתי\u0004 \u0005[ותבוא,\u0006 תלמד\u0005]\u0006 \u0003משומר חנם\u0004 בקל וחומר: \u0003ומה שומר חנם שפטור בגנבה ואבדה,\u0004 אם הוא עצמו \u0003שלח בה יד\u0004 — \u0003חייב, שומר שכר שחייב בגנבה ואבידה לא כל שכן\u0004 שחייב אם הוא עצמו גנבה. ואם כן \u0003למאי הלכתא כתבינהו רחמנא\u0004 \u0005[לאיזו הלכה,\u0006 לאיזה לימוד, \u0005כתבה התורה]\u0006 גם בזה דין של שליחות יד? — \u0003לומר לך: שליחות יד אינה צריכה חסרון,\u0004 אלא כיון שהתכוון לקחת ממנה כבר נתחייב.","\u0003ואני אומר: אינה משונה,\u0004 וכדברי \u0003ר' אלעזר,\u0004 ש\u0003אמר: דא ודא\u0004 \u0005[זו וזו]\u0006 \u0003אחת היא,\u0004 שכשם שנצרכה הלכה זו בשומר חנם, כך נצרכה בשומר שכר. ומסבירים: \u0003מאי דא ודא\u0004 \u0005[מה זו וזו]\u0006 \u0003אחת\u0004 היא? — \u0003משום דאיכא למפרך\u0004 \u0005[שיש\u0006 מקום \u0005לפרוך,\u0006 לשבור\u0005]\u0006 את תוקפו של הקל וחומר שהבאנו קודם, ולומר: \u0003מה לשומר חנם, שכן משלם תשלומי כפל בטוען טענת גנב\u0004 אם יתברר שלא נגנב מאיתו. אבל שומר שכר במקרה כזה אינו משלם כפל אלא את הפקדון בלבד. וכיון שמצאנו שהחמירה בו התורה, אפשר לומר שגם בשליחות יד יהיה רק הוא חייב ולא שומר שכר, ושוב אין כאן קל וחומר.","ומעירים: \u0003ומאן\u0004 \u0005[ומי]\u0006 ש\u0003לא פריך\u0004 \u0005[הקשה]\u0006 כך \u0003סבר:\u0004 לשלם \u0003קרנא\u0004 \u0005[קרן]\u0006 \u0003בלא שבועה עדיפא מכפילא\u0004 \u0005[עדיף\u0006 מאשר לשלם כפל \u0003בשבועה\u0004 ולכן עדיין אפשר לומר שחמור יותר שומר שכר משומר חנם, ויש כאן קל וחומר.","\u0003רבא אמר,\u0004 כך הוא הלימוד: \u0003לא תאמר שליחות יד לא בשומר חנם ולא בשומר שכר, ותיתי\u0004 \u0005[ותבוא,\u0006 ותלמד\u0005]\u0006 הלכה זו \u0003משואל.\u0004 וכך נלמד: \u0003ומה שואל\u0004 ש\u0003לדעת\u0004 ה\u0003בעלים קא עביד\u0004 \u0005[הוא עושה],\u0006 שהרי שאל מן הבעלים לעשות מלאכה בבהמה, ואף על פי כן אם \u0003שלח בה יד\u0004 — \u0003חייב, שומר חנם ושומר שכר\u0004 שלא נתנה להם רשות להשתמש בפקדון \u0003לא כל שכן\u0004 שחייבים.","אם כן \u0003למה נאמר\u0004 בכתוב עוד פעם דין שליחות יד — \u0003חדא\u0004 \u0005[אחת\u0006 מהם\u0005]\u0006 \u0003לומר לך: שליחות יד אין צריכה חסרון. ואידך\u0004 \u0005[והאחרת]:\u0006 \u0003שלא תאמר\u0004 כיון שיש כאן קל וחומר, הרי במדה זו \u0003דיו לבא מן הדין להיות כנידון\u0004 ואין אתה יכול להחמיר בנלמד יותר מן המלמד, ותאמר: \u0003מה שואל\u0004 אם היה הדבר \u0003בבעלים\u0004 (שהיו בעליו עמו) \u0003פטור\u0004 — \u0003אף שומר חנם ושומר שכר בבעלים פטור,\u0004 ולכן הוצרך לחזור ולומר שבשומרים אלה אין פטור גם אם היה הדבר בבעלים.","ושואלים: \u0003ולמאן דאמר\u0004 \u0005[ול\u0006שיטת \u0005מי שאומר]\u0006 \u0003שליחות יד צריכה חסרון,\u0004 אם כן \u0003הני תרתי\u0004 \u0005[אלו השתים]\u0006 \u0003בשליחות יד למה לי?\u0004 ומסבירים: \u0003חדא\u0004 \u0005[אחת\u0006 מהן\u0005]\u0006 \u0003שלא תאמר דיו לבא מן הדין להיות כנדון,\u0004 ולא תאמר שיש בשומר חנם ושומר שכר ההקלה שיש בשואל לענין פטור בבעלים.","\u0003ואידך\u0004 \u0005[והאחרת]\u0006 \u0003לכדתניא\u0004 \u0005[לכפי ששנינו\u0006 בברייתא\u0005]\u0006 נאמר: \u0003\"ונקרב בעל הבית אל האלהים\u0004 אם לא שלח יד במלאכת רעהו\u0003\"\u0004 (שמות כב, ז) — הכוונה היא \u0003לשבועה. אתה אומר\u0004 שהוא נקרב \u0003לשבועה, או אינו אלא לדין?\u0004 על כן למדים: \u0003נאמרה שליחות יד למטה\u0004 (\"אם לא שלח ידו במלאכת רעהו\". שם י), \u0003ונאמרה שליחות יד למעלה\u0004 (\"אם לא שלח ידו במלאכת רעהו\". שם ז), \u0003מה להלן\u0004 מפורש שהוא \u0003לשבועה\u0004 (\"שבועת ה' תהיה בין שניהם אם לא שלח ידו במלאכת רעהו\") — \u0003אף כאן\u0004 הכוונה היא \u0003לשבועה\u0004 ולא להעמדה בדין בלבד."],["\u0003המפקיד מעות אצל חברו,\u0004 אם \u0003צררן\u0004 השומר בבגדו \u0003והפשילן לאחוריו, או שמסרם לבנו ולבתו הקטנים,\u0004 או הניחם בבית \u0003ונעל בפניהם שלא כראוי\u0004 — \u0003חייב\u0004 אם נגנבו, \u0003שלא שימר כדרך השומרים. ואם שימר כדרך השומרים\u0004 ונגנב — הרי זה \u0003פטור.\u0004","ושואלים: \u0003בשלמא כולהו\u0004 \u0005[נניח לכולם]\u0006 כי ברור \u0003שלא שימר כדרך השומרים, אלא צררן והפשילן לאחוריו, מאי הוה ליה למיעבד\u0004 \u0005[מה היה לו לעשות]\u0006 יתר מכן? \u0003אמר רבא אמר ר' יצחק: אמר קרא\u0004 \u0005[הכתוב]\u0006 \u0003\"וצרת הכסף בידך\"\u0004 (דברים יד, כה), מכאן נלמד: \u0003אף על פי שצרורין\u0004 — \u0003יהיו בידך\u0004 ולא במקום אחר.","ואגב כך מביאים אמרה דומה ש\u0003אמר ר' יצחק: לעולם יהא כספו של אדם מצוי בידו,\u0004 שלא ישקיע כל כספו בעסקים ולא ישאר לו כסף מזומן, ורמז לדבר — \u0003שנאמר: \"וצרת הכסף בידך\"\u0004 (שם). \u0003ואמר ר' יצחק\u0004 כעצה טובה: \u0003לעולם ישליש\u0004 (יחלק לשלושה) \u0003אדם מעותיו, שליש\u0004 יטמין \u0003בקרקע, שליש\u0004 ישקיע \u0003בפרקמטיא\u0004 (מסחר) \u0003ושליש תחת ידו.\u0004","ועוד דברים דומים: \u0003ואמר ר' יצחק: אין הברכה מצויה אלא בדבר הסמוי מן העין\u0004 שאינו נראה ואינו גלוי, \u0003שנאמר: \"יצו ה' אתך את הברכה באסמיך\"\u0004 (דברים כח, ח) במחסנים, במקום שאין רואים אותו. כיוצא בזה \u0003תנא דבי\u0004 \u0005[שנה\u0006 החכם \u0005בבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ישמעאל:\u0004 \u0003אין הברכה מצויה אלא בדבר שאין העין שולטת בו, שנאמר \"יצו ה' אתך את הברכה באסמיך\"\u0004 (שם).","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003ההולך למוד\u0004 (למדוד) \u0003את גורנו, אומר: \"יהי רצון מלפניך ה' אלהינו שתשלח ברכה במעשה ידינו\". התחיל למוד, אומר: \"ברוך השולח ברכה בכרי הזה\". מדד ואחר כך בירך\u0004 ברכה זו — \u0003הרי זה תפילת שוא, לפי שאין הברכה מצויה לא בדבר השקול ולא בדבר המדוד ולא בדבר המנוי, אלא בדבר הסמוי מן העין, שנאמר: \"יצו ה' אתך את הברכה באסמיך\".\u0004","\u0003אמר שמואל: כספים אין להם שמירה אלא\u0004 אם טומנם \u0003בקרקע,\u0004 וזוהי דרך שמירתם הראויה. \u0003אמר רבא: ומודי\u0004 \u0005[ומודה]\u0006 \u0003שמואל\u0004 שאם קבל פקדון \u0003בערב שבת בין השמשות,\u0004 ש\u0003לא אטרחוהו רבנן\u0004 \u0005[הטריחוהו חכמים]\u0006 לטומנם מיד בקרקע. \u0003ו\u0004אולם \u0003אי שהא\u0004 \u0005[אם שהה]\u0006 \u0003למוצאי שבת שעור\u0004 כדי \u0003למקברינהו\u0004 \u0005[לקברם]\u0006 \u0003ולא קברינהו\u0004 \u0005[קברם]\u0006 — \u0003מחייב\u0004 \u0005[חייב]\u0006 באחריות אם נגנבו. \u0003ואי צורבא מרבנן\u0004 \u0005[ואם תלמיד חכם]\u0006 \u0003הוא\u0004 המפקיד ו\u0003סבר\u0004 השומר: \u0003דלמא מיבעי ליה זוזי לאבדלתא\u0004 \u0005[שמא יהיו צריכים לו כספים להבדלה]\u0006 ולכן לא טמנם מיד — מותר לו להמתין מעט.","ומעירים: \u0003והאידנא דשכיחי גשושאי\u0004 \u0005[ועכשיו שמצויים\u0006 גנבים \u0005המגששים\u0006 בקרקע\u0005]\u0006 לחפש שם דברים טמונים — \u0003אין\u0004 לכספים \u0003שמירה אלא\u0004 כאשר שם אותם \u0003בשמי קורה\u0004 (בקורות הגג בבית). ומעירים: \u0003והאידנא דשכיחי פרומאי\u0004 \u0005[ועכשיו שמצויים\u0006 גנבים \u0005הפורמים\u0006 את הגגות\u0005]\u0006 לחפש מה שהטמינו שם — \u0003אין להם שמירה אלא ביני אורבי\u0004 \u0005[\u0006כשמטמינים \u0005בין הלבנים\u0006 שבקיר\u0005].\u0006 \u0003אמר רבא: ומודה שמואל\u0004 שהיא שמירה ראויה אם הטמינם \u0003בכותל, אי נמי\u0004 \u0005[או גם כן]\u0006 \u0003בין הקרנות\u0004 (פינות הבית). \u0003והאידנא דשכיחי טפוחאי\u0004 \u0005[ועכשיו שמצויים\u0006 גנבים \u0005הטופחים\u0006 על הכתלים\u0005]\u0006 לדעת אם טמון שם דבר, \u0003אין להן שמירה אלא בטפח הסמוך לקרקע\u0004 בתוך הקיר, ששם אי אפשר לגלות את המקום על ידי טפיחה, \u0003או בטפח הסמוך לשמי קורה.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אחא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יוסף לרב אשי: התם תנן\u0004 \u0005[שם\u0006 במסכת פסחים \u0005שנינו]:\u0006 \u0003חמץ שנפלה עליו מפולת\u0004 — \u0003הרי הוא\u0004 נחשב \u0003כמבוער\u0004 שהרי החמץ ישאר תמיד טמון שם. \u0003רבן שמעון בן גמליאל אומר: כל שאין הכלב יכול לחפש אחריו\u0004 הרי הוא כמבוער. \u0003ותנא\u0004 \u0005[ושנה]\u0006 החכם: \u0003כמה חפישת הכלב\u0004 — \u0003שלשה טפחים.\u0004 והשאלה היא: \u0003הכא מאי\u0004 \u0005[כאן מה\u0006 הדין\u0005]?\u0006 \u0003מי בעינן\u0004 \u0005[האם צריכים אנו]\u0006 בהטמנת כספים להעמיק \u0003שלשה טפחים או לא?\u0004","\u0003אמר ליה\u0004 \u0005[אמר לו]\u0006 רב אשי: \u0003התם\u0004 \u0005[שם]\u0006 \u0003משום ריחא\u0004 \u0005[הריח]\u0006 של החמץ \u0003בעינן\u0004 \u0005[צריכים אנו]\u0006 \u0003שלשה טפחים,\u0004 שכן הכלב מריח ומחטט שם. \u0003הכא\u0004 \u0005[כאן]\u0006 בטמינת כסף שהוא \u0003משום איכסויי מעינא\u0004 \u0005[כיסוי מן העין]\u0006 — \u0003לא בעינן\u0004 \u0005[אין אנו צריכים]\u0006 \u0003שלשה טפחים\u0004 ודי בפחות מזה. ושואלים: \u0003וכמה? אמר רפרם\u0004 מן המקום \u0003סיכרא: טפח\u0004 אחד.","מסופר: \u0003ההוא גברא דאפקיד זוזי גבי חבריה, אותבינהו בצריפא דאורבני, איגנוב\u0004 \u0005[אדם אחד הפקיד כספים אצל חבירו, הניחם\u0006 החבר \u0005בצריף\u0006 עשוי מענפי \u0005ערבות,\u0006 ומשם \u0005נגנב\u0006 הכסף\u0005].\u0006 \u0003אמר רב יוסף: אף על גב\u0004 \u0005[אף על פי]\u0006 ש\u0003לענין גנבי\u0004 \u0005[גנבים]\u0006 \u0003נטירותא\u0004 \u0005[שמירה]\u0006 \u0003היא,\u0004 שהרי המקום שמור כשאר המקומות, ואולם \u0003לענין נורא\u0004 \u0005[אש]\u0006 — \u0003פשיעותא\u0004 \u0005[פשיעה,\u0006 רשלנות\u0005]\u0006 \u0003היא,\u0004 שהרי הכל עלול להישרף, \u0003הוה\u0004 \u0005[הרי זה]\u0006 מקרה \u0003ש\u0004\u0003תחלתו בפשיעה\u0004 (בחוסר זהירות, ברשלנות) \u0003וסופו באונס,\u0004 ומשום כך \u0003חייב. ואיכא דאמרי\u0004 \u0005[ויש אומרים]\u0006 להיפך, שכך אמר: \u0003אף על גב\u0004 \u0005[אף על פי]\u0006 ש\u0003לענין נורא\u0004 \u0005[אש]\u0006 — \u0003פשיעותא\u0004 \u0005[פשיעה]\u0006 \u0003היא, לענין גנבי\u0004 \u0005[גנבים]\u0006 — \u0003נטירותא\u0004 \u0005[שמירה]\u0006 \u0003היא\u0004 \u0003ותחלתו בפשיעה, וסופו באונס\u0004 — \u0003פטור.\u0004 ומסכמים: \u0003והילכתא\u0004 \u0005[והלכה]\u0006 למעשה בבעיה זו: כל דבר ש\u0003תחילתו בפשיעה\u0004 ברשלנות אף על פי ש\u0003סופו באונס\u0004 — \u0003חייב.\u0004","ועוד מסופר: \u0003ההוא גברא דאפקיד זוזי גבי חבריה\u0004 \u0005[אדם אחד הפקיד כספים אצל חבירו]\u0006 לאחר זמן \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003הב\u0004 \u0005[תן]\u0006 \u0003לי זוזאי\u0004 \u0005[כספי]!\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 החבר: \u0003לא ידענא היכא אותבינהו\u0004 \u0005[אינני יודע,\u0006 אינני זוכר, \u0005היכן הנחתי אותם].\u0006 \u0003אתא לקמיה\u0004 \u0005[בא\u0006 הדבר \u0005לפני]\u0006 \u0003רבא,\u0004 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003כל \"לא ידענא\"\u0004 \u0005[\"אינני יודע\"]\u0006 \u0003פשיעותא\u0004 \u0005[פשיעה,\u0006 רשלנות\u0005]\u0006 \u0003היא, זיל\u0004 \u0005[לך]\u0006 ו\u0003שלם.\u0004","ועוד מסופר:, \u0003ההוא גברא דאפקיד זוזי גבי חבריה\u0004 \u0005[אדם אחד הפקיד כספים אצל חבירו].\u0006 \u0003אשלמינהו לאימיה, ואותבינהו בקרטליתא, ואיגנוב\u0004 \u0005[מסר\u0006 החבר את הכספים \u0005לאמו,\u0006 והיא \u0005הניחה אותם בארגז ונגנבו].\u0006 \u0003אמר רבא: היכי נדיינו דייני להאי דינא\u0004 \u0005[איך ידונו דיינים דין זה]?\u0006 כי יש בו בעיה על מי חלה האחריות.","אם \u0003נימא ליה לדידיה: זיל שלים\u0004 \u0005[לך ושלם],\u0006 יכול ההוא לומר:"],["הלא כלל הוא: \u0003כל המפקיד על דעת אשתו ובניו הוא מפקיד,\u0004 ולכן נהגתי כראוי שמסרתי לאמי.","\u0003נימא\u0004 \u0005[נאמר]\u0006 \u0003לה לאימיה\u0004 \u0005[לאמו]:\u0006 \u0003זילי שלימי\u0004 \u0005[לכי\u0006 ו\u0005שלמי]\u0006 \u0003אמרה\u0004 \u0005[\u0006יכולה היא \u0005לומר]:\u0006 \u0003לא אמר לי\u0004 בני \u0003דלאו דידיה נינהו דאקברינהו\u0004 \u0005[שאין\u0006 הכספים \u0005שלו כדי שאקבור אותם]\u0006 שהיא שמירה מעולה.","ואם \u0003נימא ליה\u0004 \u0005[נאמר לו]:\u0006 \u0003אמאי\u0004 \u0005[מדוע]\u0006 \u0003לא אמרת לה\u0004 שאין הכספים שלך? \u0003אמר: כל שכן, דכי אמינא\u0004 \u0005[שאם אומר]\u0006 \u0003לה דדידי נינהו\u0004 \u0005[ש\u0006הכספים \u0005שלי הם]\u0006 — \u0003טפי מזדהרא בהו\u0004 \u0005[יותר היא נזהרת בהם].\u0006","\u0003אלא אמר רבא\u0004 כך יש לדון: \u0003משתבע איהו דהנהו זוזי אשלמינהו לאימיה\u0004 \u0005[ישבע הוא,\u0006 האיש, \u0005שאת הכספים הללו מסר לאמו],\u0006 \u0003ומשתבעא אימיה דהנהו זוזי אותבינהו בקרטליתא ואיגנוב\u0004 \u0005[ותישבע אמו שאת הכספים הללו הניחה בארגז ונגנבו]\u0006 \u0003ופטור\u0004 מלשלם.","ומסופר עוד: \u0003ההוא אפוטרופא דיתמי דזבן להו תורא ליתמי ומסריה לבקרא\u0004 \u0005[אפוטרופוס אחד של יתומים שקנה שור עבור היתומים ומסר אותו לרועה הבקר].\u0006 \u0003לא הוו ליה\u0004 \u0005[היו לו]\u0006 לשור זה \u0003ככי ושיני למיכל, ומית\u0004 \u0005[ניבים ושיניים לאכול\u0006 בהם \u0005ו\u0006כיון שלא נתנו לו מזון מיוחד \u0005מת\u0006 השור\u0005].\u0006 \u0003אמר רמי בר חמא: היכי נדיינו דייני להאי דינא\u0004 \u0005[איך ידונו דיינים בדין זה]?\u0006","\u0003נימא ליה לאפוטרופא\u0004 \u0005[נאמר לו לאפוטרופוס]:\u0006 \u0003זיל שלים\u0004 \u0005[לך שלם\u0006 את הנזק\u0005],\u0006 \u0003אמר: אנא לבקרא מסרתיה\u0004 \u0005[אני לרועה הבקר מסרתי אותו]\u0006 והוא צריך היה לטפל בו.","\u0003נימא ליה לבקרא\u0004 \u0005[נאמר לו לרועה הבקר]:\u0006 \u0003זיל שלים\u0004 \u0005[לך ושלם],\u0006 \u0003אמר: אנא בהדי תורי אוקימתיה, אוכלא שדאי ליה\u0004 \u0005[אני בין השוורים העמדתי אותו, אוכל שמתי לפניו],\u0006 ו\u0003לא הוה ידעינן דלא אכל\u0004 \u0005[ידעתי שאין הוא אוכל].\u0006","ושואלים: \u0003מכדי בקרא\u0004 \u0005[הלא רועה הבקר]\u0006 \u0003שומר שכר דיתמי\u0004 \u0005[של היתומים]\u0006 \u0003הוא\u0004 ואם כן \u0003איבעי ליה לעיוני אי איכא פסידא דיתמי\u0004 \u0005[היה לו לבדוק אם יש הפסד ליתומים]\u0006 ולראות אם השור אוכל! ומשיבים: \u0003הכי נמי\u0004 \u0005[כך הוא גם כן]\u0006 אילו כך היה המקרה, ואולם \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 — באופן \u0003דליכא פסידא דיתמי\u0004 \u0005[שאין הפסד ליתומים]\u0006 יוצא מזה, \u0003דאשכחוהו למריה דתורא ושקול יתמי זוזי מיניה\u0004 \u0005[שמצאוהו את בעל השור וקבלו היתומים את הכסף ממנו\u0006 בחזרה\u0005].\u0006","ושואלים: \u0003אלא מאן קא טעין\u0004 \u0005[מי הוא זה שטוען]\u0006 — \u0003מריה דתורא קטעין\u0004 \u0005[בעל השור הוא שטוען]\u0006 לאפוטרופוס, אם כן אומרים לו: \u0003איבעי ליה לאודוען\u0004 \u0005[היה לו להודיענו]\u0006 שהשור איננו אוכל! ומשיבים: \u0003מאי מודעינן ליה\u0004 \u0005[מה מודיעים אנו לו]\u0006 — הלא \u0003מידע ידע\u0004 \u0005[יודע\u0006 הוא\u0005]\u0006 ש\u0003מקח טעות הוי\u0004 \u0005[הוא].\u0006 ומשיבים: מדובר כאן \u0003בספסירא דזבן הכא ומזבין להכא\u0004 \u0005[בסרסור שקונה מכאן ומוכר לשם]\u0006 ולא ידע מה טיב השור, \u0003הלכך\u0004 (על כן) \u0003מישתבע איהו\u0004 \u0005[נשבע הוא]\u0006 ש\u0003לא הוה ידע\u0004 \u0005[ידע]\u0006 בפגמו של השור, \u0003ומשלם בקרא\u0004 \u0005[ומשלם רועה הבקר]\u0006 לא את דמי השור כולו אלא \u0003דמי בשר בזול\u0004 שהוא חלק ממחיר השור.","מסופר: \u0003ההוא גברא דאפקיד כשותא גבי חבריה\u0004 \u0005[אדם אחד הפקיד\u0006 כמות של \u0005כשות אצל חברו],\u0006 היא הכשות שמטילים כתבלין בעשיית שיכר. \u0003הוה ליה לדידיה נמי כריא דכשותא\u0004 \u0005[היה לו עצמו גם כן כרי,\u0006 ערימה, \u0005של כשות].\u0006 \u0003אמר ליה לסרסיה\u0004 \u0005[לו לממונה\u0006 על השיכר\u0005]:\u0006 \u0003מהאי רמי\u0004 \u0005[\u0006\u0005מזה,\u0006 מהכרי שלי, \u0005הטל\u0006 לשיכר\u0005].\u0006 \u0003אזל רמא מאידך\u0004 \u0005[הלך\u0006 האיש \u0005והטיל\u0006 לשיכר \u0005מן\u0006 הערימה \u0005האחרת,\u0006 של המפקיד\u0005].\u0006 \u0003אמר רב עמרם: היכי נדיינו דייני להאי דינא\u0004 \u0005[איך ידונו דיינים דין זה]?\u0006","\u0003נימא ליה לדידיה\u0004 \u0005[נאמר לו\u0006 לשומר הפיקדון\u0005]:\u0006 \u0003זיל שלים\u0004 \u0005[\u0006\u0005לך שלם],\u0006 \u0003אמר\u0004 שומר הפקדון: \u0003אנא אמרי ליה מהאי רמי\u0004 \u0005[אני אמרתי לו\u0006 לעובד שלי \u0005מזה תטיל]\u0006 ואינני אחראי.","\u0003נימא ליה לסרסיה\u0004 \u0005[נאמר לו לממונה]:\u0006 \u0003זיל שלים\u0004 \u0005[לך ושלם],\u0006 \u0003אמר\u0004 הממונה: \u0003לא אמר לי\u0004 בעל הבית \u0003מהאי רמי ומהאי\u0004 \u0005[מזה הטל ומזה]\u0006 \u0003לא תרמי\u0004 \u0005[תטיל]\u0006 וחשבתי שרק עצה טובה הוא נותן, ולא ידעתי שיש חשיבות מיוחדת בדבר.","ומעירים: \u0003ואי דשהא\u0004 \u0005[ואם שהה]\u0006 בינתיים \u0003שיעור\u0004 זמן כדי \u0003לאיתויי ליה\u0004 \u0005[להביא לו]\u0006 את הכשות \u0003ולא אייתי ליה\u0004 \u0005[הביא לו]\u0006 — אם כן בכך \u0003גלי אדעתיה דניחא ליה\u0004 \u0005[גילה דעתו שנוח\u0006 היה \u0005לו בכך]\u0006 כי אם היתה ערימת הכשות שלו במקום רחוק ושל הפקדון במקום קרוב, והוא הקדים ובא ולקח משם, אם כן יכול היה השומר לדעת בעצמו מה אירע! ומשיבים: מדובר כאן בש \u0003לא שהא\u0004 \u0005[שהה],\u0006 או שלא היה הבדל במרחק, או שעשה זאת באותו זמן.","ושואלים: \u0003סוף סוף, מאי פסידא איכא, והא קא משתרשי ליה\u0004 \u0005[סוף סוף, מה הפסד יש בכך, והלא הוא מרווח בזה]!\u0006 ואם כן, ישלם השומר דמי הכשות שנטל מן הפקדון, והכל יבוא על מקומו בשלום! \u0003אמר רב סמא בריה\u0004 \u0005[בנו]\u0006 של \u0003רבא:\u0004 מדובר כאן באופן \u0003דהוה שיכרא חלא\u0004 \u0005[שנהיה השיכר חומץ,\u0006 שהחמיץ השיכר\u0005]\u0006 ואם כן נמצא שאי אפשר לקבל את דמי הכשות מן השיכר. \u0003רב אשי אמר:\u0004 מדובר כאן \u0003בכיסי\u0004 \u0005[בקוצים]\u0006 שהיתה הכשות הזו מעורבת בקוצים, ולא השביחה את השיכר כראוי."],["\u0003ומשלם ליה\u0004 \u0005[לו]\u0006 \u0003דמי כיסי\u0004 \u0005[קוצים,\u0006 כשות גרועה\u0005]\u0006 לפי מה שהרויח.","\u0003המפקיד מעות אצל שולחני\u0004 שעיסוקו בהחלפת כספים, \u0003אם\u0004 היו הכספים \u0003צרורין\u0004 — \u0003לא ישתמש בהן, לפיכך אם אבדו\u0004 — \u0003אינו חייב באחריותן.\u0004 אם היו הכספים \u0003מותרין\u0004 — \u0003ישתמש בהן, לפיכך אם אבדו חייב באחריותן.\u0004 אבל אם הפקיד מעות \u0003אצל בעל הבית, בין\u0004 היו \u0003צרורין ובין מותרין\u0004 — \u0003לא ישתמש בהן,\u0004 שלא העלה בדעתו שישתמש בהם. \u0003לפיכך אם אבדו\u0004 — \u0003אינו חייב באחריותן. חנוני\u0004 דינו לענין זה \u0003כבעל הבית,\u0004 אלו \u0003דברי ר' מאיר. ר' יהודה אומר: חנוני\u0004 דינו \u0003כשולחני.\u0004","ושואלים: וכי \u0003משום\u0004 שהיו הכספים \u0003צרורין לא ישתמש בהן?\u0004 הלא בדרך כלל נוהגים בני אדם לצרור כספים, ואין זה מוכיח שכוונתם שלא יוציאו אותם! \u0003אמר רב אסי אמר רב יהודה: ב\u0004מקרה \u0003שהיו המעות\u0004 \u0003צרורין וחתומין שנו\u0004 כאן, שברור שאינו רוצה שיפתחו את הצרור. \u0003רב מרי אמר:\u0004 מדובר באופן שהיו קשורים \u0003בקשר משונה,\u0004 שאף הוא סימן שאינו רוצה שיפתחוהו. \u0003איכא דאמרי\u0004 \u0005[יש אומרים]\u0006 בלשון אחרת: \u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רב מרי:\u0004 אם היו קשורים \u0003בקשר משונה מאי\u0004 \u0005[מה]\u0006 הדין, האם הם כחתומים, או לא? לשאלה זו לא ניתנה תשובה, ועל כן \u0003תיקו\u0004 \u0005[תעמוד]\u0006 במקומה.","שנינו במשנה שאם היו הכספים \u0003מותרין ישתמש בהן\u0004 ולפיכך חייב באחריותן. \u0003אמר רב הונא: ואפילו נאנסו\u0004 (ניטלו ממנו באונס) חייב לשלם עבורם. ומקשים: \u0003והא \"אבדו\" קתני\u0004 \u0005[שנה],\u0006 משמע רק אבדו, ולא באונס! ומשיבים: צריכים להבין זאת כפי שאמר \u0003רבה\u0004 בענין אחר, ש\u0003אמר רבה:\u0004 מה שאמרו שם \u0003\"נגנבו\"\u0004 — כוונתו \u0003בלסטין מזויין\u0004 שהוא אונס של שוד, \u0003\"אבדו\"\u0004 — \u0003שטבעה ספינתו בים.\u0004","\u0003ורב נחמן אמר\u0004 שלא כדברי רב הונא; אם \u0003נאנסו\u0004 הוא \u0003לא\u0004 חייב. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא לרב נחמן:\u0004 \u0003לדידך\u0004 \u0005[לשיטתך]\u0006 ש\u0003אמרת\u0004 \u0003נאנסו לא, אלמא לא הוי\u0004 \u0005[מכאן שאינו\u0006 נחשב\u0005]\u0006 כ\u0003שואל עלייהו\u0004 \u0005[עליהם],\u0006 ואולם \u0003אי\u0004 \u0005[אם]\u0006 \u0003שואל לא הוי\u0004 \u0005[איננו\u0006 נחשב\u0005]\u0006 — \u0003שומר שכר נמי לא הוי\u0004 \u0005[גם כן איננו\u0006 נחשב\u0005]\u0006 עליהם, ומדוע איפוא חייב באחריותם אפילו כשאבדו? יהא כשומר חנם ויפטר! \u0003אמר\u0004 לו רב נחמן: \u0003בהא מודינא\u0004 \u0005[בזה מודה אני]\u0006 \u0003לך,\u0004 ש\u0003הואיל ונהנה מהנה\u0004 \u0005[ונהנה]\u0006 מהכספים, \u0003בההוא\u0004 \u0005[באותה]\u0006 \u0003הנאה דאי מיתרמי ליה זבינא דאית בה רווחא זבן בהו\u0004 \u0005[באותו הנאה שאם יזדמן לו מקח שיש בו רווח יקנה בהם],\u0006 \u0003הוי עלייהו\u0004 \u0005[נעשה עליהם]\u0006 \u0003שומר שכר.\u0004","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003רב נחמן לרב הונא\u0004 ממה ששנינו: \u0003המפקיד מעות אצל שולחני, אם\u0004 היו \u0003צרורין\u0004 — \u0003לא ישתמש בהן, לפיכך אם הוציא\u0004 ונתברר שהיו אלה מעות הקדש — \u0003לא מעל הגזבר\u0004 שהפקיד את המעות אצל השולחני, לפי שהמעילה נעשתה על ידי השולחני, ולא על ידי הגזבר. \u0003ואם\u0004 היו הכספים \u0003מותרין\u0004 — \u0003ישתמש בהן, לפיכך אם הוציא\u0004 — \u0003מעל הגזבר.\u0004","\u0003ואי אמרת\u0004 \u0005[ואם אומר אתה]\u0006 ש\u0003אפילו\u0004 כאשר \u0003נאנסו\u0004 חייב עליהם, \u0003מאי איריא\u0004 \u0005[מה שייך,\u0006 מדוע דווקא\u0005]\u0006 שנינו זאת באופן ש\u0003הוציא? אפילו לא הוציא נמי\u0004 \u0005[גם כן]\u0006 כיון שנתן לו כספים מותרין, ולשיטתך הרי הוא כמשאילם לו במפורש, והרי זה כאילו הוציאם מיד מרשות ההקדש!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רב הונא: \u0003הוא הדין אף על גב\u0004 \u0005[אף על פי]\u0006 ש\u0003לא הוציא,\u0004 ומיד שנמסרו הכספים לידי השולחני חייב הגזבר עליהם, \u0003ואיידי דתנא רישא\u0004 \u0005[ומתוך ששנה בראש\u0006 הברייתא\u0005]\u0006 דווקא \u0003\"הוציא\", תנא סיפא נמי\u0004 \u0005[שנה בסופה גם כן]\u0006 בלשון \u0003\"הוציא\"\u0004 אבל אין זה מדוייק, שכיון שמסר בידו לשימוש הרי זה כאילו הוציאם.","\u0003השולח יד בפקדון\u0004 לקחת ממנו עבור עצמו, \u0003בית שמאי אומרים: ילקה בחסר וביתר.\u0004 כלומר, אם ירדו המחירים — ישלם כשעת הגזילה, אם עלו המחירים — ישלם כבשעה שצריך לשלם. \u0003ובית הלל אומרים:\u0004 ישלם \u0003כשעת הוצאה. ר' עקיבא אומר:\u0004 ישלם \u0003כשעת התביעה.\u0004","\u0003אמר רבה: האי מאן דגזל חביתא דחמרא מחבריה\u0004 \u0005[מי שגזל חבית יין מחבירו],\u0006 \u0003מעיקרא שויא זוזא השתא שויא\u0004 \u0005[מתחילה שווה זוז\u0006 אחד \u0005ועכשיו שווה]\u0006 \u0003ארבעה,\u0004 אם \u0003תברה\u0004 \u0005[שברה]\u0006 \u0003או שתייה\u0004 \u0005[שתה]\u0006 ממנה — \u0003משלם ארבעה\u0004 זוזים, ואם \u0003איתבר ממילא\u0004 \u0005[נשברה מעצמה]\u0006 — \u0003משלם\u0004 רק \u0003זוזא\u0004 \u0005[זוז\u0006 אחד\u0005].\u0006","ומסביר: \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 ההבדל — \u0003כיון דאי איתה הדרא למרה בעינא\u0004 \u0005[כיון שאילו היתה\u0006 שלמה \u0005היתה חוזרת לבעליה בעינה]\u0006 ולא היה צריך להתחשב במחיר, אם כן נמצא כי \u0003ההיא שעתא דקא שתי ליה\u0004 \u0005[באותה שעה ששתה אותו]\u0006 \u0003או דקא תבר לה\u0004 \u0005[ששבר אותה]\u0006 היא השעה שבה \u0003קא גזל מיניה\u0004 \u0005[גוזל ממנו\u0006 למעשה\u0005],\u0006 \u0003ותנן\u0004 \u0005[ושנינו\u0006 במשנה\u0005]:\u0006 \u0003כל הגזלנין משלמין כשעת הגזילה,\u0004 ובשעת הגזילה היתה שווה כבר ארבעה. ואולם אם \u0003איתבר ממילא\u0004 \u0005[אם נשברה מעצמה]\u0006 \u0003משלם זוזא\u0004 \u0005[זוז\u0006 אחד\u0005].\u0006 \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר — \u0003השתא\u0004 \u0005[עכשיו]\u0006 הרי \u0003לא עביד לה ולא מידי\u0004 \u0005[עשה בה דבר],\u0006 \u0003אמאי קא מחייבת ליה\u0004 \u0005[על מה אתה מחייב אותו]\u0006 לשלם — \u0003אההיא שעתא\u0004 \u0005[על אותה שעה]\u0006 ש\u0003גזלה,\u0004 \u0003ההיא שעתא זוזא הוא דשויא\u0004 \u0005[באותה שעה זוז\u0006 בלבד \u0005היתה שווה\u0006 ולא יותר\u0005].\u0006","\u0003תנן\u0004 \u0005[שנינו\u0006 במשנתנו\u0005]\u0006 ש\u0003בית הלל אומרים\u0004 שהשולח יד בפקדון הריהו משלם \u0003כשעת הוצאה.\u0004 ושואלים: \u0003מאי\u0004 \u0005[מה]\u0006 פירוש \u0003כשעת הוצאה? אילימא\u0004 \u0005[תאמר]\u0006 \u0003כשעת הוצאה מן העולם,\u0004 כלומר, כשעת השימוש בדבר.","\u0003ובמאי\u0004 \u0005[ובמה\u0006 מדובר\u0005]?\u0006 \u0003אי\u0004 \u0005[אם]\u0006 \u0003בחסר,\u0004 כשירד המחיר עד זמן השימוש, \u0003מי איכא למאן דאמר\u0004 \u0005[האם יש מי שאומר]\u0006 בכגון זה שימצאו הבעלים נחסרים על ידי כך? \u0003והא תנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]:\u0006 \u0003כל הגזלנין משלמין כשעת הגזילה,\u0004 משמע: ולא פחות מזה! \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003ביתר,\u0004 שעלה המחיר משעת הגזילה עד שעת הוצאה — אם כן \u0003היינו\u0004 \u0005[זוהי]\u0006 שיטת \u0003בית שמאי,\u0004 שהרי נמצא שולח היד לוקה בחסר וביתר!"],["\u0003אלא פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005]\u0006 שצריך לפרש \u0003כשעת הוצאה מבית בעלים,\u0004 כלומר, בשעת הגזילה. אם כן, \u0003לימא\u0004 \u0005[האם לומר]\u0006 כי \u0003רבה\u0004 אמר כדעת \u0003בית שמאי\u0004 ולא כדעת בית הלל?! ודוחים: \u0003אמר\u0004 \u0005[\u0006יכול היה \u0005לומר]\u0006 \u0003לך רבה:\u0004 \u0003ביתר\u0004 — \u0003כולי עלמא לא פליגי\u0004 \u0005[הכל אינם חולקים],\u0006 \u0003כי פליגי\u0004 \u0005[כאשר נחלקו]\u0006 הרי זה \u0003בחסר.\u0004","וזו היא המחלוקת: \u0003בית שמאי סברי\u0004 \u0005[סבורים]\u0006 ש\u0003שליחות יד אינה צריכה חסרון\u0004 וגם אם לא חסר דבר מן הפקדון, די בעצם העובדה שלקח את הדבר לעצמו שייחשב מאותה שעה כגוזלו, וממילא, \u0003כי\u0004 \u0005[כאשר]\u0006 \u0003חסר\u0004 מערך הדבר שהשתמש בו — \u0003ברשותא דידיה\u0004 \u0005[ברשותו שלו]\u0006 \u0003חסר\u0004 וחייב לשלם. \u0003ובית הלל סברי\u0004 \u0005[סבורים]\u0006 שאינו צריך לשלם, לפי שאין דומה שליחות יד לגזילה, שלא קנסוהו בשליחות יד, שהרי בהיתר הגיעה לידו, ולדעתם \u0003שליחות יד צריכה חסרון\u0004 ועל מה שלא לקח ממנה בפועל לא התחייב, וממילא \u0003כי\u0004 \u0005[כאשר]\u0006 \u0003חסר\u0004 — \u0003ברשותא דמריה\u0004 \u0005[ברשות בעליה]\u0006 \u0003חסר\u0004 ערך החבית, ומעריכים לפי שעת הגזילה.","ומקשים: \u0003אלא הא\u0004 \u0005[\u0006הלכה \u0005זו]\u0006 ש\u0003אמר רבא\u0004 ש\u0003שליחות יד אינה צריכה חסרון, לימא\u0004 \u0005[האם לומר]\u0006 כי \u0003רבא\u0004 \u0003אמר כ\u0004דעת \u0003בית שמאי?! אלא, הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 — \u0003כגון שטלטלה\u0004 לא בשליחות יד לקחת מתוכן החבית ולשתות ממנה, אלא להשתמש בה כבסולם \u0003להביא עליה גוזלות.\u0004 \u0003ובשואל שלא מדעת קא מיפלגי\u0004 \u0005[חלוקים הם];\u0006","\u0003בית שמאי סברי\u0004 \u0005[סבורים]:\u0006 \u0003שואל שלא מדעת\u0004 — \u0003גזלן הוי\u0004 \u0005[הוא],\u0006 ולכן משטלטל את החבית נחשב כגוזלה \u0003ו\u0004ממילא \u0003כי חסר\u0004 \u0005[כאשר חסרה\u0006 החבית\u0005]\u0006 — \u0003ברשותא דידיה חסר\u0004 \u0005[ברשות שלו,\u0006 של הגוזל, \u0005חסרה].\u0006 \u0003ובית הלל סברי\u0004 \u0005[סבורים]:\u0006 \u0003שואל שלא מדעת\u0004 — \u0003שואל הוי.\u0004 \u0003ו\u0004ממילא, \u0003כי\u0004 \u0005[כאשר]\u0006 \u0003חסר\u0004 מתוכנה — \u0003ברשותא דמרה\u0004 \u0005[ברשות בעליה]\u0006 \u0003חסר.\u0004","ותוהים על כך: אם כן \u0003הא\u0004 \u0005[\u0006הלכה \u0005זו]\u0006 ש\u0003אמר רבא:\u0004 אלא \u0003שואל שלא מדעת\u0004 — \u0003לרבנן\u0004 \u0005[ל\u0006דעת \u0005חכמים]\u0006 \u0003גזלן הוי\u0004 \u0005[הוא],\u0006 אם כן \u0003לימא\u0004 \u0005[האם נאמר]\u0006 ש\u0003רבא\u0004 הוא ש\u0003אמר\u0004 את דבריו \u0003כ\u0004דעת \u0003בית שמאי?\u0004 \u0003אלא\u0004 יש לדחות כל מה שהסברנו עד כה, ולומר שחסר ויתר אינו שינוי במחירי השוק, אלא במה שחסרה הבהמה כאשר גזזו אותה, או מה שהותירה בוולדות וכדומה, ו\u0003הכא\u0004 \u0005[כאן]\u0006 \u0003בשבח של גזילה\u0004 כעין זה \u0003קמיפלגי\u0004 \u0005[חלוקים הם]\u0006 למי מגיע שבח זה. \u0003בית שמאי סברי\u0004 \u0005[סבורים]:\u0006 \u0003שבח גזילה\u0004 של \u0003נגזל הוי\u0004 \u0005[הוא],\u0006 \u0003ובית הלל סברי\u0004 \u0005[סבורים]\u0006 \u0003שבח גזילה\u0004 של \u0003גזלן הוי\u0004 \u0005[הוא],\u0006","\u0003ובפלוגתא דהני תנאי\u0004 \u0005[ובמחלוקת של תנאים אלה]\u0006 נחלקו, \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003הגוזל את הרחל\u0004 (כבשה), \u0003גזזה\u0004 או \u0003ילדה\u0004 — \u0003משלם אותה ואת גיזתיה ואת ולדותיה,\u0004 אלו \u0003דברי ר' מאיר. ר' יהודה אומר: גזילה חוזרת בעיניה,\u0004 כפי שהיא.","ומעירים: \u0003דיקא נמי\u0004 \u0005[מדוייק גם כן]\u0006 שזהו פירוש משנתנו, ש\u0003בית שמאי אומרים ילקה בחסר וביתר\u0004 ולא אמרו שילקה ביוקר וזול, \u0003ובית הלל אומרים: כשעת הוצאה.\u0004 אם כן, \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שכן הוא הענין, ובזה נחלקו.","שנינו במשנה כי \u0003ר' עקיבא אומר\u0004 שישלם \u0003כשעת התביעה. אמר רב יהודה אמר שמואל: הלכה כ\u0004שיטת \u0003ר' עקיבא.\u0004 \u0003ו\u0004אולם \u0003מודה ר' עקיבא במקום שיש עדים\u0004 שראו בשליחות יד, שמחשבים לפי אותו זמן. \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר\u0005]\u0006 — ש\u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 \u0003\"לאשר הוא לו יתננו ביום אשמתו\"\u0004 (ויקרא ה, כד), \u0003וכיון דאיכא\u0004 \u0005[שיש]\u0006 \u0003עדים\u0004 לגזילה, אם כן \u0003מההוא שעתא\u0004 \u0005[מאותה שעה]\u0006 של הגזילה — \u0003הוא דאיחייב ליה\u0004 \u0005[שהתחייב לו]\u0006 ב\u0003אשמה.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' אושעיא לרב יהודה: רבי, אתה אומר כן? הכי\u0004 \u0005[כך]\u0006 \u0003אמר ר' אסי אמר ר' יוחנן: חלוק היה ר' עקיבא אפילו במקום שיש עדים, ומאי טעמא\u0004 \u0005[ומה\u0006 טעם] — ש\u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 \u0003\"לאשר הוא לו יתננו ביום אשמתו\"\u0004 (שם), \u0003ובי דינא הוא דקא מחייבי ליה\u0004 \u0005[ובית הדין הם שמחייבים אותו]\u0006 ב\u0003אשמה\u0004 ולא העדים.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' זירא לר' אבא בר פפא: כי אזלת להתם\u0004 \u0005[כאשר הולך אתה לשם,\u0006 לארץ ישראל\u0005]\u0006 \u0003אקיף אסולמא דצור, ועול לגביה\u0004 \u0005[הקף\u0006 בדרכך \u0005ולך\u0006 דרך \u0005סולמה של צור, והכנס אצל]\u0006 \u0003ר' יעקב בר אידי\u0004 \u0003ובעי מיניה אי שמיעא ליה\u0004 \u0005[ושאל אותו אם שמע]\u0006 מ\u0003ר' יוחנן\u0004 אם \u0003הלכה כ\u0004שיטת \u0003ר' עקיבא או אין הלכה כ\u0004שיטת \u0003ר' עקיבא?\u0004 הלך לשם ושאל, \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003הכי\u0004 \u0005[כך]\u0006 \u0003אמר ר' יוחנן: הלכה כ\u0004שיטת \u0003ר' עקיבא לעולם.\u0004","ושואלים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003לעולם? אמר רב אשי: שלא תאמר הני מילי\u0004 \u0005[דברים אלה]\u0006 שאמר ר' עקיבא הם דווקא \u0003היכא דליכא\u0004 \u0005[במקום שאין]\u0006 \u0003עדים,\u0004 \u0003אבל היכא דאיכא\u0004 \u0005[במקום שיש]\u0006 \u0003עדים לא.\u0004","\u0003ואי נמי דאהדרה לדוכתה ואיתברא\u0004 \u0005[או גם כן כשהחזיר את החבית למקומה ונשברה]\u0006 \u0003לאפוקי\u0004 \u0005[להוציא]\u0006 \u0003מ\u0004דברי \u0003ר' ישמעאל\u0004 שאמר שאם גנב אדם מחבירו והחזיר \u0003לא בעינן\u0004 \u0005[אין אנו צריכים]\u0006 \u0003דעת בעלים\u0004 להודיעם שהחזיר, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 \u0003דבעינן\u0004 \u0005[שצריכים אנו]\u0006 \u0003דעת בעלים\u0004 לדעת ר' עקיבא. \u0003ורבא אמר:\u0004 לא כר' יוחנן, אלא \u0003הלכה כבית הלל.\u0004","\u0003החושב\u0004 (כלומר, אמר בקול שרצונו) \u0003לשלוח יד בפקדון,\u0004 ונודע הדבר לעדים, \u0003בית שמאי אומרים: חייב\u0004 מאז על כל מה שקורה לפקדון, \u0003ובית הלל אומרים: אינו חייב עד שישלח בו יד\u0004 בפועל, \u0003שנאמר: \"אם לא שלח ידו במלאכת רעהו\"\u0004 (שמות כב, ז). \u0003הטה את החבית\u0004 של הפקדון \u0003ונטל הימנה\u0004 (ממנה) \u0003רביעית\u0004 של יין לעצמו \u0003ונשברה\u0004 החבית — \u0003אינו משלם אלא\u0004 דמי \u0003רביעית,\u0004 כי לא גזל אלא רביעית אחת. אם \u0003הגביהה ונטל הימנה רביעית ונשברה\u0004 כיון שקנה אותה בהגבהה — \u0003משלם דמי כולה.\u0004"],["\u0003מנהני מילי\u0004 \u0005[מנין הדברים]\u0006 שאדם מתחייב על שליחות יד במחשבה? — \u0003דתנו רבנן\u0004 \u0005[ששנו חכמים]:\u0006 בדיני שליחות יד נאמר \u0003\"על כל דבר פשע\"\u0004 (שמות כב, ח), \u0003בית שמאי אומרים:\u0004 כתוב זה \u0003מלמד שחייב על המחשבה\u0004 (דיבור) \u0003כמעשה,\u0004 שדי רק ב\"דבר פשע\". ו\u0003בית הלל אומרים: אינו חייב עד שישלח בו יד\u0004 ממש, \u0003שנאמר: \"אם לא שלח ידו במלאכת רעהו\"\u0004 (שם ז). \u0003אמרו להן בית שמאי לבית הלל: והלא כבר נאמר \"על כל דבר פשע\"! אמרו להן בית הלל לבית שמאי:\u0004 ו\u0003הלא כבר נאמר \"אם לא שלח ידו במלאכת רעהו\"!\u0004 \u0003אם כן, מה תלמוד לומר \"על כל דבר פשע\"?\u0004 דבר זה בא ללמדנו: \u0003שיכול אין לי\u0004 חייב בשליחות יד \u0003אלא הוא\u0004 עצמו שעשה, ואולם אם \u0003אמר לעבדו\u0004 או \u0003לשלוחו\u0004 שישלחו יד בפקדון שבידו \u0003מנין\u0004 שחייב על מעשיהם? \u0003תלמוד לומר: \"על כל דבר פשע\"\u0004 שמתחייב בזה גם של דיבורו.","","שנינו במשנה: \u0003הטה את החבית\u0004 אינו חייב אלא על מה שהשתמש בו. \u0003אמר רבה: לא שנו אלא\u0004 אם \u0003נשברה\u0004 החבית, \u0003אבל\u0004 אם \u0003החמיצה\u0004 החבית — \u0003משלם את כולה.\u0004 ומסבירים: \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר — \u0003גירי דידיה הוא דאהנו לה\u0004 \u0005[החצים שלו הם גרמו לה]\u0006 להחמיץ, כלומר, מעשיו הם שגרמו ליין שבתוכה שיחמיץ, שאף שנטל רק רביעית, מכל מקום טלטול החבית ופתיחתה הם שגרמו להחמצה.","שנינו במשנה שאם \u0003הגביהה\u0004 את החבית \u0003ונטל הימנה\u0004 אפילו רביעית חייב על כולה. \u0003אמר שמואל: לא\u0004 תפרש \u0003נטל ממש\u0004 מן החבית, \u0003אלא כיון שהגביהה\u0004 כדי \u0003ליטול\u0004 ממנה, \u0003אף על פי שלא נטל\u0004 ממנה עדיין — מתחייב.","ושואלים: \u0003לימא קא סבר\u0004 \u0005[האם נאמר כי סבור]\u0006 \u0003שמואל\u0004 ש\u0003שליחות יד אינה צריכה חסרון? אמרי\u0004 \u0005[אומרים]:\u0006 \u0003לא,\u0004 אין להוכיח מכאן, ואפשר לומר כי \u0003שאני הכא דניחא ליה דתיהוי הא חבית כולה בסיס להא\u0004 \u0005[שונה כאן שנוח לו שתהא חבית זו כולה בסיס לאותה]\u0006 \u0003רביעית,\u0004 שאף שהתכוון להוציא רק כמות קטנה, אבל כיון שאף רביעית אינו רוצה שתהיה לבדה אלא בתוך חבית יין מלאה, נמצא שמעונין בחבית כולה — ומשום כך נחשב כאילו נטל את כל החבית.","\u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רב אשי:\u0004 לפי שיטה זו, \u0003הגביה ארנקי\u0004 \u0005[ארנק]\u0006 \u0003ליטול הימנה דינר\u0004 אחד בלבד \u0003מהו\u0004 הדין בכגון זה? הרי נאמר: \u0003חמרא\u0004 \u0005[יין]\u0006 \u0003הוא דלא מינטר\u0004 \u0005[שאינו נשמר]\u0006 \u0003אלא אגב חמרא\u0004 \u0005[יין]\u0006 ומשום כך אומרים שהיה מעונין בחבית כולה, \u0003אבל זוזא מינטר\u0004 \u0005[אבל דינר נשמר\u0006 בפני עצמו\u0005].\u0006 \u0003או דלמא שאני נטירותא דארנקי מנטירותא\u0004 \u0005[שמא שונה שמירתו של ארנק\u0006 שלם \u0005משמירה]\u0006 של \u0003דינר\u0004 שהארנק נשמר יותר מדינר בודד, ולכך מעונין בארנק כולו. לשאלה זו לא נמצאה תשובה, ועל כן \u0003תיקו\u0004 \u0005[תעמוד]\u0006 במקומה.","","כאשר קונה אדם דבר בכסף — כלל הוא שתשלום הכסף איננו גומר שום מעשה קנין ורק משיכת החפץ שנקנה, היא הגומרת את הקנין, ותשלום הכספים יוצר רק התחייבות מוסרית. ואולם כאשר קונה אדם או מחליף מטבעות כסף במטבעות זהב, הרי \u0003הזהב קונה את הכסף,\u0004 שמטבעות הזהב נחשבות אז כחפץ (\"פרי\") ואילו הכסף הוא כמטבע, ומשום כך משיכת הזהב קונה את מטבעות הכסף, אולם \u0003הכסף אינו קונה את הזהב\u0004 שהוא ככל תשלום כספים שאינו גומר את הקנין.","וכיוצא בזה, \u0003הנחשת קונה את הכסף, והכסף אינו קונה את הנחשת,\u0004 \u0003מעות הרעות,\u0004 שהן כסף שנפחת, או שיש קשיים אחרים בשימושו, \u0003קונות את היפות,\u0004 משום שהן נחשבות חפץ לגבי המעות היפות הנחשבות לכסף, \u0003והיפות אינן קונות את הרעות.\u0004","\u0003אסימון\u0004 שהוא פיסת מתכת עגולה שאין עליה צורה טבועה \u0003קונה את המטבע, והמטבע אינו קונה את\u0004 ה\u0003אסימון.\u0004 ובכלל: \u0003מטלטלין קונין את המטבע,\u0004 ו\u0003מטבע אינו קונה את המטלטלין.\u0004","\u0003זה הכלל: כל המטלטלים קונין זה את זה,\u0004 שכאשר אין קנין כסף אלא חליפין, הרי אם משך צד אחד — ממילא נקנה גם האחר. ועתה מסבירים את הכללים הללו למעשה: \u0003כיצד? משך הימנו\u0004 (ממנו), מן המוכר, \u0003פירות\u0004 בתהליך הקנין \u0003ולא נתן לו\u0004 עדיין \u0003מעות\u0004 במחירם — \u0003אינו יכול לחזור בו.\u0004 ואולם אם \u0003נתן לו מעות ולא משך הימנו\u0004 את \u0003ה\u0004\u0003פירות\u0004 — \u0003יכול לחזור בו,\u0004 ולבטל את העיסקה ולומר שהקנין עדיין לא נגמר.","\u0003אבל אמרו\u0004 חכמים: \u0003מי שפרע מאנשי דור המבול ומדור הפלגה,\u0004 שאף שלא היה דיין בעולם הזה שיפרע מהם, נפרע מהם הקדוש ברוך הוא על חטאיהם — \u0003הוא עתיד להפרע ממי שאינו עומד בדבורו,\u0004 שאף שבית דין של מטה איננו יכול לכפות עליו דבר, יענש בידי שמים אם גרם נזק. \u0003ר' שמעון אומר: כל שהכסף בידו ידו על העליונה.\u0004 כלומר, מה שאמרנו שקנין בכסף אינו גומר את העיסקה, הוא רק לגבי המוכר שבידו נמצא הכסף שקיבל (וגם הפירות), שהוא יכול לבטל את העיסקה ולהחזיר את הכסף. אבל הקונה שנתן כסף — הוא אינו יכול לחזור בו, גם אם לא משך את הפירות.","","\u0003מתני ליה\u0004 \u0005[היה משנה,\u0006 מלמד, \u0005לו]\u0006 \u0003רבי\u0004 יהודה הנשיא \u0003לר' שמעון בריה\u0004 \u0005[בנו]:\u0006 \u0003הזהב קונה את הכסף\u0004 כפי שאנו שונים במשנתנו. \u0003אמר לו\u0004 בנו: \u0003רבי, שנית לנו בילדותיך\u0004 (בצעירותך) במהדורה הראשונה של המשנה: \u0003הכסף קונה את הזהב,\u0004 ועכשיו אתה חוזר בך \u0003ותשנה לנו בזקנותיך הזהב קונה את הכסף?\u0004","ושואלים: \u0003בילדותיה מאי סבר, ובזקנותיה מאי סבר\u0004 \u0005[בצעירותו מה חשב ובזיקנתו מה חשב],\u0006 מה היה הבסיס לדעתו קודם ואחר כך? ומשיבים: \u0003בילדותיה סבר\u0004 \u0005[בילדותו חשב]:\u0006 \u0003דהבא דחשיב הוי טבעא\u0004 \u0005[זהב ש\u0006הוא \u0005חשוב\u0006 יותר הריהו \u0005נחשב\u0006 לכסף, \u0005למטבע]\u0006 \u0003כספא דלא חשיב\u0004 \u0005[כסף שאינו חשוב\u0006 כל כך\u0005]\u0006 — \u0003הוי פירא\u0004 \u0005[הרי הוא כפירות],\u0006 ולפי הכלל: \u0003קני ליה פירא לטבעא\u0004 \u0005[קונה הפרי את המטבע].\u0006 ואילו \u0003בזקנותיה סבר\u0004 \u0005[בזקנתו סבר]:\u0006 \u0003כספא\u0004"],["\u0003דחריף\u0004 \u0005[שהוא חריף],\u0006 כלומר, מהיר בהוצאה, שמטבעות כסף עוברות לסוחר בכל מקום, ואילו מטבעות זהב שהן יקרות הרבה יותר לא תמיד יש מי שמוכן לקחת אותן, על כן \u0003הוי טבעא\u0004 \u0005[הוא\u0006 נחשב \u0005למטבע].\u0006 \u0003דהבא דלא חריף הוי פירא\u0004 \u0005[הזהב שאיננו חריף\u0006 בהוצאה \u0005הרי הוא כפירות]\u0006 ולפי הכלל: \u0003קני ליה פירא לטבעא\u0004 \u0005[קונה הפרי את המטבע].\u0006","\u0003אמר רב אשי: כילדותיה מסתברא\u0004 \u0005[כפי\u0006 ששנה \u0005בילדותו מסתבר]\u0006 לומר, \u0003מדקתני\u0004 \u0005[ממה ששנה]\u0006 בהמשך המשנה: \u0003\"הנחשת קונה את הכסף\",\u0004","\u0003אי אמרת בשלמא\u0004 \u0005[נניח אם אומר אתה]\u0006 כי \u0003כספא\u0004 \u0005[כסף]\u0006 \u0003לגבי דהבא\u0004 \u0005[הזהב]\u0006 \u0003פירא הוי\u0004 \u0005[פרי הוא]\u0006 \u0003היינו דקא תני\u0004 \u0005[הוא ששנה]\u0006 \u0003\"הנחשת קונה את הכסף\",\u0004 לומר: \u0003דאף על גב\u0004 \u0005[שאף על פי]\u0006 ש\u0003לגבי דהבא פירא הויא\u0004 \u0005[זהב פרי היא],\u0006 \u0003לגבי נחשת טבעא הוי\u0004 \u0005[מטבע היא].\u0006 \u0003אלא אי אמרת כספא\u0004 \u0005[אם אומר אתה\u0006 כי \u0005כסף]\u0006 \u0003לגבי דהבא טבעא הוי\u0004 \u0005[הזהב כמטבע הוא]\u0006 הרי מובן מאליו, כי \u0003השתא לגבי דהבא דחשיב מיניה, אמרת טבעא הוי\u0004 \u0005[עכשיו לגבי הזהב שחשוב ממנה, אומר אתה\u0006 כי \u0005מטבע הוא]\u0006 \u0003לגבי\u0004 ה\u0003נחשת דאיהו חשיב ואיהו\u0004 \u0005[שהוא,\u0006 הכסף, גם \u0005חשוב והוא]\u0006 גם \u0003חריף\u0004 בהוצאה \u0003מבעיא\u0004 \u0005[נצרכה\u0006 לומר\u0005]\u0006 שהכסף נחשב כמטבע לגבי נחושת?","ודוחים: מכאן אין הוכחה, כי \u0003איצטריך\u0004 \u0005[הוצרך]\u0006 לשנות גם קטע זה. שכן \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]\u0006 כי \u0003הני פריטי, באתרא דסגיי אינהו חריפי טפי מכספא\u0004 \u0005[אותן פרוטות\u0006 של נחושת \u0005במקום שהן מהלכות\u0006 ונקנות, \u0005הן חריפות\u0006 בהוצאה \u0005יותר מ\u0006אשר מטבע \u0005כסף]\u0006 על כן \u0003אימא טבעא הוי\u0004 \u0005[אמור\u0006 שנחשבות הן \u0005כמטבעות]\u0006 לגבי כסף, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 ש\u0003כיון דאיכא דוכתא דלא סגי ביה\u0004 \u0005[שיש\u0006 מקום שאינן הולכות, נוהגות \u0005בו]\u0006 — \u0003פירא הוי\u0004 \u0005[הרי הן כפרי],\u0006 כי כסף אפשר להחליף בכל מדינה, מה שאין כן מטבע של נחושת אינה עוברת לסוחר אלא באזור מסויים ומוגבל.","ומעירים: \u0003ואף ר' חייא סבר\u0004 \u0005[סבור]\u0006 כי \u0003דהבא טבעא הוי\u0004 \u0005[הזהב מטבע הוא]\u0006 לגבי כסף. ש\u0003רב אוזיף דינרי מברתיה\u0004 \u0005[לווה דינרים מבתו]\u0006 של \u0003ר' חייא,\u0004 \u0003לסוף אייקור דינרי\u0004 \u0005[לבסוף התייקרו הדינרים]\u0006 והיה מחירם של דינרי זהב גבוה יותר לפי ערך הכסף. \u0003אתא לקמיה\u0004 \u0005[בא\u0006 רב \u0005לפני]\u0006 \u0003ר' חייא\u0004 לשאול מה יעשה, שאם ישלם יותר שמא הוא עובר משום איסור ריבית. \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003זיל שלים\u0004 \u0005[לך ושלם]\u0006 \u0003לה\u0004 דינרים \u0003טבין ותקילין\u0004 \u0005[טובים ושקולים],\u0006 כלומר, חייב אתה להחזיר אותו מספר של דינרים ולא לפי ערכם בכסף. ומכאן, \u0003אי אמרת בשלמא דהבא טבעא הוי\u0004 \u0005[נניח אם אומר אתה\u0006 שהזהב \u0005מטבע הוא]\u0006 — \u0003שפיר\u0004 \u0005[יפה]\u0006 שלווה והחזיר אותן מטבעות. \u0003אלא אי אמרת פירא הוי\u0004 \u0005[אם אומר אתה\u0006 שהזהב \u0005כפירות הוא],\u0006 אם כן \u0003הוה ליה\u0004 \u0005[הרי זה]\u0006 כלווה \u0003סאה בסאה,\u0004 ש\u0003אסור\u0004 ללוות סאה ולהחזיר בדיוק סאה, שמא בינתיים עלה המחיר!","ודוחים: כאן לא היה מתחילה ענין של הלוואה ממש, כי \u0003רב דינרי הוו ליה\u0004 \u0005[דינרים היו לו]\u0006 במקום אחר, והוצרך לכסף רק לפי שעה \u0003וכיון דהוו ליה דינרי\u0004 \u0005[שהיו לו דינרים\u0006 אצלו\u0005]\u0006 \u0003נעשה כאומר לה: הלויני עד שיבא בני או עד שאמצא מפתח\u0004 שדבר זה איננו נקרא הלוואה, ואין בו דיני רבית.","\u0003אמר רבא: האי תנא סבר דהבא טבעא הוי\u0004 \u0005[תנא זה,\u0006 שנביא את דבריו \u0005סבור\u0006 אף הוא \u0005שהזהב מטבע הוא],\u0006 \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003פרוטה שאמרו\u0004 חכמים בכל מקום שיעורה \u0003אחד משמונה באיסר האיטלקי.\u0004 ושואלים: \u0003למאי נפקא מינה\u0004 \u0005[מה יוצא מזה]?\u0006 לכאורה פרוטה היא תמיד פרוטה. ומשיבים: \u0003לקדושי אשה\u0004 שהן בפרוטה, ופרוטה זו צריך להעריכה לפי ערך האיסר האיטלקי. עוד אמר: \u0003איסר\u0004 הוא \u0003אחד מעשרים וארבעה בדינר של כסף.\u0004 ושאלו: \u0003למאי נפקא מינה\u0004 \u0005[מה יוצא מזה]?\u0006 ומשיבים: \u0003למקח וממכר,\u0004 לדעת מה ערכו במסחר.","\u0003דינר של כסף\u0004 הוא \u0003אחד מעשרים וחמשה בדינר של זהב.\u0004 ו\u0003למאי נפקא מינה\u0004 \u0005[מה יוצא מזה]\u0006 לקבוע לו ערך — \u0003לפדיון הבן,\u0004 שנותנים חמישה סלעים (שהם עשרים דינר) לפדיון הבן, שמא נתן לכהן דינר זהב, מחזיר לו חמישה דינרי כסף.","ומעתה: \u0003אי אמרת בשלמא טבעא הוי\u0004 \u0005[נניח אם אומר אתה\u0006 שדינר הזהב \u0005מטבע הוא]\u0006 \u0003משער\u0004 ה\u0003תנא במידי דקיץ\u0004 \u0005[בדבר\u0006 שדמיו \u0005קבועים]\u0006 שמחיר הזהב הוא מחיר המטבע היסודי, והכסף לגביו אינו אלא כפרי, שערך הכסף עולה ויורד ואילו המטבע הקבוע הוא הזהב. \u0003אלא אי אמרת פירא הוי\u0004 \u0005[אם אומר אתה\u0006 שהזהב \u0005כפרי הוא]\u0006 וכי \u0003משער\u0004 ה\u0003תנא במידי דאוקיר וזיל\u0004 \u0005[בדבר שהוא מתייקר ונעשה זול]?\u0006 \u0003זימנין דמהדר ליה כהנא וזימנין דמוסיף ליה איהו לכהנא\u0004 \u0005[פעמים שצריך להחזיר לו הכהן\u0006 יותר \u0005ופעמים שמוסיף הוא לכהן].\u0006 אלא, \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 כי סבור אותו תנא: \u0003טבעא הוי\u0004 \u0005[מטבע הוא]\u0006 ומסכמים: אכן, \u0003שמע מינה\u0004 \u0005[למד מכאן].\u0006","\u0003תנן התם\u0004 \u0005[שנינו\u0006 במשנה \u0005שם]\u0006 לענין שקלים, ש\u0003בית שמאי אומרים: לא יעשה\u0004 (יחליף) \u0003אדם סלעין\u0004 של כספי מעשר, ושאר כספים השייכים לקודש ב\u0003דינרי זהב, ובית הלל מתירין. ר' יוחנן וריש לקיש\u0004 נחלקו בדבר, \u0003חד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 \u0003אמר\u0004 שה\u0003מחלוקת\u0004 היא בהחלפת \u0003סלעים על דינרין,\u0004 וטעם המחלוקת ש\u0003בית שמאי סברי\u0004 \u0005[סבורים]:\u0006 \u0003כספא טבעא\u0004 \u0005[הכסף\u0006 הוא \u0005מטבע]\u0006 \u0003ודהבא פירא\u0004 \u0005[זהב\u0006 הוא \u0005כפרי]\u0006 \u0003וטבעא אפירא לא מחללינן\u0004 \u0005[ומטבע על פרי אין מחללין],\u0006 אלא להיפך. \u0003ו\u0004אילו \u0003בית הלל סברי\u0004 \u0005[סבורים]:\u0006 \u0003כספא פירא ודהבא טבעא\u0004 \u0005[הכסף\u0006 הוא \u0005כפירות והזהב\u0006 הוא \u0005כמטבע]\u0006 \u0003ופירא אטבעא מחללינן\u0004 \u0005[ופרי על מטבע מחללים],\u0006 \u0003אבל פירות על דינרין\u0004 של זהב — ל\u0003דברי הכל מחללינן\u0004 \u0005[מחללים אנו].\u0006","\u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 ההבדל — \u0003מידי דהוה\u0004 \u0005[כפי שהוא\u0006 הדין\u0005]\u0006 לגבי \u0003כסף ל\u0004שיטת \u0003בית הלל.\u0004 הלא \u0003כסף לבית הלל, אף על גב דכספא לגבי דהבא פירא הוי\u0004 \u0005[אף על פי שהכסף לגבי הזהב כפרי הוא]\u0006 מכל מקום \u0003לגבי פירא טבעא הוי\u0004 \u0005[פירות מטבע הוא].\u0006 \u0003זהב נמי\u0004 \u0005[גם כן]\u0006 \u0003ל\u0004שיטת \u0003בית שמאי, אף על גב דדהבא\u0004 \u0005[אף על פי שהזהב]\u0006 \u0003לגבי כספא פירא הוי\u0004 \u0005[הכסף פרי הוא],\u0006 \u0003לגבי פירא טבעא הוי\u0004 \u0005[פירות מטבע הוא]\u0006 ולכן מותר לחלל עליו. \u0003וחד\u0004 \u0005[ואחד\u0006 מהם\u0005]\u0006 \u0003אמר: אף בפירות על דינרין מחלוקת,\u0004 שהם חולקים אם הזהב נחשב כמטבע או כפרי (או חפץ אחר).","ושואלים: \u0003ולמאן דאמר\u0004 \u0005[ו\u0006לדעת \u0005מי שאומר]\u0006 כי \u0003אף בפירות על דינרין מחלוקת, אדמיפלגי\u0004 \u0005[עד שהם נחלקים]\u0006 \u0003בסלעין על דינרין, לפלוג\u0004 \u0005[שיחלקו]\u0006 בבעיה היסודית, \u0003בפירות על דינרין!\u0004 ודוחים: \u0003אי איפלוג\u0004 \u0005[אילו היו חולקים]\u0006 \u0003בפירות על דינרין, הוה אמינא\u0004 \u0005[הייתי אומר]:\u0006 \u0003הני מילי\u0004 \u0005[דברים אלה]\u0006 אמורים דווקא \u0003בפירות על דינרין, אבל בסלעין על דינרין\u0004 — \u0003מודו\u0004 \u0005[מודים]\u0006 \u0003להן בית הלל לבית שמאי דדהבא\u0004 \u0005[שהזהב]\u0006 \u0003לגבי כספא פירא הוי\u0004 \u0005[כסף פרי הוא]\u0006 \u0003ולא מחללינן\u0004 \u0005[ואין מחללין],\u0006 על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שאף בכך נחלקו.","ומעירים, \u0003תסתיים\u0004 \u0005[תוגדר]\u0006 מחלוקת זו שלא ידענו מה הן דעות החולקים, ש\u0003ר' יוחנן הוא\u0004 ש\u0003אמר\u0004 ש\u0003אין מחללין\u0004 פירות על דינרי זהב, ש\u0003אמר ר' יוחנן\u0004"],["\u0003אסור ללוות דנר בדינר,\u0004 שמא יתייקרו ונמצא משלם ריבית.","ומעתה נברר: \u0003דינר דמאי\u0004 \u0005[של מה]?\u0006 \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003דינר של כסף בדינר של כסף, לגבי,\u0004 בפני \u0003נפשיה\u0004 \u0005[עצמו]\u0006 \u0003מי איכא למאן\u0004 ש\u0003אמר לאו טבעא הוי\u0004 \u0005[האם יש מי שאומר שאיננו מטבע]?\u0006 \u0003אלא פשיטא\u0004 \u0005[פשוט]\u0006 שאמר שאין ללוות \u0003דינר של זהב בדינר של זהב,\u0004 ומעתה נברר: \u0003ולמאן\u0004 \u0005[ול\u0006שיטת \u0005מי]?\u0006 \u0003אי\u0004 \u0005[אם]\u0006 לפי שיטת \u0003בית הלל\u0004 — \u0003הא אמרי טבעא הוי\u0004 \u0005[הרי אומרים\u0006 הם \u0005מטבע הוא],\u0006 \u0003אלא לאו\u0004 \u0005[האם לא]\u0006 — \u0003ל\u0004דעת \u0003בית שמאי, ושמע מינה\u0004 \u0005[ולמד מכאן]\u0006 כי \u0003ר' יוחנן הוא\u0004 ש\u0003אמר, אין מחללינן\u0004 \u0005[אין מחללין]\u0006 על דינרי זהב, שלדעתו אינם נחשבים כמטבע גמורה.","ודוחים: \u0003לא, לעולם אימא\u0004 \u0005[אומר]\u0006 \u0003לך\u0004 כי \u0003ר' יוחנן הוא\u0004 ש\u0003אמר מחללינן\u0004 \u0005[מחללים אנו]\u0006 על דינרי זהב, \u0003ושאני\u0004 \u0005[ושונה]\u0006 דין \u0003הלואה\u0004 \u0003כיון\u0004 ש\u0003לענין מקח וממכר שויוהו רבנן כי פירא\u0004 \u0005[עשו אותו,\u0006 את דינר הזהב, \u0005חכמים כמו פרי],\u0006 \u0003דאמרינן\u0004 \u0005[שאנו אומרים]:\u0006 \u0003איהו ניהו דאוקיר וזיל\u0004 \u0005[הוא הוא שהתייקר והוזל]\u0006 וכפי שאמרנו הזהב קונה את הכסף, ו\u0003לגבי\u0004 דיני \u0003הלואה\u0004 בריבית \u0003נמי פירא הוי\u0004 \u0005[גם כן כפרי הוא]\u0006 ויש בו חשש ריבית.","ומעירים: \u0003הכי נמי מסתברא\u0004 \u0005[כך גם כן מסתבר]\u0006 לומר שזו דעתו של ר' יוחנן, \u0003דכי אתא\u0004 \u0005[שכאשר\u0006 \u0003בא]\u0004 \u0003רבין\u0004 מארץ ישראל לבבל \u0003אמר\u0004 בשם \u0003ר' יוחנן: אף על פי שאמרו אסור ללוות דינר בדינר, אבל מחללין מעשר שני עליו,\u0004 ואם כן \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 במפורש שר' יוחנן הוא שאמר שמחללים.","ומעתה שבים לעצם הבעיה בדבר חילול מעשר של זהב \u0003תא שמע\u0004 \u0005[בא\u0006 ו\u0005שמע]\u0006 פתרון לבעיה ממה ששנינו במשנה: \u0003הפורט סלע ממעות מעשר שני\u0004 שרוצה לצרף כספים קטנים למטבעות גדולים יותר, \u0003בית שמאי אומרים: בכל הסלע\u0004 מחליף ל\u0003מעות\u0004 כסף, \u0003ובית הלל אומרים: בשקל\u0004 (חצי סלע) \u0003כסף, בשקל\u0004 פורט ל\u0003מעות\u0004 קטנות יותר. ומעתה, \u0003השתא\u0004 \u0005[עכשיו]\u0006 \u0003ל\u0004דעת \u0003בית שמאי\u0004 אפילו \u0003לגבי פריטי\u0004 \u0005[פרוטות]\u0006 של נחושת אמרו הם כי \u0003מחללינן\u0004 \u0005[מחללים אנו]\u0006 עליהם את פירות המעשר, \u0003לגבי דהבא מיבעיא\u0004 \u0005[לגבי זהב נצרכה לומר]\u0006 שמחללין? ודוחים: \u0003שאני פריטי, באתרא דסגיין חריפי\u0004 \u0005[שונות הפרוטות, שבמקום שהן מהלכות הן חריפות,\u0006 עוברות לסוחר\u0005]\u0006 יותר ממטבע כסף\u0005].\u0006","\u0003לישנא אחרינא\u0004 \u0005[לשון אחרת]\u0006 \u0003אמרי לה\u0004 \u0005[אומרים אותה],\u0006 את מחלוקת \u0003ר' יוחנן וריש לקיש,\u0004 בצורה שונה. \u0003חד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 \u0003אמר\u0004 שה\u0003מחלוקת\u0004 היא \u0003בסלעין על דינרים,\u0004 ש\u0003בית שמאי סברי\u0004 \u0005[סבורים]\u0006 שמה שנאמר בכתוב \u0003\"\u0004וצרת \u0003הכסף\"\u0004 (דברים יד, כה) כוונתו \u0003כסף ראשון ולא כסף שני,\u0004 כלומר, אותו כסף עצמו שנתקבל עבור חילול פירות המעשר הוא הכסף שצריך להביא לירושלים, ואין להחליף כסף זה באחר.","\u0003ובית הלל סברי\u0004 \u0005[סבורים]\u0006 כיון שנאמר \u0003\"הכסף\",\u0004 וגם \u0003\"כסף\", ריבה\u0004 הכתוב, בחזרה זו, ללמד שמותר להביא לירושלים \u0003אפילו כסף שני. אבל פירות על דינרין\u0004 — \u0003דברי הכל מחללינן\u0004 \u0005[מחללים אנו],\u0006 \u0003דאכתי\u0004 \u0005[שעדיין]\u0006 \u0003כסף ראשון הוא,\u0004 ומותר לחלל את הפירות בכל סוג כסף.","\u0003וחד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 \u0003אמר\u0004 כי \u0003אף בפירות על דינרין נמי\u0004 \u0005[גם כן]\u0006 \u0003מחלוקת\u0004 היא אם מותר בכסף דווקא או גם בזהב.","ושואלים: \u0003ולמאן דאמר\u0004 \u0005[\u0006\u0005ול\u0006שיטת \u0005מי שאומר]\u0006 שב\u0003סלעין על דינרין מחלוקת, אדמיפלגי\u0004 \u0005[עד שהם חלוקים]\u0006 \u0003בסלעין על דינרין, לפלגי\u0004 \u0005[שיחלקו]\u0006 במקרה יסודי יותר וברור יותר ב\u0003סלעין על סלעין,\u0004 שהרי לשיטת האוסרים גם דבר זה אסור!","ומשיבים: \u0003אי אפלגי\u0004 \u0005[אם\u0006 היו \u0005חלוקים]\u0006 \u0003בסלעין על סלעין, הוה אמינא\u0004 \u0005[הייתי אומר]:\u0006 \u0003הני מילי\u0004 \u0005[דברים אלה\u0006 אמורים\u0005]\u0006 דווקא שמחלל \u0003סלעין על סלעין, אבל בסלעין על דינרין\u0004 — \u0003מודו להו\u0004 \u0005[מודים להם]\u0006 \u0003בית הלל לבית שמאי, דדהבא\u0004 \u0005[שזהב]\u0006 \u0003לגבי כספא\u0004 \u0005[כסף]\u0006 \u0003פירא הוי ולא מחללינן\u0004 \u0005[\u0006כ\u0005פרי הוא ואין אנו מחללים],\u0006 על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שלא כן הוא, ואין הבדל.","ומביאים עוד ראיה, \u0003תא שמע\u0004 \u0005[בא\u0006 ו\u0005שמע]\u0006 ממה ששנינו במשנה: \u0003הפורט סלע של מעשר שני בירושלים\u0004 עצמה, \u0003בית שמאי אומרים:\u0004 יפרוט ויטול \u0003בכל הסלע מעות, ובית הלל אומרים: בשקל\u0004 לוקח \u0003כסף\u0004 ו\u0003בשקל\u0004 לוקח \u0003מעות.\u0004 ומעתה, \u0003השתא כספא לגבי פריטי מחללינן\u0004 \u0005[עכשיו\u0006 הרי, \u0005כסף על פרוטות מחללים אנו],\u0006 \u0003ולא אמרינן\u0004 \u0005[ואין אנו אומרים]\u0006 שגזירת הכתוב היא שיהא זה \u0003כסף ראשון ולא כסף שני, לגבי דהבא דחשיב מיניה\u0004 \u0005[זהב שחשוב ממנו,\u0006 מן הכסף\u0005],\u0006 \u0003מי אמרינן\u0004 \u0005[האם אומרים אנו],\u0006 האם יכולים לומר אז שדווקא \u0003כסף ראשון ולא כסף שני?\u0004","\u0003אמר רבא:\u0004 מ\u0003ירושלים קמותבת\u0004 \u0005[אתה מקשה]?!\u0006 \u0003שאני\u0004 \u0005[שונה]\u0006 הדין ב\u0003ירושלים, דכתיב ביה\u0004 \u0005[שנאמר בו]\u0006 \u0003\"ונתתה הכסף בכל אשר תאוה נפשך בבקר ובצאן\"\u0004 (שם כו) שכן בירושלים יכול לעשות בכסף ככל שירצה.","ומציעים עוד: \u0003תא שמע\u0004 \u0005[בא\u0006 ו\u0005שמע]\u0006 ראיה ממה ששנינו במשנה נוספת: \u0003הפורט סלע ממעות מעשר שני,\u0004 כלומר, מכסף שנתקבל מחילול פירות המעשר — \u0003בית שמאי אומרים:\u0004 יפרוט ויטול \u0003בכל הסלע מעות, ובית הלל אומרים: בשקל\u0004 יטול \u0003כסף\u0004 ו\u0003בשקל\u0004 יטול \u0003מעות.\u0004 והרי זו הוכחה נצחת שהכל מסכימים שמותר להחליף כסף מעשר בכסף אחר!","\u0003אלא\u0004 יש לחזור ממה שהסברנו ולומר \u0003דכולי עלמא\u0004 \u0005[לדעת הכל]\u0006 במה שנאמר \u0003\"הכסף\" כסף ריבה\u0004 בתורה, ואפילו כסף שני. אלא \u0003אי איתמר\u0004 \u0005[אם נאמר]\u0006 שחלקו \u0003ר' יוחנן ור' שמעון בן לקיש הכי איתמר\u0004 \u0005[כך נאמר]:\u0006 \u0003חד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 \u0003אמר:\u0004 \u0003מחלוקת בסלעין\u0004 שמחליפים \u0003על דינרין,\u0004 ש\u0003בית שמאי סברי\u0004 \u0005[סבורים]:\u0006 \u0003גזרינן\u0004 \u0005[גוזרים אנו]\u0006 לאסור,"],["\u0003שמא ישהה עליותיו\u0004 לירושלים בשל החלפה זו, \u0003דזימנין דלא מלו זוזי בדינרא\u0004 \u0005[שפעמים שאין מתמלאים זוזים בדינר\u0006 הזהב\u0005]\u0006 \u0003ולא מסיק\u0004 \u0005[יעלה]\u0006 עד שיהא לו כדי דינר זהב שלם. \u0003ובית הלל סברי\u0004 \u0005[סבורים]:\u0006 \u0003לא גזרינן\u0004 \u0005[אין אנו גוזרים]\u0006 \u0003שמא ישהה עליותיו, דכי\u0004 \u0005[ש\u0006גם \u0005אם]\u0006 \u0003לא מלו נמי בדינרא אסוקי מסיק להו\u0004 \u0005[יתמלאו כדי דינר מעלה אותם]\u0006 במטבעות של כסף. \u0003אבל בפירות על דינרין\u0004 — \u0003דברי הכל מחללינן\u0004 \u0005[מחללים אנו],\u0006 ש\u0003כיון דמרקבי\u0004 \u0005[ש\u0006הם, הפירות \u0005נרקבים]\u0006 ודאי \u0003לא משהי להו\u0004 \u0005[ישהה אותם]\u0006 עד שיתמלא כדי דינר שלם.","ואילו \u0003חד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 \u0003אמר:\u0004 \u0003אפילו בפירות על דינרין נמי\u0004 \u0005[גם כן]\u0006 \u0003מחלוקת\u0004 מאותו חשש.","ושואלים: \u0003בשלמא להך לישנא דאמרת דמדאורייתא משרא שרי\u0004 \u0005[נניח לאותה לשון,\u0006 גרסה, \u0005שאמרת שמן התורה מותר\u0006 הדבר\u0005]\u0006 \u0003ורבנן הוא דגזרו ביה\u0004 \u0005[וחכמים\u0006 בלבד \u0005הם שגזרו בו]\u0006 — \u0003היינו דקתני\u0004 \u0005[זה ששנה]\u0006 בסגנון \u0003\"יעשה\" ו\"לא יעשה\",\u0004 שהוא לשון הצעה, ולכתחילה. \u0003אלא להך לישנא דאמרת דמדאורייתא פליגי\u0004 \u0005[לאותה לשון שאמרת שמן התורה חלוקים\u0006 הם\u0005]\u0006 אם הדבר מותר ואפשר, אם כן בלשון \u0003מחללינן ולא מחללינן מבעי ליה\u0004 \u0005[מחללים ואין מחללים היה צריך לו\u0006 לומר\u0005],\u0006 שהרי אם הדבר אסור מן התורה, לא נתחללו הכספים. ומעירים, אכן לשיטה זו \u0003קשיא\u0004 \u0005[קשה]\u0006 הדבר.","\u0003איתמר\u0004 \u0005[נאמר]\u0006 שנחלקו \u0003רב ולוי\u0004 בבעיה הבאה: \u0003חד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 \u0003אמר:\u0004 \u0003מטבע נעשה חליפין.\u0004 כלומר, קנין חליפין אפשר לעשותו גם כאשר אחד הצדדים מחליף מטבעות. \u0003וחד\u0004 \u0005[ואחד\u0006 מהם\u0005]\u0006 \u0003אמר:\u0004 \u0003אין מטבע נעשה חליפין,\u0004 לפי שאין קנין חליפין אלא בחפצים ככלים ופירות. \u0003אמר רב פפא: מאי טעמא דמאן דאמר\u0004 \u0005[מה הטעם של מי שאומר]\u0006 \u0003אין מטבע נעשה חליפין\u0004 — \u0003משום דדעתיה אצורתא\u0004 \u0005[שדעתו\u0006 של הקונה מטבע \u0005על הצורה]\u0006 על המטבע הטבועה דווקא, ולא על ערך המתכת היקרה שבו, \u0003וצורתא עבידא דבטלא\u0004 \u0005[והצורה עשויה שתתבטל]\u0006 על ידי המלכות. וכיון שכך, נמצא שאין המטבע עצמו דבר שיש בו ערך של ממש, ולכן אינו נקנה בחליפין כשאר פירות.","\u0003תנן\u0004 \u0005[שנינו\u0006 במשנתנו\u0005]:\u0006 \u0003הזהב קונה את הכסף, מאי לאו\u0004 \u0005[האם לא]\u0006 הכוונה שקונה \u0003בחליפין, ושמע מינה\u0004 \u0005[ולמד מכאן]\u0006 כי \u0003מטבע נעשה חליפין?\u0004 ודוחים: \u0003לא,\u0004 הכוונה היא \u0003בדמים.\u0004 כלומר, קנין זה הוא כשאר קניינים, בכסף. ומקשים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 אין הלשון מדוייק כי לא היה צריך לומר \u0003הזהב קונה את הכסף\u0004 אלא \u0003מחייב מבעי ליה\u0004 \u0005[צריך היה\u0006 לו\u0005]\u0006 לומר, שהרי הוא המחייב במשיכתו את הקונה לשלם תמורתו כסף! ומשיבים: \u0003תני\u0004 \u0005[שנה]\u0006 ותקן: \u0003הזהב מחייב\u0004 את הכסף.","ומעירים: \u0003הכי נמי מסתברא\u0004 \u0005[כך גם כן מסתבר],\u0006 שיש להבין את המשנה במשמעות זו \u0003מדקתני סיפא\u0004 \u0005[ממה ששנה בסופה]\u0006 של המשנה: \u0003הכסף אינו קונה את הזהב. אי אמרת בשלמא\u0004 \u0005[נניח אם אומר אתה]\u0006 שמדובר כאן על קנין \u0003דמים,\u0004 כלומר, בכסף — \u0003היינו דאמרינן\u0004 \u0005[זהו שאנו אומרים]\u0006 \u0003דהבא פירא, וכספא טבעא, וטבעא פירא לא קני\u0004 \u0005[זהב\u0006 כ\u0005פרי\u0006 הוא, \u0005וכסף מטבע, ומטבע אינו קונה פרי].\u0006 \u0003אלא אי אמרת\u0004 \u0005[אם אומר אתה]\u0006 שמדובר \u0003ב\u0004קנין \u0003חליפין,\u0004 אם כן \u0003תרוייהו לקנו אהדדי\u0004 \u0005[ששניהם יקנו זה את זה],\u0006 שהרי בקנין חליפין שני הדברים נקנים כאחת.","\u0003ועוד, תניא\u0004 \u0005[שנוייה\u0006 ברייתא\u0005]:\u0006 \u0003הכסף אינו קונה את הזהב, כיצד?\u0004 — \u0003מכר לו עשרים וחמשה דינר של כסף בדינר של זהב, אף על פי שמשך את הכסף לא קנה עד שימשוך את הזהב. אי אמרת בשלמא\u0004 \u0005[נניח אם אומר אתה]\u0006 שמדובר כאן בקנין \u0003דמים\u0004 — \u0003משום הכי לא קני\u0004 \u0005[משום כך אינו קונה],\u0006 שאין הקנין חל אלא כאשר מושך את גוף החפץ הנקנה. \u0003אלא אי אמרת\u0004 \u0005[אם אתה אומר]\u0006 שמדובר \u0003ב\u0004קנין \u0003חליפין\u0004 — \u0003נקני\u0004 \u0005[שיקנה],\u0006 שהרי כשקונה חפץ אחד נקנה גם חבירו בחליפין.","ומקשים לצד שני: \u0003אלא מאי\u0004 \u0005[מה]\u0006 מפרש אתה שמדובר כאן בקנין \u0003דמים? אי הכי אימא רישא\u0004 \u0005[אם כך אמור את תחילתה\u0006 של הברייתא\u0005]:\u0006 \u0003הזהב קונה את הכסף, כיצד?\u0004 — \u0003מכר לו דינר של זהב בעשרים וחמשה דינר של כסף, כיון שמשך את הזהב נקנה כסף בכל מקום שהוא.\u0004","\u0003אי אמרת בשלמא\u0004 \u0005[נניח אם אומר אתה]\u0006 שמדובר \u0003ב\u0004קנין \u0003חליפין היינו דקתני\u0004 \u0005[זהו ששנינו]\u0006 \u0003\"נקנה כסף בכל מקום שהוא\",\u0004 שבחליפין חל הקנין על אותן מטבעות כסף בכל מקום שהן. \u0003אלא אי אמרת\u0004 \u0005[אם אומר אתה]\u0006 שמדובר \u0003ב\u0004קנין \u0003דמים\u0004 \u0003האי\u0004 \u0005[זה]\u0006 הלשון \u0003\"נקנה כסף בכל מקום שהוא\"\u0004 אינה נכונה, אלא \u0003נתחייב גברא מיבעי ליה\u0004 \u0005[נתחייב האיש היה צריך לו\u0006 לומר\u0005]\u0006 שהרי בגמר המקח חייב הקונה לשלם, אבל אינו צריך לתת דווקא מטבעות מסויימים אלה, אלא את סכום הקנין.","\u0003אמר רב אשי: לעולם\u0004 תפרש שמדובר כאן בקנין \u0003דמים. ומאי\u0004 \u0005[ומה]\u0006 פירוש \u0003\"בכל מקום שהוא\"?\u0004 הכוונה היא: \u0003כמות שהוא, כדאמר ליה\u0004 \u0005[כפי שאמר לו]\u0006 בעל הכסף, שאינו יכול לשנות בטיבו של הכסף. כיצד, \u0003אי\u0004 \u0005[אם]\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003מארנקי חדשה יהבינא\u0004 \u0005[מארנק חדש אני נותן]\u0006 \u0003לך,\u0004 כלומר, מטבעות חדשים, \u0003לא מצי יהיב ליה מארנקי ישנה\u0004 \u0005[אינו יכול לתת לו מארנק ישן],\u0006 כלומר, מטבעות ישנים \u0003אף על גב דעדיפי מינייהו\u0004 \u0005[אף על פי\u0006 שכרגיל נחשבים הם \u0005כעדיפים מהם]\u0006 משום שאנשים מתייחסים באמון לכסף שכבר השתמשו בו. ו\u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של הקונה, \u0003דאמר ליה\u0004 \u0005[שאומר לו]\u0006 בעל הזהב: \u0003לישנן קא בעינא להו\u0004 \u0005[אני רוצה אותן],\u0006 שרצוני להחזיק אצלי את המטבעות זמן רב ובינתיים יתיישנו, ואינני רוצה לקחת מטבעות ישנות שלא ישחירו ביותר.","\u0003אמר רב פפא: אפילו למאן\u0004 ש\u0003אמר\u0004 \u0005[\u0006לדעת \u0005מי שאומר]\u0006 \u0003אין מטבע נעשה חליפין\u0004 — \u0003מיעבד\u0004 \u0005[לעשות]\u0006 \u0003הוא דלא עביד\u0004 \u0005[שאינו\u0006 \u0003עושה]\u0004 \u0003חליפין,\u0004 ואולם \u0003אקנויי מיקנו\u0004 נקנה הוא על ידי \u0003חליפין,\u0004 שאם מחליף כלי של ממש בכסף — נקנה הכסף בחליפין, \u0003מידי דהוה אפירא\u0004 \u0005[כמו שהוא\u0006 הדין בענין \u0005פירות]\u0006 \u0003ל\u0004שיטת \u0003רב נחמן\u0004 כי \u0003פירא\u0004 \u0005[פירות]\u0006 \u0003ל\u0004שיטת \u0003רב נחמן, לאו אף על גב דאינהו לא עבדי\u0004 \u0005[האם לא אף על פי שהם עצמם אינם עושים]\u0006 \u0003חליפין,\u0004 \u0003אקנויי מקנו\u0004 \u0005[נקנים הם]\u0006 \u0003בחליפין,\u0004 \u0003טבעא נמי לא שנא\u0004 \u0005[מטבע גם כן אינה שונה].\u0006","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על דעת רב פפא ממה ששנינו: \u0003היה עומד בגורן ואין בידו מעות\u0004 ורוצה לחלל את פירות מעשר שני בלא שיתחייב להוסיף חומש. שאדם המחלל את פירותיו שלו חייב להוסיף חומש, ורוצה האיש להערים ולעשות כאילו מוכרם לחברו ואז יוכל למכרם בשויים בלא הוספה. \u0003אמר לחבירו: הרי פירות הללו נתונים לך במתנה,\u0004"],["\u0003וחוזר ואומר: הרי הן\u0004 הפירות הללו שהם עכשיו שלך \u0003מחוללין על מעות שיש לי בבית.\u0004 ונדייק: \u0003טעמא\u0004 \u0005[הטעם,\u0006 דווקא\u0005]\u0006 ש\u0003אין בידו מעות, הא\u0004 \u0005[הרי]\u0006 אם \u0003יש בידו מעות\u0004 — \u0003ליקני להו לאידך\u0004 \u0005[שיקנה אותם לאחר,\u0006 לחבירו את המעות הללו \u0003במשיכה\u0004 \u0003ופריק\u0004 \u0005[ויפדה]\u0006 \u0003דהכי\u0004 \u0005[שכך]\u0006 \u0003עדיף, דהוה ליה נכרי\u0004 \u0005[שהרי הוא זר]\u0006 ואינו צריך להוסיף חומש, וכך נראה הדבר פחות כהערמה על המעשר.","\u0003ואי אמרת\u0004 \u0005[ואם אומר אתה]\u0006 ש\u0003מטבע נקנה בחליפין\u0004 הרי יכול להעביר לו את הכספים בדרך זו: \u0003ניקנו ליה\u0004 \u0005[שיקנו לו]\u0006 את ה\u0003מעות להיאך\u0004 \u0005[לההוא,\u0006 לחבירו\u0005]\u0006 \u0003אגב סודר,\u0004 שהרי יכול לעשות קנין חליפין עם החבר על ידי סודר, ויקנו את המעות לחבר, \u0003ולפרוק\u0004 \u0005[ויפדה]!\u0006 ומשיבים: מדובר באופן \u0003דלית ליה\u0004 \u0005[שאין לו]\u0006 \u0003סודר.\u0004 ושואלים: \u0003ונקנינהו נהליה\u0004 \u0005[ושיקנה אותם,\u0006 את המעות \u0005לו]\u0006 \u0003אגב קרקע!\u0004 ומשיבים: \u0003דלית ליה\u0004 \u0005[שאין לו]\u0006 \u0003קרקע.\u0004","ומקשים: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003עומד בגורן קתני\u0004 \u0005[שנה]!\u0006 ודוחים: מדובר באופן שעומד \u0003בגורן שאינו שלו.\u0004 על סדרת תירוצים זו מקשים: \u0003ואיכפל\u0004 \u0005[וכי יתאמץ]\u0006 ה\u0003תנא לאשמועינן גברא ערטילאי דלית ליה\u0004 \u0005[להשמיענו\u0006 לשנות לנו מקרה \u0005באדם ערום שאין לו]\u0006 \u0003ולא כלום?\u0004 כלומר, אין זה מסתבר לפרש את הברייתא שתהא רק במקרה יוצא דופן כגון זה, ומן הסתם אין הסבר זה אמיתי. \u0003אלא לאו שמע מינה\u0004 \u0005[האם לא תלמד מכאן]\u0006 ש\u0003אין מטבע נקנה בחליפין.\u0004 ומסכמים: אכן, \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שכן הוא.","ומספרים: \u0003ואף רב פפא הדר ביה\u0004 \u0005[חזר בו]\u0006 מדעתו לגבי קנין מטבע בחליפין. \u0003כי הא\u0004 \u0005[כמו\u0006 מעשה \u0005זה]\u0006 ש\u0003רב פפא הוו ליה תריסר אלפי דינרי בי חוזאי\u0004 \u0005[היו לו שנים עשר אלף דינרים\u0006 בהלוואה \u0005בבית חוזאי],\u0006 \u0003אקנינהו\u0004 \u0005[הקנה אותם]\u0006 לשליחו \u0003רב שמואל בר אחא אגב אסיפא דביתיה\u0004 \u0005[סף הבית\u0006 שלו\u0005]\u0006 כדי שהשליח יוכל לשאת ולתת ולתבוע את הכספים לעצמו, שאם יהא שליח בלבד יצטרך להתיעץ במשלח, ולמעשה יתכן שלא יצליח בשליחותו. משמע שאף הוא סבר שאין אפשרות להקנות לו את הכספים בחליפין. ומספרים, \u0003כי אתא\u0004 \u0005[כאשר בא,\u0006 חזר\u0005]\u0006 רב שמואל בר אחא עם הכסף שמח כל כך רב פפא עד ש\u0003נפק לאפיה\u0004 \u0005[יצא לפניו,\u0006 הלך לקראתו\u0005]\u0006 \u0003עד\u0004 המקום \u0003תווך\u0004 לקבל את פניו.","\u0003וכן אמר עולא: אין מטבע נעשה חליפין. וכן אמר רב אסי: אין מטבע נעשה חליפין, וכן אמר רבה בר בר חנה אמר ר' יוחנן: אין מטבע נעשה חליפין.\u0004","\u0003איתיביה\u0004 \u0005[הקשה\u0006 לו\u0005]\u0006 \u0003רב אבא לעולא\u0004 ממה ששנינו: \u0003הרי שהיו חמריו ופועליו תובעין אותו\u0004 שכר שחייב להם כשהיה \u0003בשוק, ואמר לשולחני: תן לי ב\u0004שוה \u0003דינר מעות\u0004 קטנות יותר \u0003ואפרנסם\u0004 (ואשלם להם) \u0003ואני אעלה לך\u0004 (אשלם לך) אחר כך \u0003יפה\u0004 (שווה) \u0003דינר וטריסית\u0004 (מטבע קטנה) \u0003ממעות שיש לי בביתי. אם יש לו מעות\u0004 בבית באותה שעה — \u0003מותר.\u0004 לפי שאין זו קרויה הלוואה וממילא אין התוספת נחשבת כריבית, \u0003ואם לאו\u0004 \u0005[לא]\u0006 — הלוואה היא זו, \u0003ואסור\u0004 משום ריבית. \u0003ואי סלקא דעתך\u0004 \u0005[ואם עולה על דעתך]\u0006 לומר ש\u0003אין מטבע נעשה חליפין,\u0004 אם כן אינך יכול לומר שנעשו פה רק חליפין של מטבעות עם השולחני אלא \u0003הויא ליה\u0004 \u0005[הרי זו]\u0006 \u0003הלואה, ואסור! אשתיק\u0004 \u0005[שתק]\u0006 עולא.","\u0003אמר\u0004 רב אבא לעולא, בנסיון לתרץ את הקושיה: \u0003דלמא אידי ואידי\u0004 \u0005[שמא זה וזה],\u0006 הכספים שהיו בביתו והכספים שלקח \u0003בפרוטטות,\u0004 שהן פרוטות קטנות מאד \u0003שנו דליכא עלייהו טבעא\u0004 \u0005[שאין עליהן טביעה],\u0006 \u0003ואידי ואידי פירא הוו\u0004 \u0005[ואלה ואלה פירות הן]\u0006 \u0003ומשום הכי\u0004 \u0005[כך]\u0006 \u0003נקנו בחליפין. אמר\u0004 לו עולא: \u0003אין\u0004 \u0005[כן]\u0006 זו באמת הכוונה, \u0003דיקא נמי\u0004 \u0005[מדוייק גם כן]\u0006 תירוץ זה מסגנון הדברים \u0003דקתני\u0004 \u0005[ששנה]\u0006 \u0003יפה דינר וטריסית ולא קתני\u0004 \u0005[ולא שנה]\u0006 \u0003דינר יפה וטריסית.\u0004 משמע שאין מדובר במטבעות ממש, אלא בשוויים של מטבעות. מסכמים: אכן, \u0003שמע מינה\u0004 \u0005[למד ממנה]\u0006 שכן הוא.","\u0003רב אשי אמר: לעולם\u0004 יכול אתה לומר שאין כאן ענין של חליפין אלא \u0003בדמים.\u0004 ומדובר כאן \u0003בפרוטטות,\u0004 ואת הקושיה יש לתרץ כך: \u0003כיון דאית ליה\u0004 \u0005[שיש לו]\u0006 כסף בביתו \u0003נעשה כאומר הלויני עד שיבא בני או עד שאמצא מפתח\u0004 שאין זו קרויה הלוואה, ומשום כך אין כאן חשש ריבית.","ומציעים עוד פתרון לבעיה: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ממה ששנינו: \u0003כל הנעשה דמים באחר, כיון שזכה זה\u0004 — \u0003נתחייב זה\u0004 הצד האחר \u0003בחליפין.\u0004 ומעתה נברר את משמעות הדברים: \u0003כל הנעשה דמים באחר מאי ניהו\u0004 \u0005[מה הוא]\u0006 הדבר הזה הנעשה מחיר עבור דברים אחרים, בוודאי הכוונה — \u0003מטבע,\u0004 ואם כן \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 כי \u0003מטבע נעשה חליפין!\u0004","\u0003אמר רב יהודה: הכי קאמר\u0004 \u0005[כך אמר],\u0006 כך יש להבין את הדברים:"],["\u0003כל הנישום דמים באחר,\u0004 כל דבר שמעריכים את מחירו כאשר מחליפים אותו, כלומר מטלטלים, \u0003כיון שזכה זה נתחייב זה בחליפין.\u0004","ומעירים: \u0003הכי נמי מסתברא\u0004 \u0005[כך גם כן מסתבר]\u0006 לפרש, \u0003מדקתני סיפא\u0004 \u0005[מ\u0006כיון \u0005ששנה בסופה]\u0006 של אותה ברייתא: \u0003כיצד?\u0004 — \u0003החליף שור בפרה או חמור בשור.\u0004 ומעירים: אכן \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שזו הכוונה שמדובר בברייתא במטלטלים ולא בכספים.","ושואלים: \u0003ולמאי דסליק אדעתיה מעיקרא\u0004 \u0005[ולפי מה שעלה בדעתו מתחילה]\u0006 שהכוונה היא ל\u0003מטבע, מאי\u0004 \u0005[מה]\u0006 משמעה של לשון \u0003\"כיצד\"\u0004 זו? והלא לכאורה ברור שאי אפשר לפרש שמדובר במטבע! ומשיבים: \u0003הכי קאמר\u0004 \u0005[כך אמר]\u0006 \u0003ופירי נמי עבדי\u0004 \u0005[ופירות גם כן עושים]\u0006 \u0003חליפין\u0004 ולא רק מטבעות, \u0003כיצד?\u0004 — \u0003החליף שור בפרה או חמור בשור.\u0004","ושואלים: \u0003הניחא\u0004 \u0005[זה נוח]\u0006 לשיטת \u0003רב ששת,\u0004 ש\u0003אמר\u0004 ש\u0003פירי עבדי\u0004 \u0005[פירות עושים]\u0006 \u0003חליפין,\u0004 \u0003אלא לרב נחמן\u0004 ש\u0003אמר: כלי\u0004 — \u0003אין\u0004 \u0005[כן]\u0006 עושה חליפין, \u0003אבל פירי לא עבדי\u0004 \u0005[פירות אינם עושים]\u0006 \u0003חליפין,\u0004 \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"כיצד\"?\u0004","ומשיבים: \u0003הכי קאמר\u0004 \u0005[כך אמר]:\u0006 \u0003יש דמים שהן כחליפין,\u0004 פעמים שמקח בדמים דינו כחליפין, \u0003כיצד?\u0004 — \u0003החליף דמי שור בפרה או דמי חמור בשור.\u0004","ושואלים: \u0003מאי טעמיה\u0004 \u0005[מה טעמו]\u0006 של \u0003רב נחמן?\u0004 ומשיבים: \u0003סבר לה\u0004 \u0005[סבור הוא]\u0006 \u0003כ\u0004שיטת \u0003ר' יוחנן.\u0004 ש\u0003אמר\u0004 ר' יוחנן: \u0003דבר תורה,\u0004 כלומר, על פי עיקר דין תורה \u0003מעות קונות\u0004 וכיון ששילם הקונה במעות — נגמר הקנין. \u0003ומפני מה אמרו\u0004 חכמים ש\u0003משיכה קונה\u0004 — \u0003גזירה שמא יאמר לו\u0004 המוכר לקונה \u0003נשרפו חטיך בעלייה\u0004 לאחר שנתת את הכסף, ונמצא הקונה נפסד, ועל כן תיקנו שכל עוד גוף החפץ לא בא לידי הלוקח אין הקנין גמור.","ומעתה, \u0003מלתא דשכיחא\u0004 \u0005[דבר שמצוי]\u0006 — \u0003גזרו ביה רבנן\u0004 \u0005[בו חכמים]\u0006 גזירה זו שיגמר המקח רק במשיכה, אבל \u0003מלתא דלא שכיחא\u0004 \u0005[דבר שאינו מצוי]\u0006 \u0003לא גזרו ביה רבנן\u0004 \u0005[בו חכמים],\u0006 וקנין כזה שקנה מטלטלין בדמי מטלטלין דבר שאינו מצוי הוא, ולכן דנים בו כדין תורה, ונגמר הקנין עם נתינת הכסף.","ושואלים: \u0003ו\u0004לדעת \u0003ריש לקיש\u0004 ש\u0003אמר\u0004 ש\u0003משיכה מפורשת מן התורה,\u0004 ומעות עצמן אינן קונות, אם כן, \u0003הניחא\u0004 \u0005[זה נוח]\u0006 \u0003אי סבר לה\u0004 \u0005[אם סבור הוא]\u0006 כדעת \u0003רב ששת\u0004 בקנין פירות בחליפין, הרי \u0003מתרץ לה\u0004 \u0005[מיישב\u0006 הוא \u0005אותה],\u0006 את הברייתא, \u0003כרב ששת.\u0004","\u0003אלא אי סבר לה\u0004 \u0005[אם סבור הוא]\u0006 \u0003כ\u0004שיטת \u0003רב נחמן,\u0004 ש\u0003אמר: פירי לא עבדי\u0004 \u0005[פירות אינם עושים]\u0006 \u0003חליפין ומטבע לא קני\u0004 \u0005[אינו קונה],\u0006 אם כן \u0003היכי מתרץ לה\u0004 \u0005[איך\u0006 הוא \u0005מיישב אותה]?\u0006 ומשיבים: \u0003על כרחך\u0004 עליך לומר כי \u0003כרב ששת\u0004 הוא \u0003מתרץ\u0004 \u0005[מיישב]\u0006 אותה, ולא באופן אחר.","\u0003תנן\u0004 \u0005[שנינו\u0006 במשנה\u0005]:\u0006 \u0003כל המטלטלין קונין זה את זה. ואמר ריש לקיש: אפילו כיס מלא מעות בכיס מלא מעות,\u0004 משמע שיש קנין חליפין במעות! ודוחים: \u0003תרגמא\u0004 \u0005[הסבירה]\u0006 \u0003רב אחא: בדינר אנקא ואניגרא\u0004 (בדינרים פסולים) שאינם נחשבים ככסף, ואין בהם אלא ערך המתכת היקרה שבהם, ש\u0003אחד שפסלתו מלכות,\u0004 שהמלך גזר שלא ישתמשו יותר במטבע זה ו\u0003אחד שפסלתו\u0004 ה\u0003מדינה\u0004 שבני מדינה זו אינם רוצים להשתמש בו.","ופ\u0003וצריכא\u0004 \u0005[וצריך\u0006 לומר\u0005]\u0006 בשני המקרים: \u0003דאי אשמועינן\u0004 \u0005[שאם היה משמיע לנו]\u0006 רק במטבע ש\u0003פסלתו מלכות\u0004 הייתי אומר שהדין כן \u0003משום דלא סגי\u0004 \u0005[שאיננו\u0006 הולך, עובר \u0005]\u0006 לסוחר \u0003כלל,\u0004 שהרי המלך גזר ואסר את שימושו. \u0003אבל פסלתו מדינה, דסגי ליה\u0004 \u0005[שהוא\u0006 הולך, עובר \u0005]\u0006 לסוחר \u0003במדינה אחריתי\u0004 \u0005[אחרת]\u0006 — \u0003אימא אכתי\u0004 \u0005[אמור\u0006 ש\u0005עדיין]\u0006 \u0003מטבע הוא\u0004 \u0003ואין מטבע נקנה בחליפין.\u0004","\u0003ואי אשמועינן\u0004 \u0005[ואם היה משמיע לנו]\u0006 \u0003פסלתו מדינה, משום דלא סגי ליה\u0004 \u0005[שאינו עובר לסוחר]\u0006 באותו מקום \u0003לא בצנעא ולא בפרהסיא,\u0004 שהרי בני המדינה מסרבים להשתמש בו, \u0003אבל פסלתו מלכות דסגי ליה בצנעא\u0004 \u0005[שהוא מהלך,\u0006 נקנה, \u0005בצינעה]\u0006 — \u0003אימא אכתי\u0004 \u0005[אמור\u0006 שמא \u0005עדיין]\u0006 \u0003מטבע הוא\u0004 \u0003ואין מטבע נקנה בחליפין,\u0004 על כן \u0003צריכא\u0004 \u0005[נצרכה]\u0006 לומר בשניהם.","\u0003אמר רבא בר רב הונא,\u0004 אמר אדם לחבירו: \u0003\"מכור לי\u0004 חפץ שלך \u0003באלו\u0004 הכספים שבידי \u0003\",\u0004 ולא שאל המוכר כמה כספים הם — הרי זה \u0003קנה\u0004 במה שנתן לו, שנגמר המקח על ידי כך,"],["\u0003ויש לו עליו אונאה.\u0004","ומסבירים: \u0003קנה\u0004 — \u0003אף על גב\u0004 \u0005[אף על פי]\u0006 ש\u0003לא משך,\u0004 שמ\u0003כיון\u0004 ש\u0003לא קפיד\u0004 \u0005[הקפיד]\u0006 על הסכום — הרי הוא \u0003קנה,\u0004 כיון \u0003דכי חליפין דמי\u0004 \u0005[ש\u0006הדבר \u0005נחשב\u0006 כעין \u0005חליפין],\u0006 \u0003ויש לו עליו אונאה\u0004 כי \u0003\"מכור לי באלו\" קאמר ליה\u0004 \u0005[אמר לו],\u0006 שהיתה כאן לשון מכר, ומכר פירושו במחיר מקובל. ואילו \u0003רב אבא אמר רב הונא\u0004 סבור כי אם אמר \u0003\"מכור לי באלו\"\u0004 — \u0003קנה, ואין לו עליו אונאה,\u0004 שעשה כאן כקנין חליפין גמור. ומעתה באים לדון בפרטי הלכות אלה.","\u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005]\u0006 ש\u0003דמים ואין מקפיד עליהן,\u0004 כלומר, כשמוכר דבר בדמים, אבל איננו מקפיד עליהם שיהא המחיר מדוייק כערך הקניה — \u0003הא קאמרינן דקני\u0004 \u0005[הרי אמרנו שהוא קונה]\u0006 מיד, ש\u0003כחליפין דמו\u0004 \u0005[הם נחשבים].\u0006 עשה \u0003חליפין ומקפיד עליהן\u0004 שיהא הערך שווה, \u0003מאי\u0004 \u0005[מה\u0006 יהא הדין\u0005]?\u0006","\u0003אמר רב אדא בר אהבה: תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לדבר ממה ששנינו: \u0003הרי שהיה תופש פרתו ועומד, ובא חבירו ואמר לו: פרתך למה\u0004 עומדת כאן? אמר בעל הפרה: \u0003לחמור אני צריך.\u0004 ואמר החבר: \u0003יש לי חמור שאני נותן לך.\u0004 והוא שאל: \u0003פרתך בכמה.\u0004 ענה לו בעל הפרה: \u0003בכך וכך.\u0004 ושאל בעל הפרה: \u0003חמורך בכמה?\u0004 וענה בעל החמור \u0003בכך וכך.\u0004","אם \u0003משך בעל החמור את הפרה, ולא הספיק בעל הפרה למשוך את החמור עד שמת החמור\u0004 — \u0003לא קנה בעל החמור את הפרה,\u0004 אף שלכאורה היה כאן קנין חליפין, ובחליפין כשצד אחד מושך את החפץ נגמר בכך הקנין כולו.","\u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 כי \u0003חליפין ומקפיד עליהן\u0004 — \u0003לא קנה.\u0004 שהרי כאן לא הסתפקו בהחלפת פרה בחמור, אלא העריכו את שוויים של אלה, כיון שמקפידים על הערך אין הקנין נגמר עד שימשכו שניהם.","\u0003אמר רבא: אטו\u0004 \u0005[האם]\u0006 \u0003חליפין\u0004 שבתורה \u0003בשופטני עסקינן, דלא קפדי\u0004 \u0005[בטפשים\u0006 בשוטים \u0005עוסקים אנו, שאין\u0006 הם \u0005מקפידים\u0006 כלל על הערך\u0005],\u0006 ובלבד שיחליפו חפצים? \u0003אלא\u0004 ב\u0003כל חליפין מיקפד קפדי\u0004 \u0005[מקפידים]\u0006 \u0003ו\"קנה\"\u0004 ששנינו משמעו שבקנין נגמרו החליפין, ואת המחיר ישלים אחר כך. \u0003והכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 — כגון ש\u0003אמר ליה\u0004 \u0005[לו]:\u0006 הרי לך \u0003חמור בפרה וטלה, ומשך את הפרה ועדיין לא משך את הטלה,\u0004 ש\u0003לא הוה ליה\u0004 \u0005[היתה]\u0006 כאן עדיין \u0003משיכה מעליא\u0004 \u0005[מעולה,\u0006 גמורה\u0005].\u0006","\u0003אמר מר\u0004 \u0005[החכם]\u0006 בענין שעסקנו בו קודם \u0003\"מכור לי באלו\"\u0004 — \u0003קנה ויש לו עליו אונאה.\u0004 ושואלים: \u0003לימא סבר\u0004 \u0005[האם לומר\u0006 על בסיס הלכה זו \u0005שסבור]\u0006 \u0003רב הונא\u0004 ש\u0003מטבע נעשה חליפין?\u0004","ודוחים: \u0003לא, רב הונא סבר לה\u0004 \u0005[סבור הוא]\u0006 \u0003כ\u0004שיטת \u0003ר' יוחנן\u0004 ש\u0003אמר: דבר תורה מעות קונות. ומפני מה אמרו משיכה קונה\u0004 — \u0003גזירה שמא יאמר לו נשרפו חטיך בעלייה.\u0004 וכיון שרק גזירת חכמים היא, \u0003מלתא דשכיחא\u0004 \u0005[דבר שמצוי]\u0006 — \u0003גזרו בה רבנן\u0004 \u0005[בו חכמים],\u0006 \u0003ומלתא דלא שכיחא\u0004 \u0005[ודבר שאינו מצוי]\u0006 — \u0003לא גזרו בה רבנן\u0004 \u0005[בו חכמים],\u0006 ומכירה בצורה זו שהיא כעין חליפין — אינה שכיחה, ונשארה כדין תורה, שמעות קונות. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003מר הונא בריה\u0004 \u0005[בנו של]\u0006 \u0003רב נחמן לרב אשי: אתון, הכי מתניתו לה\u0004 \u0005[אתם, כך אתם שונים\u0006 לומדים\u0005]\u0006 את הענין הזה, \u0003אנן הכי מתנינן לה\u0004 \u0005[אנחנו כך שונים\u0006 את הענין\u0005],\u0006 כלומר, לא כמסקנה, אלא במפורש: \u0003וכן אמר רב הונא: אין מטבע נעשה חליפין.\u0004","כיון שדובר בקנין חליפין, שאלו: \u0003במה קונין,\u0004 כלומר, מה הוא האופן המקובל שבו מחזיקים חפץ מסויים כדי שיתקיים בכך קנין חליפין?","\u0003רב אמר:\u0004 קונים \u0003בכליו של קונה.\u0004 כלומר, הקונה נותן למוכר חפץ, וכאשר המוכר מושך את החפץ וקונה אותו לעצמו נגמרה על ידי כך פעולת הקנין. וטעמו — \u0003דניחא ליה\u0004 \u0005[שנוח לו]\u0006 \u0003לקונה דלהוי\u0004 \u0005[שיהא]\u0006 ה\u0003מקנה\u0004 כ\u0003קונה\u0004 את החפץ \u0003כי היכי דלגמר ולקני ליה\u0004 \u0005[כדי\u0006 \u0005שיגמור\u0006 בלבו \u0005ויקנה לו].\u0006 \u0003ולוי אמר:\u0004 קונים \u0003בכליו של מקנה, שהוא\u0004 נותן את החפץ שימשכנו הקונה, \u0003כדבעינן למימר לקמן\u0004 \u0005[כפי שאנחנו רוצים לומר לפנינו,\u0006 בהמשך הדיון\u0005].\u0006","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב הונא מ\u0004ן המקום \u0003דסקרתא\u0004 \u0003לרבא: ול\u0004שיטת \u0003לוי\u0004 ש\u0003אמר\u0004 שקונים \u0003בכליו של מקנה,\u0004 אם היה זה מקרה של קנין קרקע בחליפין \u0003הא קא קני ארעא\u0004 \u0005[הרי\u0006 נמצא ש\u0005קנה קרקע]\u0006 \u0003אגב גלימא\u0004 \u0005[אגב גלימה],\u0006 שהרי הקונה מושך את הגלימה וקונה אותה, ואגב כך נקנית לו גם הקרקע, ו\u0003אם כן הוו ליה\u0004 \u0005[הרי זה]\u0006 מקרה שבו \u0003נכסים שיש להן אחריות\u0004 (כגון קרקע) \u0003ו\u0004\u0003נקנים עם נכסים שאין להן אחריות. ואנן איפכא תנן\u0004 \u0005[ואנו ההיפך שנינו\u0006 במשנה\u0005]:\u0006 \u0003נכסים שאין להן אחריות נקנין עם נכסים שיש להן אחריות!\u0004","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אי הוה\u0004 \u0005[אילו היה]\u0006 \u0003לוי\u0004 שהקשית עליו \u0003הכא\u0004 \u0005[כאן],\u0006 \u0003הוה מפיק לאפך פולסי דנורא\u0004 \u0005[היה מוציא אליך שבטים של אש]\u0006 להלקותך בהם, על השאלה הבלתי הוגנת! \u0003מי סברת גלימא\u0004 \u0005[האם סבור אחה\u0006 שבשעת הקנין \u0005גלימה]\u0006 ממש הוא \u0003מקנה ליה\u0004 \u0005[לו]?\u0006 אינו כן, אלא \u0003בההיא\u0004 \u0005[באותה]\u0006 \u0003הנאה דקא\u0004 \u0005[שהוא]\u0006 \u0003מקבל מיניה\u0004 \u0005[ממנו]\u0006 — הריהו \u0003גמר ואקני ליה\u0004 \u0005[\u0006\u0005גומר ומקנה לו],\u0006 שאין קבלת החפץ כקניית שאר הנכסים בקניין אגב, אלא שעשה קנין ומקנה גם דברים אחרים.","ומעירים, מחלוקת רב ולוי היא \u0003כתנאי\u0004 \u0005[כ\u0006מחלוקת \u0005תנאים]\u0006 שנחלקו כבר בשאלה זו: שהכתוב אומר \u0003\"וזאת לפנים בישראל על הגאולה ועל התמורה לקים כל דבר שלף איש נעלו ונתן לרעהו\"\u0004 (רות ד, ז). ומסבירים: \u0003\"גאולה\" זו מכירה, וכן הוא אומר: \"\u0004לא ימכר \u0003ולא יגאל\"\u0004 (ויקרא כז, כח). \u0003\"תמורה\"\u0004 — \u0003זו חליפין, וכן הוא אומר \"לא יחליפנו ולא ימיר אתו\"\u0004 (שם י).","בהמשך נאמר \u0003\"לקים כל דבר שלף איש נעלו ונתן לרעהו\",\u0004 ויש לברר \u0003מי נתן למי?\u0004 ומשיבים: \u0003בועז\u0004 הקונה \u0003נתן לגואל\u0004 שהוא המקנה המוכר שכך נעשה קנין. \u0003ר' יהודה אומר: גואל נתן לבועז,\u0004 ואם כן נמצא שהיתה כבר מחלוקת תנאים בכליו של מי נעשה הקנין.","\u0003תנא\u0004 \u0005[שנה]\u0006 החכם: \u0003קונין\u0004 קנין חליפין \u0003בכלי אף על פי שאין בו שוה פרוטה. אמר רב נחמן: לא שנו\u0004 שדי לקנין חליפין אף דבר שאינו שווה פרוטה, \u0003אלא בכלי\u0004 שבו עושים חליפין, \u0003אבל בפירי\u0004 \u0005[בפירות]\u0006 — \u0003לא. רב ששת אמר: אפילו בפירות.\u0004 ומסבירים: \u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003רב נחמן\u0004 — \u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 \u0003\"נעלו\"\u0004 (רות ד, ז) ומכאן נלמד: \u0003נעל\u0004 — \u0003אין\u0004 \u0005[כן],\u0006 וכל דבר הדומה לנעל שהוא כלי, \u0003מידי אחרינא\u0004 \u0005[דבר אחר]\u0006 שאיננו כלי — \u0003לא\u0004 נעשה בו קנין.","\u0003מאי טעמיה\u0004 \u0005[מה טעמו]\u0006 של \u0003רב ששת\u0004 — \u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"לקים כל דבר\"\u0004 (שם). ושואלים: \u0003לרב נחמן נמי\u0004 \u0005[גם כן],\u0006 \u0003הכתיב\u0004 \u0005[הרי נאמר]\u0006 \u0003\"לקים כל דבר\"!\u0004 ומשיבים: הכתוב \u0003ההוא\u0004 כוונתו: \u0003לקים כל דבר,\u0004 ש\u0003נקנין\u0004 כל הדברים \u0003במנעל.\u0004 ושואלים מצד אחר: \u0003ורב ששת נמי\u0004 \u0005[גם כן]\u0006 \u0003הכתיב\u0004 \u0005[הלא נאמר]\u0006 \u0003\"נעלו\"!\u0004 ומשיבים: \u0003אמר\u0004 \u0005[\u0006יכול היה \u0005לומר]\u0006 \u0003לך\u0004 \u0003רב ששת,\u0004 כך יש ללמוד מכאן: \u0003מה נעלו דבר המסויים\u0004 שהוא שלם ומוגדר לעצמו \u0003אף כל דבר המסויים, לאפוקי\u0004 \u0005[להוציא]\u0006 \u0003חצי רמון וחצי אגוז\u0004 שאין הם בגדר דבר מסויים ולכך \u0003לא\u0004 עושים בכעין זה קנין חליפין, ואולם ברימון ואגוז שלם אכן אפשר לעשות.","\u0003אמר רב ששת בריה\u0004 \u0005[בנו\u0006 של \u0003רב אידי: כמאן כתבינן האידנא\u0004 \u0005[כ\u0006דעת \u0005מי כותבים אנו כיום]\u0006 בשטרות, שנעשה הקנין \u0003\"במנא דכשר למקניא ביה\"\u0004 \u0005[\"בכלי הכשר לקנות בו\"].\u0006 ומסבירים: \u0003\"במנא\"\u0004 \u0005[\"בכלי\"]\u0006 מדגישים זאת כדי \u0003לאפוקי\u0004 \u0005[להוציא]\u0006 \u0003מ\u0004דברי \u0003רב ששת\u0004 ש\u0003אמר קונין בפירות. \"דכשר\"\u0004 — הרי זה בא \u0003לאפוקי\u0004 \u0005[להוציא]\u0006 \u0003מ\u0004דעת \u0003שמואל,\u0004 ש\u0003אמר קונין\u0004"],["\u0003במרוקא\u0004 (גרעיני תמרים המשמשים למרק ולהחליק בהם קלף), \u0003למקניא\u0004 \u0005[לקנות בו]\u0006 — \u0003לאפוקי\u0004 \u0005[להוציא]\u0006 מדברי \u0003לוי,\u0004 ש\u0003אמר\u0004 שהקנין נעשה \u0003בכליו של מקנה,\u0004 על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 בלשון זו \u0003\"למקניא\"\u0004 \u0005[\"לקנות\"]\u0006 \u0003ולא \"לקנויי\"\u0004 \u0005[\"להקנות\"].\u0006 המלה \u0003\"ביה\"\u0004 \u0005[\"בו\"]\u0006 שבשטר, \u0003רב פפא אמר:\u0004 דבר זה בא \u0003למעוטי\u0004 \u0005[למעט]\u0006 \u0003מטבע\u0004 שאין עושים בו חליפין. \u0003ורב זביד\u0004 אמר, \u0003ואיתימא\u0004 \u0005[ויש אומרים]\u0006 ש\u0003רב אשי\u0004 הוא זה ש\u0003אמר: למעוטי\u0004 \u0005[למעט]\u0006 \u0003איסורי הנאה.\u0004","\u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 שבאופן אחר הסבירו את הלשון: \u0003\"ביה\", אמר רב פפא:\u0004 הרי זה בא \u0003למעוטי\u0004 \u0005[למעט]\u0006 \u0003מטבע\u0004 שאי אפשר לעשות בו קנין חליפין. והמלה \u0003\"דכשר\"\u0004 שבשטר, \u0003אמר רב זביד ואיתימא\u0004 \u0005[ויש אומרים]\u0006 שאמר זאת \u0003רב אשי,\u0004 מילה זו באה \u0003למעוטי\u0004 \u0005[למעט]\u0006 \u0003איסורי הנאה. אבל מוריקא\u0004 שמיעטנו בלשון קודמת בביאור זה \u0003לא אצטריך\u0004 \u0005[הוצרך\u0006 לומר\u0005]\u0006 שאין עושים בו קנין, כיון שאינו חשוב כלל.","ומעתה שבים לפרש את המשנה לגופה. שנינו במשנה ש\u0003אסימון קונה את המטבע.\u0004 ושאלו: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"אסימון\"? אמר רב:\u0004 הכוונה היא ל\u0003מעות הניתנות בסימן לבית מרחץ.\u0004 שהיה בית המרחץ מחלק סימנים מסויימים כעין כרטיסי כניסה ואחר כך היו משלמים עבורם, והם עצמם אינם מטבעות.","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על כך ממה ששנינו במשנה: \u0003אין מחללין מעשר שני על אסימון ולא על מעות הניתנות בסימן לבית המרחץ. מכלל\u0004 הדברים אתה למד ש\u0003אסימון לאו\u0004 \u0005[לא]\u0006 \u0003מעות הניתנות בסימן לבית המרחץ! וכי תימא פרושי קמפרש\u0004 \u0005[ואם תאמר\u0006 כי \u0005מפרש הוא]\u0006 באותה משנה ומסביר מה הוא אסימון — \u0003והא\u0004 \u0005[והרי]\u0006 \u0003לא תנא הכי\u0004 \u0005[שנה\u0006 החכם \u0005כך],\u0006 שהרי שנינו במשנה אחרת: \u0003מחללין מעשר שני על אסימון,\u0004 אלו \u0003דברי ר' דוסא. וחכמים אומרים: אין מחללין. ושוין\u0004 כולם בדעתם \u0003שאין מחללין על מעות הניתנות בסימן לבית המרחץ,\u0004 ואם כן ברור שאין האסימון מעות הניתנות לבית המרחץ!","\u0003אלא\u0004 \u0003אמר ר' יוחנן\u0004 יש לומר פירוש אחר: \u0003מאי\u0004 \u0005[מה\u0006 הוא\u0005]\u0006 \u0003אסימון\u0004 — \u0003פולסא,\u0004 עיגול מתכת העשוי לצורך מטבע שעדיין לא נטבעה עליו צורה. ומעירים: \u0003ואזדא\u0004 \u0005[והולך]\u0006 \u0003ר' יוחנן לטעמיה\u0004 \u0005[לטעמו,\u0006 לשיטתו\u0005]\u0006 בפירוש זה, ש\u0003אמר ר' יוחנן\u0004 במקום אחר: \u0003ר' דוסא ור' ישמעאל אמרו דבר אחד,\u0004 שיש להם שיטה בסיסית אחת, \u0003ר' דוסא\u0004 — \u0003הא דאמרן\u0004 \u0005[זו שאמרנו],\u0006 שלדעתו אסימון דינו כמטבע. שיטת \u0003ר' ישמעאל מאי היא\u0004 \u0005[מה הוא]\u0006 — \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 מה שנאמר \u0003\"וצרת הכסף בידך\"\u0004 (דברים יד, כב) — הרי זה בא \u0003לרבות כל דבר הנצרר ביד,\u0004 שיש לו ערך כספי, אלו \u0003דברי ר' ישמעאל, ר' עקיבא אומר: לרבות כל דבר שיש עליו צורה.\u0004 הרי שר' עקיבא סבור שצריך מטבע טבועה דווקא, ולדעת ר' ישמעאל אפילו אסימון כשר.","שנינו במשנה הסבר \u0003כיצד\u0004 נעשה קנין — שאם \u0003משך\u0004 הקונה \u0003הימנו\u0004 (ממנו), מן המוכר, \u0003פירות ולא נתן לו מעות\u0004 — \u0003אינו יכול לחזור בו,\u0004 אבל לאחר נתינת מעות בלבד יכול לחזור בו. וכאן מקומה של המחלוקת שהוזכרה כבר קודם בדרך אגב. \u0003אמר ר' יוחנן: דבר תורה,\u0004 מעיקר דין התורה \u0003מעות קונות,\u0004 וכשנותן כסף — מיד נקנה החפץ למשלם \u0003ומפני מה אמרו\u0004 חכמים ש\u0003משיכה קונה\u0004 — \u0003גזירה שמא יאמר לו\u0004 המוכר אחרי שקיבל את הכסף \u0003נשרפו חטיך בעלייה\u0004 ונמצא הקונה נפסד. ומשום כך תיקנו שלא יגמר הממכר עד שמקבל הקונה את גוף החפץ עצמו.","ושואלים: ולולא תקנה זו מה בעצם ההפסד? \u0003סוף סוף, מאן דשדא\u0004 \u0005[מי שהטיל]\u0006 את ה\u0003דליקה בעי שלומי\u0004 \u0005[צריך לשלם],\u0006 ואם כן ישלם לקונה, ואינו מפסיד איפוא! \u0003אלא\u0004 כך יש לומר: \u0003גזירה\u0004 היא שגזרו חכמים מתוך החשש \u0003שמא תפול דליקה באונס\u0004 ולא באשמת מישהו. \u0003אי מוקמת להו ברשותיה\u0004 \u0005[אם מעמיד אתה אותו,\u0006 את החפץ, \u0005ברשותו]\u0006 של המוכר הריהו \u0003מסר נפשיה, טרח ומציל\u0004 \u0005[ימסור את נפשו, יטרח ויציל],\u0006 שהרי את שלו הוא מציל. \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003לא,\u0004 שהחטים עכשיו שייכות לקונה — \u0003לא מסר נפשיה טרח ומציל\u0004 \u0005[ימסור את נפשו לטרוח ולהציל],\u0006 זו שיטת ר' יוחנן.","\u0003ריש לקיש אמר: משיכה מפורשת מן התורה,\u0004 שדין המשיכה דין תורה הוא, ולא תקנת חכמים בלבד. ושואלים: \u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003ריש לקיש,\u0004 מהיכן למד? ומשיבים: \u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"וכי תמכרו ממכר לעמיתך או קנה מיד עמיתך\u0004 אל תונו איש את אחיו\u0003\"\u0004 (ויקרא כה, יד), וכוונתו: \u0003דבר הנקנה מיד ליד,\u0004 משמע: משיכה.","\u0003ור' יוחנן אמר: \"מיד\"\u0004 שנאמר אין כוונתו מיד ליד ממש, ובא רק \u0003למעוטי\u0004 \u0005[למעט]\u0006 \u0003קרקע דלית\u0004 \u0005[שאין]\u0006 \u0003בה אונאה,\u0004 שהרי אינה עוברת מיד ליד כלל.","ושואלים: \u0003וריש לקיש\u0004 מה עונה הוא על הסבר זה? ומשיבים: אכן, גם הוא מפרש שבקרקע אין הונאה, אלא לדעתו \u0003אם כן לכתוב קרא\u0004 \u0005[שיאמר הכתוב]\u0006 \u0003\"וכי תמכרו ממכר מיד עמיתך אל תונו\", \"או קנה\" למה לי? שמע מינה\u0004 \u0005[למד מכאן]\u0006 שבא הדבר ללמדנו דין \u0003משיכה\u0004.","ושואלים: \u0003ור' יוחנן \"או קנה\" מאי עביד ליה\u0004 \u0005[מה עושה\u0006 הוא \u0005בו],\u0006 כיצד מפרש הוא אותו? ומשיבים: \u0003מיבעי ליה לכדתניא\u0004 \u0005[נחוץ לו\u0006 הדבר \u0005לכפי ששנינו\u0006 בברייתא\u0005]:\u0006 ממה שנאמר \u0003\"וכי תמכרו ממכר אל תונו\"\u0004 \u0003אין לי\u0004 ללמוד \u0003אלא\u0004 למקרה בו \u0003נתאנה\u0004 (רומה) ה\u0003לוקח,\u0004 ואולם אם \u0003נתאנה\u0004 (רומה) ה\u0003מוכר מנין?\u0004 — \u0003תלמוד לומר: \"או קנה אל תונו\",\u0004 לומר, גם כשקונים אסור להונות את המוכר.","ושואלים: \u0003וריש לקיש\u0004 מה אומר הוא על הלכה זו? ומשיבים: \u0003תרתי גמר מיניה\u0004 \u0005[שני\u0006 דברים \u0005לומד\u0006 הוא \u0005מכאן],\u0006 גם לענין אונאת המוכר, וגם לענין דרך הקניה.","\u0003תנן\u0004 \u0005[שנינו\u0006 במשנתנו\u0005],\u0006 \u0003ר' שמעון אומר: כל שהכסף בידו ידו על העליונה.\u0004 ומכאן נלמד כי ה\u0003מוכר הוא דמצי הדר ביה\u0004 \u0005[שיכול לחזור בו],\u0006 ואילו ה\u0003לוקח לא מצי הדר ביה\u0004 \u0005[יכול לחזור בו].\u0006 ומעתה, \u0003אי אמרת בשלמא\u0004 \u0005[נניח אם אומר אתה]\u0006 ש\u0003מעות קונות\u0004 — \u0003משום הכי\u0004 \u0005[כך]\u0006 ה\u0003מוכר מצי הדר ביה\u0004 \u0005[יכול לחזור בו]\u0006 ואילו ה\u0003לוקח לא מצי הדר ביה\u0004 \u0005[יכול לחזור בו],\u0006 שכדברי ר' יוחנן עשו תקנה במשיכה רק לטובתו של הקונה כדי שלא יפסיד את סחורתו, אבל המעות נקנו מיד. \u0003אלא אי אמרת\u0004 \u0005[אם אומר אתה]\u0006 בכלל \u0003ש\u0004\u0003מעות אינן קונות\u0004 — אם כן ה\u0003לוקח נמי ליהדר ביה\u0004 \u0005[גם כן יחזור בו]!\u0006","ומשיבים: \u0003אמר\u0004 \u0005[\u0006יכול היה \u0005לומר]\u0006 \u0003לך\u0004 \u0003ריש לקיש: אליבא\u0004 \u0005[על פי שיטת]\u0006 \u0003ר' שמעון\u0004 — \u0003לא קאמינא\u0004 \u0005[אין אני אומר],\u0006 \u0003כי קאמינא\u0004 \u0005[כי אומר אני]\u0006 הרי זה \u0003אליבא דרבנן\u0004 \u0005[על פי\u0006 שיטת \u0005חכמים].\u0006","ושואלים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003ל\u0004שיטת \u0003ריש לקיש\u0004 — \u0003היינו דאיכא\u0004 \u0005[זהו\u0006 ההבדל \u0005שישנו]\u0006 \u0003בין ר' שמעון לרבנן\u0004 \u0005[וחכמים]\u0006 שנחלקו בדבר קנין מעות, \u0003אלא ל\u0004שיטת \u0003ר' יוחנן, מאי איכא\u0004 \u0005[מה יש,\u0006 מה ההבדל\u0005]\u0006 \u0003בין ר' שמעון\u0004 וחכמים? ומשיבים: \u0003איכא בינייהו\u0004 \u0005[יש ביניהם\u0006 מחלוקת\u0005]\u0006 בנושא שאמר \u0003רב חסדא.\u0004 ש\u0003אמר רב חסדא: כדרך שתקנו משיכה במוכרין כך תקנו משיכה בלקוחות,\u0004 שכל עוד לא היתה משיכה יכול גם הלקוח לחזור בו. \u0003ר' שמעון לית ליה\u0004 \u0005[אין לו,\u0006 אינו מקבל\u0005]\u0006 את שיטת \u0003רב חסדא,\u0004 ואילו \u0003רבנן אית להו\u0004 \u0005[יש להם,\u0006 מקבלים\u0005]\u0006 את דברי \u0003רב חסדא\u0004","\u0003תנן\u0004 \u0005[שנינו\u0006 במשנתנו\u0005]:\u0006 \u0003אבל אמרו מי שפרע מדור המבול הוא עתיד ליפרע ממי שאינו עומד בדיבורו. אי אמרת בשלמא\u0004 \u0005[נניח אם אומר אתה]\u0006 ש\u0003מעות קונות\u0004 — \u0003משום הכי קאי\u0004 \u0005[כך עומד]\u0006 זה שחזר מדיבורו \u0003ב\u0004קללה זו של \u0003\"אבל\",\u0004 \u0003אלא אי אמרת\u0004 \u0005[אם אומר אתה]\u0006 ש\u0003מעות אינן קונות, אמאי קאי\u0004 \u0005[מדוע עומד]\u0006 הוא \u0003ב\u0004קללה של \u0003\"אבל\"?\u0004 ומשיבים: \u0003משום דברים,\u0004 מפני שהבטיח לקנות ולא עמד בדיבורו.","ושואלים: \u0003ו\u0004כשחוזר בו מ\u0003דברים\u0004 בלבד, מבלי שעשה כל מעשה קנין \u0003מי קאי\u0004 \u0005[האם עומד]\u0006 הוא \u0003ב\u0004קללה זו של \u0003\"אבל\"\u0004 מי שפרע? \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006"],["\u0003ר' שמעון אומר: אף על פי שאמרו\u0004 ש\u0003טלית קונה דינר זהב ואין דינר זהב קונה טלית, מכל מקום כך הלכה\u0004 לענין תביעה בבית דין, \u0003אבל אמרו\u0004 חכמים על העושה כן: \u0003מי שפרע מאנשי דור המבול ומאנשי דור הפלגה ומאנשי סדום ועמורה וממצרים בים\u0004 — \u0003הוא עתיד ליפרע ממי שאינו עומד בדיבורו.\u0004","\u0003והנושא ונותן בדברים\u0004 בהבטחה בלבד — \u0003לא קנה, והחוזר בו\u0004 מהבטחתו — \u0003אין רוח חכמים נוחה הימנו.\u0004","\u0003ואמר רבא: אנו אין לנו\u0004 בחוזר בו בדיבור \u0003אלא \"אין רוח חכמים נוחה הימנו\"\u0004 אבל לא קללה. ומסבירים: היה הסכם ב\u0003דברים ואיכא בהדייהו\u0004 \u0005[ויש איתם]\u0006 נתינת \u0003מעות\u0004 \u0003קאי\u0004 \u0005[עומד]\u0006 בקללת \u0003\"אבל\u0004 אמרו מי שפרע וכו' \u0003\".\u0004 היה הסכם ב\u0003דברים וליכא בהדייהו\u0004 \u0005[ואין איתם]\u0006 נתינת \u0003מעות\u0004 — \u0003לא קאי\u0004 \u0005[אינו עומד]\u0006 על כך \u0003ב\u0004קללת \u0003\"אבל\".\u0004","\u0003אמר רבא: קרא ומתניתא מסייע ליה\u0004 \u0005[הכתוב והברייתא מסייעים לו]\u0006 \u0003לריש לקיש\u0004 שמדין תורה אין מעות קונות. \u0003קרא, דכתיב\u0004 \u0005[הכתוב, שנאמר]:\u0006 \u0003\"וכחש בעמיתו בפקדון או בתשומת יד או בגזל או עשק את עמיתו\"\u0004 (ויקרא ה, כא). וכך משמעות הכתוב: \u0003\"תשומת יד\"\u0004 מה הוא — \u0003אמר רב חסדא:\u0004 בכל אלה יש דמיון להפקדה בפקדון, שבכולם צריכה להיות הכחשה של דבר המצוי בעין \u0003כגון שיחד לו\u0004 הלווה \u0003כלי להלואתו\u0004 כמשכון, ואינו רוצה לתת את מה שלווה, ולא את הכלי. \u0003\"עשק\"\u0004 — \u0003אמר רב חסדא: כגון שיחד לו כלי לעשקו,\u0004 שנתן לשכיר פקדון כדי להבטיח את משכורתו, ולקח אותו ולא שילם.","\u0003וכי אהדריה קרא\u0004 \u0005[וכאשר חזר הכתוב]\u0006 על אותו ענין לענין השבת הגזל והעשק \u0003כתיב\u0004 \u0005[נאמר]\u0006 \u0003\"והיה כי יחטא ואשם והשיב את הגזלה אשר גזל או את העשק אשר עשק או את הפקדון אשר הפקד אתו\"\u0004 (שם כג), \u0003ואילו תשומת יד לא אהדריה\u0004 \u0005[חזר עליה],\u0006 \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 לא חזר ומנה זאת? — \u0003לאו\u0004 \u0005[\u0006האם \u0005לא]\u0006 \u0003משום דמחסרא\u0004 \u0005[ש\u0006היא \u0005מחוסרת]\u0006 \u0003משיכה?\u0004 שכיוון שלא משך המלוה את חפץ המשכון, לא נקנה לו המשכון כפקדון גמור, ולכן גם אם אינו משלם — אינו חייב קרבן שבועה, שלא היתה כאן כפירה בחפץ ממשי. ומשמע מכאן שללא משיכה אין קנין גמור!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב פפא לרבא: אימא\u0004 \u0005[אמור]\u0006 כי \u0003מ\u0004דין \u0003עושק הוא דהדר קרא\u0004 \u0005[שחזר הכתוב],\u0006 כיון שאף בעושק לא היתה כפירה בחפץ ממשי, ובכל זאת חזר הכתוב עליו לענין חובת השבה, והוא הדין גם לתשומת יד! ודוחים: \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 — \u0003כגון שנטלו ממנו\u0004 הפועל וקנה את החפץ קנין גמור \u0003וחזרו והפקידו אצלו\u0004 שאז היתה כאן כפירה בפקדון ממש.","ומקשים, אם כן \u0003היינו\u0004 \u0005[הרי זה]\u0006 בדיוק \u0003פקדון,\u0004 ומה חידש הכתוב? ומשיבים: ישנם \u0003תרי גוני\u0004 \u0005[שני מיני]\u0006 \u0003פקדון:\u0004 פקדון שמפקיד אצלו סתם, ופקדון שנותן לו חפץ שהיה שייך קודם למחזיק בפקדון.","ושואלים: \u0003אי הכי\u0004 \u0005[אם כן]\u0006 שבאופן כזה אתה מסביר \u0003תשומת יד נמי ליהדריה\u0004 \u0005[גם כן יחזור]\u0006 הכתוב ויאמרה, \u0003ולוקמיה\u0004 \u0005[ושיעמיד,\u0006 יסביר\u0005]\u0006 את המצב \u0003כגון שנטלו הימנו\u0004 המלוה וקנה אותו קנין גמור במשיכה \u0003וחזר והפקידו אצלו!\u0004 ואומרים: \u0003אי אהדריה קרא\u0004 \u0005[אם הכתוב היה חוזר]\u0006 על תשומת יד — \u0003לא\u0004 היתה כאן \u0003תיובתא\u0004 \u0005[קושיה חמורה]\u0006 לריש לקיש \u0003ולא סייעתא\u0004 \u0005[סיוע],\u0006 שאכן אפשר היה לפרש באופן אחר. \u0003השתא\u0004 \u0005[עכשיו]\u0006 ש\u0003לא אהדריה קרא\u0004 \u0005[חזר על כך הכתוב]\u0006 הרי זה \u0003מסייע ליה\u0004 \u0005[לו]\u0006 שאין קנין בלא משיכה.","לגוף הדבר שואלים: ו\u0003\"תשומת יד\" לא אהדריה קרא\u0004 \u0005[חזר עליו הכתוב]?\u0006 \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005],\u0006 \u0003אמר ר' שמעון: מנין ליתן את האמור למעלה למטה,\u0004 כלומר, מנין שכל הכתוב בפסוק הראשון שייך גם לשני — \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"או מכל אשר ישבע עליו לשקר\"\u0004 (שם כד), כלומר, שחוזר ומוסיף בפסוק השני גם דברים שנאמרו בפסוק הראשון, \u0003ואמר רב נחמן אמר רבה בר אבוה אמר רב:\u0004 מה שבא ר' שמעון ללמדנו הרי זה \u0003לרבות תשומת יד להישבון.\u0004 ואם כן גם תשומת יד הריהי כאילו חזר עליה הכתוב! ודוחים: מכל מקום, \u0003בהדיא מיהא\u0004 \u0005[במפורש על כל פנים]\u0006 \u0003לא אהדריה קרא\u0004 \u0005[חזר עליה הכתוב]\u0006 וניתן ללמוד זאת מהשמטה זו.","\u0003מתניתא מנלן\u0004 \u0005[ברייתא מנין לנו]\u0006 שתהא סיוע לריש לקיש? — \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 היתה לאדם פרוטה של הקדש אם \u0003נתנה לבלן\u0004 כדי לשלם שכר מרחץ — \u0003מעל\u0004 עם הנתינה \u0003ואמר רב: דוקא בלן הוא\u0004 שבנתינה מועל מיד, משום שקנין זה \u0003לא מחסרא\u0004 \u0005[חסר]\u0006 \u0003משיכה,\u0004 שאין כאן מה למשוך, אלא להכנס למרחץ ולרחוץ. \u0003אבל מידי אחריתא דמחסרא\u0004 \u0005[דבר אחר ש\u0006הוא \u0005חסר]\u0006 \u0003משיכה\u0004 — \u0003לא מעל עד דמשיך\u0004 \u0005[שימשוך],\u0006 והרי זו הוכחה שמדין תורה אין קנין בכסף אלא במשיכה.","ושואלים: \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 פרוטת הקדש, אם \u0003נתנה לספר\u0004 — \u0003מעל\u0004 מיד. \u0003וספר הא בעי לממשך\u0004 \u0005[הרי צריך למשוך]\u0006 עכשיו \u0003תספורת,\u0004 שהרי כאן יש מה למשוך, וכל עוד אינו מחזיק בו ממש לא נגמרה העסקה! ומשיבים: \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 — \u0003בספר גוי דלאו בר\u0004 \u0005[שלא בן]\u0006 \u0003משיכה הוא,\u0004 שקנין משיכה הוא דווקא בעסקות של ישראל בינם לבין עצמם, אבל בגויים הכל מודים שכסף קונה.","ומעירים, \u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך]:\u0006 \u0003נתנה לספר או לספן או לכל בעלי אומנות\u0004 אחרים — \u0003לא מעל עד\u0004 ש\u0003משך.\u0004 ולכאורה \u0003קשיין אהדדי\u0004 \u0005[קשות\u0006 הברייתות \u0005זו על זו]\u0006 שבאחת נאמר שהספר מעל מיד עם נתינה, ובשניה נאמר עד שמשך. \u0003אלא לאו שמע מינה\u0004 \u0005[האם לא תלמד מכאן]\u0006 כי \u0003כאן\u0004 מדובר \u0003בספר גוי\u0004 שהוא מועל עם נתינת מעות, ו\u0003כאן\u0004 מדובר \u0003בספר ישראל\u0004 שהוא אינו מועל עד שמושך. ומסכמים: אכן \u0003שמע מינה.\u0004","ומעירים לעצם המחלוקת בין ריש לקיש ור' יוחנן. \u0003וכן אמר רב נחמן, דבר תורה מעות קונות.\u0004 ומעירים \u0003ובדקה,\u0004 חיפשה, החכם \u0003לוי במתניתיה\u0004 \u0005[במשניות שלו]\u0006 שגם הוא ערך קובץ של ברייתות \u0003ואשכח\u0004 \u0005[ומצא]\u0006 הלכה זו: מעה של הקדש, אם \u0003נתנה לסיטון\u0004 כתשלום ראשון עבור פירות מרובים שקונה ממנו — \u0003מעל\u0004 והרי לא משך את הפירות כלל! משמע שנתינת המעות היא עצמה קנין, והרי זו ראיה שמעות קונות דבר תורה."],["\u0003אלא קשיא\u0004 \u0005[קשה\u0006 ברייתא זו\u0005]\u0006 \u0003לריש לקיש!\u0004 ומשיבים: \u0003אמר\u0004 \u0005[\u0006יכול היה \u0005לומר]\u0006 \u0003לך\u0004 \u0003ריש לקיש: הא מני\u0004 \u0005[\u0006ברייתא \u0005זו\u0006 כשיטת \u0005מי היא]\u0006 — כשיטת \u0003ר' שמעון היא,\u0004 ולא כשיטת חכמים.","שנינו במשנה שמי שחוזר בו אחרי מתן כסף, יכול אמנם לבטל קניינו, ואי אפשר לכפות אותו, \u0003אבל אמרו מי שפרע\u0004 מאנשי דור המבול ומדור הפלגה יפרע ממי שאינו עומד בדיבורו. \u0003איתמר\u0004 \u0005[נאמר]\u0006 שנחלקו אמוראים בשאלה הבאה, \u0003אביי אמר: אודועי מודעינן ליה\u0004 \u0005[מודיעים לו]\u0006 למי שחזר בו: דע לך שכך וכך עונשו של אדם שאיננו עומד בדיבורו. \u0003רבא אמר: מילט לייטינן ליה\u0004 \u0005[מקללים אותו],\u0006 כלומר, אומרים לו דברים אלה כקללה.","ומסבירים; \u0003אביי אמר: אודועי מודעינן ליה\u0004 \u0005[מודיעים אנו לו]\u0006 — \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ונשיא בעמך לא תאר\"\u0004 (שמות כב, כז), ומכאן למדנו שאסור לקלל נשיא ואף כל אדם מישראל. ואילו \u0003רבא אמר: מילט לייטינן ליה\u0004 \u0005[מקללים אנו אותו]\u0006 ולאיסור קללה אין לחשוש שהרי נאמר \u0003\"בעמך\",\u0004 וכוונתו: \u0003בעושה מעשה עמך,\u0004 אבל מי שאיננו נוהג ככשרים מישראל מותר לקללו.","\u0003אמר רבא: מנא אמינא לה\u0004 \u0005[מניין אומר אני אותה,\u0006 את שיטתי\u0005]\u0006 — על פי מעשה שהיה, ש\u0003ר' חייא בר יוסף יהבו ליה זוזי אמלחא\u0004 \u0005[נתנו לו זוזים,\u0006 כסף עבור \u0005מלח]\u0006 שהיה מוכר. \u0003לסוף אייקר מלחא\u0004 \u0005[לבסוף התייקר המלח]\u0006 ורצה ר' חייא בר יוסף לחזור בו מן העסקה. \u0003אתא לקמיה\u0004 \u0005[בא לפני]\u0006 \u0003ר' יוחנן\u0004 לשאול מה יעשה. \u0003אמר ליה\u0004 \u0005[לו] :\u0006 \u0003זיל הב להו\u0004 \u0005[לך תן להם]\u0006 את המלח, \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003לא\u0004 — \u0003קביל עליך \"מי שפרע\".\u0004 ומעתה, \u0003אי אמרת אודועי מודעינן ליה\u0004 \u0005[אם אומר אתה\u0006 שרק \u0005מודיעים אנו לו],\u0006 וכי \u0003ר' חייא בר יוסף בר אודועי\u0004 \u0005[בן הודעה]\u0006 \u0003הוא,\u0004 כלומר, וכי זקוק הוא לכך? הלא הוא יודע בעצמו הלכה זו. ודוחים: \u0003ואלא מאי\u0004 \u0005[מה]\u0006 תאמר — \u0003מילט לייטינן ליה\u0004 \u0005[\u0006ש\u0005מקללים אנו אותו],\u0006 וכי \u0003ר' חייא בר יוסף אתי לקבולי עליה לטותא דרבנן\u0004 \u0005[בא לקבל על עצמו קללת חכמים]?!\u0006","\u0003אלא\u0004 בודאי לא כך בדיוק היה המעשה אלא כך היה: \u0003ר' חייא בר יוסף ערבון הוא דיהבי ליה\u0004 \u0005[שנתנו לו],\u0006 שלא לקנין נתנו לו כסף עבור המלח, אלא נתנו לו ערבון בלבד כדי לחזק את ההתחייבות שהיו חייבים לו. \u0003הוא,\u0004 ר' חייא בר יוסף, \u0003סבר\u0004 \u0005[חשב]:\u0006 \u0003כנגדו הוא קונה.\u0004 כלומר, הערבון יוצר התחייבות כנגד שוויו של הערבון בלבד, ורצה לתת להם מלח בדיוק כנגד כסף הערבון ולא יותר. \u0003ואמר\u0004 לו \u0003ר' יוחנן\u0004 ש\u0003כנגד כולו הוא קונה.\u0004 שכיון שנתנו לו ערבון — חל דין ערבון על כל מה שנתנו לו.","באותו נושא \u0003אתמר\u0004 \u0005[נאמר]\u0006 שנחלקו אמוראים בדבר: \u0003ערבון, רב אומר: כנגדו הוא קונה\u0004 ולא יותר. \u0003ור' יוחנן אמר: כנגד כולו הוא קונה.\u0004","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על כך ממה ששנינו: \u0003הנותן ערבון לחבירו ואמר לו: \"אם אני חוזר בי\u0004 — הרי \u0003ערבוני מחול לך\", והלה,\u0004 המקבל, \u0003אמר לו: \"אם אני אחזור בי אכפול לך ערבונך\"\u0004 — נתקיימו התנאים, אלו \u0003דברי ר' יוסי.\u0004 שלדעת ר' יוסי אם אחד מהם חזר בו עושים לפי תנאם. ומעירים, \u0003ר' יוסי לטעמיה\u0004 \u0005[לטעמו,\u0006 לשיטתו\u0005]\u0006 ש\u0003אמר: אסמכתא קניא\u0004 \u0005[קונה],\u0006 שכל הבטחה כעין זו שיש בה הסכמה לקנסות יוצרת קנין, ואין אומרים שלא היתה כאן התחייבות שלמה.","\u0003ר' יהודה אומר: דיו שיקנה כנגד ערבונו. אמר רבן שמעון בן גמליאל: במה דברים אמורים\u0004 — \u0003בזמן שאמר לו \"ערבוני יקון\"\u0004 \u0005[יקנה]\u0006 \u0003אבל\u0004 אם \u0003מכר לו בית או שדה באלף זוז, ופרע לו מהם חמש מאות זוז\u0004 — \u0003קנה\u0004 הכל, \u0003ומחזיר לו את השאר\u0004 הכסף \u0003אפילו לאחר כמה שנים.\u0004 ושואלים: \u0003מאי לאו\u0004 \u0005[האם לא]\u0006 \u0003הוא הדין למטלטלין,\u0004 שגם שם \u0003בדסתמא קני להו לכולהו\u0004 \u0005[שבסתם\u0006 בלי לפרש \u0005קנה את כולם]\u0006 ולא רק כנגד ערבונו!","ודוחים: \u0003לא, מטלטלין בדסתמא לא קני\u0004 \u0005[ב\u0006דיבור \u0005סתם אינו קונה].\u0006 ושואלים: \u0003ומאי שנא\u0004 \u0005[ומה שונה,\u0006 מה ההבדל\u0005]\u0006 לענין זה בין קרקע למטלטלים? ומסבירים: \u0003קרקע דבכספא קני ליה\u0004 \u0005[שבכסף\u0006 וא \u0005קונה אותה]\u0006 \u0003ממש\u0004 אף במתן ערבון הרי \u0003קני ליה לכולה\u0004 \u0005[קונה\u0006 הוא \u0005את כולה],\u0006 ואילו \u0003מטלטלי דלא קני\u0004 \u0005[מטלטלים שאין קונה]\u0006 בכסף קנין גמור \u0003אלא לקבולי\u0004 \u0005[לקבל\u0006 על עצמו\u0005]\u0006 \u0003\"מי שפרע\"\u0004 — \u0003לא קני ליה כוליה\u0004 \u0005[אינו קונה את כולו].\u0006","ומציעים: \u0003לימא כתנאי\u0004 \u0005[האם לומר\u0006 שכבר נשנה ענין זה \u0005כ\u0006מחלוקת \u0005תנאים]\u0006 ששנינו: \u0003המלוה את חבירו על המשכון,\u0004 ו\u0003נכנסה\u0004 שנת \u0003שמיטה, אף על פי שאינו שוה אלא פלג\u0004 (חצי) מן הכסף — \u0003אינו משמט\u0004 הלוואה זו כלל, אלו \u0003דברי רבן שמעון בן גמליאל.\u0004 ואילו \u0003ר' יהודה הנשיא אומר: אם היה\u0004 ה\u0003משכון\u0004 שווה \u0003כנגד הלואתו\u0004 — \u0003אינו משמט, ואם לאו\u0004 \u0005[לא]\u0006","— משמט. ומעתה נברר; \u0003מאי\u0004 \u0005[מה]\u0006 פירוש \u0003\"אינו משמט\" דקאמר\u0004 \u0005[שאמר]\u0006 \u0003רבן שמעון בן גמליאל? אילימא\u0004 \u0005[אם תאמר]\u0006 שהכוונה היא ש\u0003כנגדו\u0004 אינו משמט, ולא הכל, האם \u0003מכלל\u0004 הדברים תאמר ש\u0003ר' יהודה הנשיא סבר\u0004 \u0005[סבור]:\u0006 \u0003להך פלגא נמי\u0004 \u0005[שאת החצי הזה גם כן]\u0006 \u0003משמט,\u0004 כיצד אפשר לומר כך? והלא היה כאן משכון!"],["\u0003אלא משכון דנקיט\u0004 \u0005[שמחזיק]\u0006 \u0003למה ליה\u0004 \u0005[לו]?\u0006 ללא ספק לקח אותו כדי להיות בטוח שאכן יקבל את כספו. \u0003אלא לאו שמע מיניה\u0004 \u0005[האם לא תלמד מכאן]\u0006 כי \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"אינו משמט\" דקאמר\u0004 \u0005[שאמר]\u0006 \u0003רבן שמעון בן גמליאל\u0004 — \u0003אינו משמט בכולו, ומאי\u0004 \u0005[ומה\u0006 פירוש\u0005]\u0006 \u0003\"משמט\" דקאמר\u0004 \u0005[שאומר]\u0006 \u0003ר' יהודה הנשיא\u0004 — \u0003להך פלגא\u0004 \u0005[לאותו חצי]\u0006 ש\u0003לא נקיט עליה\u0004 \u0005[מחזיק עליו]\u0006 \u0003משכון.\u0004","\u0003ובהא קמיפלגי\u0004 \u0005[ו\u0006בנושא \u0005זה חלוקים הם],\u0006 ש\u0003רבן שמעון בן גמליאל סבר\u0004 \u0005[סבור]:\u0006 \u0003כנגד כולו הוא קונה, ור' יהודה הנשיא סבר\u0004 \u0005[סבור]:\u0006 \u0003כנגדו הוא קונה.\u0004 ואם כן מחלוקת תנאים היא בשאלה זו.","ודוחים: \u0003לא, מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"אינו משמט\"\u0004 ש\u0003אמר רבן שמעון בן גמליאל\u0004 — כוונתו \u0003להך פלגא דנקיט עליה\u0004 \u0005[לאותו חצי שמחזיק עליו]\u0006 \u0003משכון,\u0004 ואכן, \u0003מכלל\u0004 הדברים אפשר ללמוד ש\u0003ר' יהודה הנשיא סבר\u0004 \u0005[סבור]:\u0006 \u0003להך פלגא דנקיט עליה\u0004 \u0005[לאותו חצי שמחזיק עליו]\u0006 \u0003משכון נמי\u0004 \u0005[גם כן]\u0006 \u0003משמט.\u0004 ומה ששאלת \u0003אלא משכון\u0004 ש\u0003נקיט\u0004 \u0005[ש\u0006הוא \u0005מחזיק\u0006 בו\u0005]\u0006 \u0003למה\u0004 \u0005[לו]?\u0006 — התשובה היא כי הוא \u0003לזכרון דברים בעלמא\u0004 \u0005[בלבד],\u0006 כלומר, המשכון בא לחיזוק ההבטחה שאכן ישולם החוב, ואולם המשכון עצמו אינו עושה כל מעשה קנין.","מסופר: \u0003רב כהנא יהבי ליה זוזי אכיתנא, לסוף אייקר כיתנא\u0004 \u0005[נתנו לו כסף עבור פשתן ולבסוף התייקר הפשתן].\u0006 \u0003אתא לקמיה\u0004 \u0005[בא לפני]\u0006 \u0003רב\u0004 לשאול מה יעשה. \u0003אמר ליה\u0004 \u0005[לו] :\u0006 \u0003במאי דנקיטת זוזי\u0004 \u0005[במה,\u0006 כמות \u0005ש\u0006כבר \u0005קבלת זוזים,\u0006 כסף\u0005]\u0006 — \u0003הב להו\u0004 \u0005[תן להם],\u0006 \u0003ואידך\u0004 \u0005[והשאר]\u0006 — הבטחה ב\u0003דברים\u0004 בלבד \u0003נינהו\u0004 \u0005[הם],\u0006 ו\u0003דברים אין בהן משום מחוסרי אמנה.\u0004 שמי שחוזר בו מדיבור בלבד שלא נעשה עמו מעשה קנין, אין בכך אפילו חסרון אמנה.","\u0003דאיתמר\u0004 \u0005[שנאמר]\u0006 שנחלקו אמוראים בכך; \u0003דברים,\u0004 כלומר, הבטחה בדברים בלבד, בלא קנין \u0003רב אמר: אין בהן משום מחוסרי אמנה\u0004 אם חוזר בו. \u0003ור' יוחנן אמר: יש בהם משום מחוסרי אמנה.\u0004","\u0003מיתיבי\u0004 \u0005[מקשים\u0006 על כך\u0005]\u0006 ממה \u0003ששנינו ש\u0004\u0003ר' יוסי בר' יהודה אומר: מה תלמוד לומר\u0004 (מה מלמדנו) הכתוב \u0003\"\u0004ו\u0003הין צדק\u0004 יהיה לכם\u0003\"\u0004 (ויקרא יט, לו), \u0003והלא \"הין\" בכלל איפה היה,\u0004 ומדוע יש לומר גם \"איפת צדק\" (שם) וגם \"הין צדק\"? \u0003אלא לומר לך\u0004 ברמז: \u0003שיהא הן שלך צדק, ולאו שלך צדק.\u0004 משמע, שמצוה היא שיקיים אדם מה שהבטיח! \u0003אמר אביי:\u0004 הכתוב \u0003ההוא\u0004 כוונתו \u0003שלא ידבר אחד בפה ואחד בלב.\u0004 כלומר, שאסור לאדם שיבטיח ובאותה שעה יתכוון בלבו שלא לקיים. אבל אם באותה שעה בלבו לקיים, ואחר כך נשתנו התנאים וחזר בו — אין בכך משום חסרון יושר.","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 ממה ששנינו ש\u0003ר' שמעון אומר: אף על פי שאמרו\u0004 שה\u0003טלית קונה דינר זהב,\u0004 שאם משך טלית נקנה הדינר, \u0003ואין דינר זהב קונה טלית, מכל מקום כך הלכה, אבל אמרו: מי שפרע מאנשי דור המבול ומאנשי דור הפלגה הוא עתיד ליפרע ממי שאינו עומד בדיבורו.\u0004 משמע שבכל מקרה, החוזר בו עובר משום חסרון אמנה!","ומסבירים: \u0003תנאי היא\u0004 \u0005[\u0006מחלוקת \u0005תנאים היא]\u0006 בענין זה. שכן שנינו במשנה: \u0003מעשה בר' יוחנן בן מתיא שאמר לבנו: צא ושכור לנו פועלים. הלך\u0004 הבן \u0003ופסק להם מזונות\u0004 בתוך תנאי השכירות, ולא פירש איזה מזונות. \u0003וכשבא אצל אביו אמר לו\u0004 האב: \u0003בני, אפילו אתה עושה להם כסעודת שלמה בשעתו לא יצאת ידי חובתך עמהם, שהן בני אברהם יצחק ויעקב\u0004 ולפי כבודם ראויה להם כל סעודה שבעולם. \u0003אלא עד\u0004 (כל עוד) \u0003שלא יתחילו במלאכה צא ואמור להם\u0004 שמה שאמרת \"מזונות\", כוונתך: \u0003על מנת שאין לכם עלי אלא פת וקטנית בלבד,\u0004 כנהוג.","ויש לומר: \u0003ואי סלקא דעתך\u0004 \u0005[ואם עולה על דעתך]\u0006 לומר ששינוי ב\u0003דברים יש בהן משום מחוסרי אמנה, היכי\u0004 \u0005[איך]\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003זיל הדר\u0004 \u0005[לך חזור]\u0006 \u0003בך?\u0004 ומשיבים: זו אינה קושיה, כי \u0003שאני התם\u0004 \u0005[שונה שם]\u0006 שה\u0003פועלים גופייהו\u0004 \u0005[עצמם]\u0006 \u0003לא סמכא דעתייהו\u0004 \u0005[דעתם]\u0006 עליו. \u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 — \u0003מידע ידעי\u0004 \u0005[יודעים הם]\u0006 ש\u0003על אבוה\u0004 \u0005[אביו]\u0006 \u0003סמך.\u0004","ומקשים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 \u0003אפילו התחילו במלאכה נמי\u0004 \u0005[גם כן]\u0006 אינם סומכים עליו, ומדוע אמר לו שיאמר להם לפני שהתחילו? ומשיבים: אם \u0003התחילו במלאכה ודאי סמכי דעתייהו\u0004 \u0005[סומכת דעתם],\u0006 \u0003אמרו\u0004 \u0005[אומרים הם]:\u0006 ודאי \u0003מימר אמר קמיה דאבוה וניחא ליה\u0004 \u0005[אומרים הם\u0006 ודאי \u0005אמר לפני אביו ונוח בעיניו]\u0006 ולכן הוצרך להודיעם קודם.","ושואלים: \u0003ומי\u0004 \u0005[והאם]\u0006 \u0003אמר ר' יוחנן הכי\u0004 \u0005[כך]\u0006 שחזרה מדברים יש בה משום מחוסרי אמנה? \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רבה בר בר חנה אמר ר' יוחנן: האומר לחבירו מתנה אני נותן לך\u0004 — \u0003יכול לחזור בו.\u0004 ותחילה תוהים על הלשון \u0003\"יכול\"\u0004 — \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005]\u0006 שאם הוא רוצה לחזור בו יכול הוא לחזור ואי אפשר לכפותו לתת. \u0003אלא\u0004 כך צריך לומר: \u0003מותר לחזור בו.\u0004 משמע שדברים אין בהם משום מחוסר אמנה! \u0003אמר רב פפא: ומודה ר' יוחנן במתנה מועטת דסמכא דעתייהו\u0004 \u0005[שסומכת דעתם]\u0006 של המקבלים, שוודאי יקיים דבריו, אבל במתנה מרובה יודעים שאדם עשוי להתחרט, ואין רואים בכך החלטה גמורה.","ומעירים: \u0003הכי נמי מסתברא\u0004 \u0005[כך גם כן מסתבר]\u0006 להסביר את דברי ר' יוחנן. ש\u0003אמר ר' אבהו אמר ר' יוחנן: ישראל שאמר לבן לוי: כור מעשר יש לך בידי\u0004 שהפרשתי מתבואתי, והרי אני נותן אותו לך. \u0003בן לוי רשאי לעשותו\u0004 את הכור הזה או חלקו ל\u0003תרומת מעשר על מקום אחר\u0004 שקיבל בו מעשר, שיכול לסמוך על המבטיח שלא ישנה בדיבורו. ומעתה \u0003אי אמרת בשלמא לא מצי למיהדר ביה\u0004 \u0005[נניח אם אתה אומר שאינו יכול לחזור בו]\u0006 — \u0003משום הכי רשאי\u0004 \u0005[כך רשאי].\u0006 \u0003אלא אי אמרת מצי למיהדר ביה, אמאי\u0004 \u0005[אם אומר אתה שיכול לחזור בו, מדוע]\u0006 \u0003רשאי\u0004 הוא לעשותו תרומה? שמא יחזור בו הנותן, ואז \u0003אישתכח דקא אכיל טבלים\u0004 \u0005[ימצא שהוא אוכל טבלים]!\u0006","ומשיבים: \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 — \u0003כגון שנטלו ממנו\u0004 הלוי \u0003וחזר והפקידו אצלו.\u0004","ומקשים: \u0003אי הכי אימא סיפא\u0004 \u0005[אם כך אמור את סופה\u0006 של ההלכה\u0005]:\u0006 \u0003נתנו לבן לוי אחר\u0004 — \u0003אין לו עליו אלא תרעומת. ואי סלקא דעתך\u0004 \u0005[אם עולה על דעתך]\u0006 לומר שמדובר כאן \u0003כגון שנטלו ממנו וחזר והפקידו אצלו, אמאי\u0004 \u0005[מדוע]\u0006 \u0003אין לו עליו אלא תרעומת? כיון דמשכיה\u0004 \u0005[שמשכו]\u0006 נעשה כשלו, ואם כן חוב \u0003ממונא אית ליה גביה\u0004 \u0005[יש לו אצלו]!\u0006 \u0003אלא לאו שמע מינה\u0004 \u0005[האם לא תלמד מכן]\u0006 שמדובר כאן באופן ש\u0003לא נטלו.\u0004 ומסבירים: אכן, \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שהיתה כאן הבטחה בלבד, ומכאן שאף הפרת הבטחה יש בה משום חסרון לאמונה.","מסופר, \u0003ההוא גברא דיהיב זוזי אשומשמי\u0004 \u0005[אדם אחד נתן כספים עבור שומשמים].\u0006 \u0003לסוף אייקר שומשמי\u0004 \u0005[לבסוף התייקרו השומשמים]\u0006 \u0003הדרו בהו\u0004 \u0005[\u0006ו\u0005חזרו בהם]\u0006 האנשים \u0003ואמרו ליה\u0004 \u0005[לו]:\u0006 \u0003לית לן שומשמי, שקול זוזך\u0004 \u0005[אין לנו שומשמים קח את כספך].\u0006 \u0003לא שקיל זוזיה איגנוב\u0004 \u0005[לקח\u0006 אותו אדם \u0005את כספו ונגנב\u0006 הכסף\u0005].\u0006 \u0003אתו לקמיה\u0004 \u0005[באו לפני]\u0006 \u0003רבא\u0004 לדון. \u0003אמר ליה\u0004 \u0005[לו]\u0006 רבא לקונה: \u0003כיון דאמרי\u0004 \u0005[שאמרו]\u0006 \u0003לך שקול זוזך\u0004 \u0005[קח את כספך]\u0006 \u0003ולא שקלית\u0004 \u0005[לקחת],\u0006 \u0003לא מבעיא\u0004 \u0005[נצרכה\u0006 לומר\u0005]\u0006 שכ \u0003שומר שכר דלא הוי\u0004 \u0005[אינו\u0006 נחשב\u0005],\u0006 \u0003אלא אפילו שומר חנם נמי לא הוי\u0004 \u0005[גם כן איננו\u0006 נחשב\u0005].\u0006 \u0003אמרו ליה רבנן\u0004 \u0005[חכמים]\u0006 \u0003לרבא:\u0004 \u0003והא בעי לקבולי עליה\u0004 \u0005[והרי צריך\u0006 זה שחזר בו \u0005לקבל על עצמו]\u0006 \u0003\"מי שפרע\"? אמר להו הכי נמי\u0004 \u0005[כך הוא גם כן]\u0006 שיקבל \"מי שפרע\", — או ישלם.","\u0003אמר רב פפי, אמר לי רבינא: לדידי\u0004 \u0005[לי,\u0006 עצמי\u0005]\u0006 \u0003אמר לי ההוא מרבנן\u0004 \u0005[אחד החכמים]\u0006 \u0003ורב טבות שמיה\u0004 \u0005[שמו],\u0006 \u0003ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 ש\u0003רב שמואל בר זוטרא שמיה\u0004 \u0005[שמו],\u0006 והוא היה אדם כזה \u0003דאי הוו יהבי ליה\u0004 \u0005[שאם היו נותנים לו]\u0006 \u0003כל חללא דעלמא\u0004 \u0005[חלל העולם]\u0006 \u0003לא הוי קא משני בדבוריה\u0004 \u0005[היה משנה בדיבורו].\u0006 וסיפר: \u0003בדידי הוה עובדא ההוא יומא אפניא דמעלי שבתא הוה\u0004 \u0005[בי היה מעשה, אותו יום ערב שבת בין השמשות היה],\u0006 \u0003והוה יתיבנא ואתא ההוא גברא וקאי אבבא\u0004 \u0005[הייתי יושב ובא אדם אחד ועמד בפתח].\u0006 \u0003אמר לי: אית לך שומשמי לזבוני\u0004 \u0005[יש לך שומשמין למכור]?\u0006"],["\u0003אמרי ליה\u0004 \u0005[אמרתי לו]:\u0006 \u0003לא.\u0004 \u0003אמר לי: ליהוו הנך זוזי\u0004 \u0005[יהיו זוזים אלה]\u0006 \u0003בפקדון גבך\u0004 \u0005[אצלך],\u0006 \u0003דהא חשכה\u0004 \u0005[שהרי\u0006 \u0003חשך]\u0004 \u0003לי\u0004 ולא אוכל להביאם הביתה עד שבת. \u0003אמרי ליה\u0004 \u0005[לו]:\u0006 \u0003הא ביתא קמך\u0004 \u0005[הרי הבית לפניך].\u0006 \u0003אותבינהו בביתא ואיגנוב\u0004 \u0005[הניחם בבית ונגנבו].\u0006 \u0003אתא לקמיה\u0004 \u0005[בא\u0006 אותו אדם \u0005לפני]\u0006 \u0003רבא\u0004 לתבוע שיחזירו לו את הכסף. \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003כל\u0004 ביטוי כמו \u0003\"הא ביתא קמך\"\u0004 \u0005[\"הרי הבית לפניך\"],\u0006 \u0003לא מיבעיא\u0004 \u0005[לא נצרכה]\u0006 לומר ש\u0003שומר שכר דלא הוי\u0004 \u0005[איננו],\u0006 \u0003אלא אפילו שומר חנם נמי לא הוי\u0004 \u0005[גם כן איננו].\u0006 אמר רבינא: \u0003אמרי ליה\u0004 \u0005[אמרתי לו]\u0006 לרב טבות: \u0003והא אמרו ליה רבנן\u0004 \u0005[לו חכמים]\u0006 \u0003לרבא: איבעי ליה לקבולי עליה\u0004 \u0005[היה\u0006 \u0003צריך לקבל עליו]\u0004 \u0003\"מי שפרע\".\u0004 \u0003ואמר לי\u0004 רב טבות: \u0003לא היו דברים מעולם.\u0004 כלומר, מעולם לא היה מעשה כזה.","שנינו במשנה ש\u0003ר' שמעון אומר: כל שהכסף בידו ידו על העליונה. תניא\u0004 \u0005[שנוייה\u0006 ברייתא\u0005]:\u0006 \u0003אמר ר' שמעון: אימתי\u0004 הדין כן — \u0003בזמן שהכסף והפירות ביד\u0004 ה\u0003מוכר. אבל\u0004 כאשר ה\u0003כסף ביד\u0004 ה\u0003מוכר ופירות ביד\u0004 ה\u0003לוקח\u0004 — \u0003אינו יכול לחזור בו מפני שכספו בידו.\u0004 ותוהים: \u0003\"בידו\"?!\u0004 הלא \u0003ביד\u0004 ה\u0003מוכר הוא. אלא\u0004 יש לתקן ולומר: \u0003מפני שדמי כספו בידו.\u0004","ושואלים: אם כך, \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005]\u0006 שהרי נעשתה כאן משיכה! \u0003אמר רבא: הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 — במקרה מיוחד, \u0003כגון שהיתה עלייה\u0004 (קומה עליונה של בית) \u0003של\u0004 ה\u0003לוקח מושכרת ביד\u0004 ה\u0003מוכר,\u0004 ושם היו הפירות מאוחסנים. ומסבירים: \u0003טעמא מאי תקינו רבנן\u0004 \u0005[מה טעם תיקנו חכמים]\u0006 ענין זה ש\u0003משיכה\u0004 קונה — \u0003גזירה שמא יאמר לו נשרפו חטיך בעלייה. הכא ברשותיה\u0004 \u0005[כאן\u0006 \u0003ברשותו]\u0004 של ה\u0003לוקח נינהו\u0004 \u0005[הם],\u0006 \u0003אי נפלה\u0004 \u0005[אם תיפול]\u0006 \u0003דליקה באונס\u0004 — \u0003איהו טרח ומייתי לה\u0004 \u0005[הוא יטרח ויביא אותה,\u0006 את תבואתו\u0005].\u0006","מסופר: \u0003ההוא גברא דיהיב זוזי אחמרא\u0004 \u0005[אדם אחד נתן כסף עבור יין].\u0006 \u0003לסוף\u0004 \u0005[לבסוף]\u0006 \u0003שמע דקא בעי למנסביה דבי פרזק רופילא\u0004 \u0005[שרוצים לקחת אותו מבית פרזק שר הצבא].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 לבעל היין: \u0003הב\u0004 \u0005[תן]\u0006 \u0003לי זוזי\u0004 \u0005[את כספי],\u0006 \u0003לא בעינא חמרא\u0004 \u0005[איננו רוצה יין].\u0006 \u0003אתא לקמיה\u0004 \u0005[בא\u0006 הדין \u0005לפני]\u0006 \u0003רב חסדא, אמר ליה\u0004 \u0005[לו]:\u0006 \u0003כדרך שתיקנו משיכה במוכרין כך תיקנו משיכה בלקוחות,\u0004 ולכן, כיון שהקונה עדיין לא משך את היין — רשאי הוא לחזור בו.","\u0003האונאה,\u0004 מהו השיעור שאם טעה או הוטעה בו במקח יכול לטעון שרימו אותו? — הרי זה כשהיה ההבדל \u0003ארבעה כסף מעשרים וארבעה כסף לסלע,\u0004 ולפי החשבון הוא \u0003שתות\u0004 (ששית) \u0003למקח.\u0004 וזה שרומה והוטעה \u0003עד מתי מותר\u0004 לו \u0003להחזיר? עד כדי\u0004 הזמן \u0003שיראה לתגר\u0004 (סוחר) \u0003או לקרובו\u0004 המבין יותר ממנו בטיב ובמחיר. אבל אינו יכול לחזור לאחר זמן זה, שמן הסתם אף שרומה מחל כבר.","מסופר, \u0003הורה ר' טרפון בלוד: \"האונאה שמונה כסף מעשרים וארבעה כסף לסלע, שליש למקח\". ו\u0004מששמעו זאת \u0003שמחו תגרי לוד,\u0004 שעל ידי כך נעשה ביטול המקח דבר פחות מצוי. \u0003אמר להם:\u0004 ואולם לדעתי \u0003כל היום מותר לחזור\u0004 ולא רק כדי שיראה. \u0003אמרו לו\u0004 תגרי לוד: אם כן, \u0003יניח לנו ר' טרפון במקומינו\u0004 כפי שהיינו עד כה \u0003וחזרו לדברי חכמים\u0004 לפסוק לפי שיטתם בכל נושא.","\u0003אתמר\u0004 \u0005[נאמר]\u0006 שנחלקו אמוראים בשאלה זו: \u0003רב אמר:\u0004 בענין אונאה \u0003שתות מקח שנינו,\u0004 שמחשבים את שיעור האונאה בשישית משווי החפץ, ולא מן הכסף ששולם. \u0003ושמואל אמר: שתות מעות נמי\u0004 \u0005[גם כן]\u0006 \u0003שנינו,\u0004 שאם היה ההבדל כדי שישית מהכסף ששולם הרי זו אונאה. ומסבירים את המחלוקת: כיצד? \u0003שוי שיתא בחמשא\u0004 \u0005[\u0006דבר שהיה \u0005שוה ששה\u0006 שמכר \u0005בחמישה],\u0006 או \u0003שוי שיתא\u0004 \u0005[\u0006דבר ש\u0005שווה ששה]\u0006 \u0003בשבעה\u0004 — \u0003כולי עלמא לא פליגי\u0004 \u0005[הכל אינם חולקים]\u0006 ש\u0003בתר\u0004 \u0005[שאחר]\u0006 ה\u0003מקח אזלינן\u0004 \u0005[אנו]\u0006 \u0003ואונאה הויא\u0004 \u0005[היא זו].\u0006 \u0003כי פליגי\u0004 \u0005[כאשר נחלקו]\u0006 רב ושמואל היה זה כאשר מכר דבר \u0003שוי חמשא בשיתא\u0004 \u0005[\u0006ה\u0005שווה חמישה בששה]\u0006 \u0003ושוי\u0004 \u0005[ו\u0006\u0005דבר ה\u0006\u0005שווה]\u0006 \u0003שבעה בשיתא\u0004 \u0005[בששה].\u0006 והמחלוקת היא כיצד מחשבים.","\u0003ל\u0004דעת \u0003שמואל\u0004 ש\u0003אמר:\u0004 כי גם \u0003בתר\u0004 \u0005[אחר]\u0006 ה\u0003מעות אזלינן\u0004 \u0005[אנו הולכים]\u0006 אם כן \u0003אידי ואידי\u0004 \u0005[זה וזה]\u0006 \u0003אונאה הוי\u0004 \u0005[הוא],\u0006 שיש כאן הבדל של שישית לפי חשבון הכסף ששולם. ואילו \u0003לרב\u0004 ש\u0003אמר\u0004 ש\u0003בתר\u0004 \u0005[אחר]\u0006 שווי ה\u0003מקח אזלינן\u0004 \u0005[אנחנו הולכים]\u0006 הרי \u0003שוי חמשא בשיתא\u0004 \u0005[שוה חמישה\u0006 שמכר \u0005בששה]\u0006 \u0003ביטול מקח הויא\u0004 \u0005[הוא],\u0006 שהרי הוא יותר מכדי הונאה (חמישית הערך). ואילו \u0003שוי\u0004 \u0005[\u0006דבר ה\u0005שווה]\u0006 \u0003שבעה בשיתא\u0004 \u0005[בששה]\u0006 הריהו פחות משתות, ואינו הונאה ו\u0003מחילה הויא\u0004 \u0005[הוא].\u0006","\u0003ושמואל אמר: כי אמרינן\u0004 \u0005[כאשר אומרים אנו]\u0006 \u0003מחילה וביטול מקח\u0004 הרי זה \u0003היכא דליכא\u0004 \u0005[במקום שאין]\u0006 \u0003שתות משני צדדים,\u0004 לא מצד הכסף ששולם ולא מצד ערך החפץ. \u0003אבל היכא דאיכא\u0004 \u0005[במקום שיש]\u0006 \u0003שתות\u0004 אפילו \u0003מצד אחד\u0004 — \u0003אונאה הויא\u0004 \u0005[הוא].\u0006 ומעתה מנסים להביא ראיות לשיטות.","\u0003תנן\u0004 \u0005[שנינו\u0006 במשנתנו\u0005]:\u0006 \u0003האונאה ארבעה כסף מעשרים וארבעה כסף לסלע, שתות למקח. מאי לאו\u0004 \u0005[האם לא]\u0006 הכוונה \u0003דזבין\u0004 \u0005[שקנה]\u0006 דבר \u0003שוי\u0004 \u0005[\u0006ה\u0005שווה]\u0006 \u0003עשרים בעשרין וארבעה, ושמע מינה\u0004 \u0005[ולמד מכאן]:\u0006 כי \u0003שתות מעות נמי\u0004 \u0005[גם כן]\u0006 \u0003שנינו,\u0004 וכשמואל! ודוחים: \u0003לא,\u0004 הכוונה היא \u0003דזבין שוי\u0004 \u0005[שמכר\u0006 דבר ה\u0005שווה]\u0006 \u0003עשרים וארבעה בעשרים.\u0004","ושואלים: אם כן \u0003מי נתאנה\u0004 \u0005[רומה]\u0006 בעיסקה זו — ה\u0003מוכר. אימא סיפא\u0004 \u0005[אמור\u0006 אם כן \u0005את סופה]\u0006 של המשנה: \u0003עד מתי מותר להחזיר\u0004 — \u0003בכדי שיראה לתגר או לקרובו.\u0004 ואם זה אינו ברור מעצמו, הרי \u0003אמר רב נחמן: לא שנו אלא לוקח,\u0004 שכיון שהחפץ בידו יכול להראותו מיד, \u0003אבל מוכר\u0004 — \u0003לעולם חוזר.\u0004 שכיון שאין החפץ בידו אינו יכול להראותו, ורק כאשר יזדמן חפץ כעין זה יוכל לעמוד על מחירו. ולכן אם רומה — יכול לחזור לעולם.","\u0003אלא\u0004 יש לחזור מן הפירוש הקודם, ולומר שמדובר באופן \u0003דזבין\u0004 \u0005[שמכר]\u0006 \u0003שוי\u0004 \u0005[\u0006דבר ה\u0005שווה]\u0006 \u0003עשרים וארבעה בעשרין ותמניא\u0004 \u0005[בעשרים ושמונה].\u0006 \u0003תנן\u0004 \u0005[שנינו\u0006 במשנה\u0005]:\u0006 \u0003הורה ר' טרפון בלוד: \"האונאה שמונה כסף מעשרים וארבעה כסף לסלע, שליש למקח\". מאי לאו\u0004 \u0005[האם לא]\u0006 הכוונה \u0003דזבין שוי שיתסרי\u0004 \u0005[שמכר\u0006 דבר \u0005השווה שש עשרה]\u0006 \u0003בעשרים וארבעה? ושמע מינה\u0004 \u0005[ולמד מכאן]\u0006 כי \u0003שליש מעות נמי\u0004 \u0005[גם כן]\u0006 \u0003שנינו,\u0004 כשמואל, ודוחים:","\u0003לא,\u0004 הכוונה היא \u0003דזבין שוי\u0004 \u0005[שמכר\u0006 דבר ה\u0005שווה]\u0006 \u0003עשרים וארבעה בשיתסר\u0004 \u0005[בששה עשר].\u0006 ושואלים: אם כן \u0003מי נתאנה\u0004 \u0005[רומה]\u0006 בזה — ה\u0003מוכר, אימא סיפא\u0004 \u0005[אמור את סופה\u0006 של המשנה\u0005]\u0006 \u0003אמר להם: כל היום מותר לחזור.\u0004 והלא \u0003אמר רב נחמן: לא שנו אלא לוקח, אבל מוכר לעולם חוזר. אלא\u0004 כך יש לפרש: \u0003דזבין\u0004 \u0005[שמכר]\u0006 שווה \u0003עשרים וארבעה בתלתין ותרין\u0004 \u0005[בשלושים ושתים].\u0006","ומעירים, \u0003תניא כוותיה\u0004 \u0005[שנויה\u0006 ברייתא \u0005שיטתו]\u0006 של \u0003שמואל:\u0004 \u0003מי שהוטל עליו\u0004 (שרומה) \u0003ידו על העליונה. כיצד? מכר לו שוה חמשה בששה, מי נתאנה\u0004 (רומה) כאן — \u0003לוקח,\u0004 במקרה זה \u0003יד לוקח על העליונה, רצה\u0004 הלוקח — \u0003אומר\u0004 לו למוכר: \u0003תן לי מעותי\u0004 שרצוני לבטל את המקח, \u0003או תן לי מה שאוניתני\u0004 \u0005[שרימית אותי\u0006 בו\u0005].\u0006 ואולם אם \u0003מכר לו\u0004"]]};
